QT_ISI(22,{"3564":["(Dan barang siapa yang tetap taat) tetap setia (di antara kalian kepada Allah dan Rasul-Nya dan mengerjakan amal yang saleh, niscaya Kami berikan kepadanya pahala dua kali lipat) dua kali lipat pahala yang diterima oleh wanita-wanita yang taat selain kalian. Dan menurut suatu qiraat lafal Ta'malu dan Nu'tihaa dibaca Ya'malu dan Yu'tihaa (dan Kami sediakan baginya rezeki yang mulia) di surga sebagai tambahan pahalanya.",[["۞ وَمَن","Dan sesiapa"],["يَقْنُتْ","adalah taat"],["مِنكُنَّ","antara kamu"],["لِلَّهِ","kepada Allah"],["وَرَسُولِهِۦ","dan Rasul-Nya"],["وَتَعْمَلْ","dan melakukan"],["صَـٰلِحًۭا","kebenaran"],["نُّؤْتِهَآ","Kami akan memberinya"],["أَجْرَهَا","pahala dia"],["مَرَّتَيْنِ","dua kali"],["وَأَعْتَدْنَا","dan telah Kami sediakan"],["لَهَا","untuk dia"],["رِزْقًۭا","suatu peruntukan"],["كَرِيمًۭا","mulia"]]],"3565":["(Hai istri-istri Nabi! Kamu sekalian tidaklah seperti seseorang) yakni segolongan (di antara wanita yang lain, jika kalian bertakwa) kepada Allah, karena sesungguhnya kalian adalah wanita-wanita yang agung. (Maka janganlah kalian tunduk dalam berbicara) dengan kaum laki-laki (sehingga berkeinginan orang yang ada penyakit dalam hatinya) yakni perasaan nifaq (dan ucapkanlah perkataan yang baik) dengan tanpa tunduk.",[["يَـٰنِسَآءَ","Wahai para isteri"],["ٱلنَّبِىِّ","(dari) Nabi"],["لَسْتُنَّ","kamu bukan"],["كَأَحَدٍۢ","seperti sesiapa sahaja"],["مِّنَ","antara"],["ٱلنِّسَآءِ ۚ","kaum wanita"],["إِنِ","Jika"],["ٱتَّقَيْتُنَّ","kamu takut (Allah)"],["فَلَا","maka (buat) jangan"],["تَخْضَعْنَ","menjadi lembut"],["بِٱلْقَوْلِ","dalam ucapan"],["فَيَطْمَعَ","supaya jangan digerakkan dengan keinginan"],["ٱلَّذِى","dia yang"],["فِى","dalam"],["قَلْبِهِۦ","hatinya"],["مَرَضٌۭ","(adalah) penyakit"],["وَقُلْنَ","tetapi katakan"],["قَوْلًۭا","satu perkataan"],["مَّعْرُوفًۭا","sesuai"]]],"3566":["(Dan hendaklah kalian tetap) dapat dibaca Qirna dan Qarna (di rumah kalian) lafal Qarna pada asalnya adalah Aqrarna atau Aqrirna, yang diambil dari kata Qararta atau Qarirta. Kemudian harakat Ra dipindahkan kepada Qaf, selanjutnya huruf Ra dan hamzah Washalnya dibuang sehingga jadilah, Qarna atau Qirna (dan janganlah kalian berhias) asalnya berbunyi Tatabarrajna kemudian salah satu huruf Ta dibuang sehingga jadilah Tabarrajna (sebagaimana orang-orang jahiliah yang dahulu) sebagaimana berhiasnya orang-orang sebelum Islam, yaitu kaum wanita selalu menampakkan kecantikan mereka kepada kaum lelaki. Adapun yang diperbolehkan oleh Islam adalah sebagaimana yang disebutkan di dalam firman-Nya, \".. dan janganlah mereka menampakkan perhiasannya, kecuali yang biasa tampak daripadanya.\" (Q.S. An-Nur, 31). (dan dirikanlah salat, tunaikanlah zakat dan taatilah Allah dan Rasul-Nya. Sesungguhnya Allah bermaksud hendak menghilangkan dosa dari kalian) yakni dosa-dosa, hai (ahlul bait) yakni istri-istri Nabi saw. (dan membersihkan kalian) daripada dosa-dosa itu (sebersih-bersihnya.)",[["وَقَرْنَ","Dan tinggal"],["فِى","dalam"],["بُيُوتِكُنَّ","rumah-rumah kamu"],["وَلَا","dan jangan"],["تَبَرَّجْنَ","tunjukkan diri kamu"],["تَبَرُّجَ","(seperti) paparan"],["ٱلْجَـٰهِلِيَّةِ","(pada zaman) jahiliyah"],["ٱلْأُولَىٰ ۖ","yang dahulu"],["وَأَقِمْنَ","Dan menubuhkan"],["ٱلصَّلَوٰةَ","solat"],["وَءَاتِينَ","dan memberi"],["ٱلزَّكَوٰةَ","zakat"],["وَأَطِعْنَ","dan taat"],["ٱللَّهَ","Allah"],["وَرَسُولَهُۥٓ ۚ","dan Rasul-Nya"],["إِنَّمَا","Hanya"],["يُرِيدُ","Allah berkehendak"],["ٱللَّهُ","Allah berkehendak"],["لِيُذْهِبَ","untuk mengeluarkan"],["عَنكُمُ","daripada kamu"],["ٱلرِّجْسَ","kekotoran itu"],["أَهْلَ","(O) Orang ramai"],["ٱلْبَيْتِ","(dari) Dewan"],["وَيُطَهِّرَكُمْ","Dan untuk menyucikan kamu"],["تَطْهِيرًۭا","(dengan penyucian yang menyeluruh)."]]],"3567":["(Dan ingatlah apa yang dibacakan di rumah kalian dari ayat-ayat Allah) Alquran (dan hikmah) sunah Nabi. (Sesungguhnya Allah adalah Maha Lembut) terhadap kekasih-kekasih-Nya (lagi Maha Mengetahui) terhadap semua makhluk-Nya.",[["وَٱذْكُرْنَ","Dan ingat"],["مَا","apa"],["يُتْلَىٰ","dibacakan"],["فِى","dalam"],["بُيُوتِكُنَّ","rumah-rumah kamu"],["مِنْ","daripada"],["ءَايَـٰتِ","(the) Ayat"],["ٱللَّهِ","(milik) Allah"],["وَٱلْحِكْمَةِ ۚ","dan hikmahnya"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["كَانَ","ialah"],["لَطِيفًا","Maha Halus"],["خَبِيرًا","Maha Mengetahui"]]],"3568":["(Sesungguhnya laki-laki dan perempuan yang muslim, laki-laki dan perempuan yang mukmin, laki-laki dan perempuan yang tetap dalam ketaatannya) (laki-laki dan perempuan yang benar) dalam keimanannya (laki-laki dan perempuan yang sabar) di dalam menjalankan ketaatan (laki-laki yang khusyuk) yang merendahkan diri (dan perempuan yang khusyuk, laki-laki dan perempuan yang bersedekah, laki-laki dan perempuan yang berpuasa, laki-laki dan perempuan yang memelihara kehormatannya) dari hal-hal yang diharamkan (laki-laki dan perempuan yang banyak menyebut nama Allah, Allah telah menyediakan untuk mereka ampunan) dari perbuatan-perbuatan maksiat yang pernah mereka lakukan (dan pahala yang besar) bagi amal ketaatan mereka.",[["إِنَّ","Sesungguhnya"],["ٱلْمُسْلِمِينَ","lelaki Islam"],["وَٱلْمُسْلِمَـٰتِ","dan wanita muslimah"],["وَٱلْمُؤْمِنِينَ","dan orang-orang yang beriman"],["وَٱلْمُؤْمِنَـٰتِ","dan wanita yang beriman"],["وَٱلْقَـٰنِتِينَ","dan orang-orang yang taat"],["وَٱلْقَـٰنِتَـٰتِ","dan wanita yang taat"],["وَٱلصَّـٰدِقِينَ","dan orang-orang yang benar"],["وَٱلصَّـٰدِقَـٰتِ","dan wanita yang benar"],["وَٱلصَّـٰبِرِينَ","dan lelaki yang sabar"],["وَٱلصَّـٰبِرَٰتِ","dan wanita yang sabar"],["وَٱلْخَـٰشِعِينَ","dan lelaki yang hina"],["وَٱلْخَـٰشِعَـٰتِ","dan wanita yang rendah hati"],["وَٱلْمُتَصَدِّقِينَ","dan orang-orang yang bersedekah"],["وَٱلْمُتَصَدِّقَـٰتِ","dan wanita yang bersedekah"],["وَٱلصَّـٰٓئِمِينَ","dan orang-orang yang berpuasa"],["وَٱلصَّـٰٓئِمَـٰتِ","dan wanita yang berpuasa"],["وَٱلْحَـٰفِظِينَ","dan orang-orang yang menjaga"],["فُرُوجَهُمْ","kesucian mereka"],["وَٱلْحَـٰفِظَـٰتِ","dan wanita-wanita yang memelihara (nya)"],["وَٱلذَّٰكِرِينَ","dan lelaki yang ingat"],["ٱللَّهَ","Allah"],["كَثِيرًۭا","banyak"],["وَٱلذَّٰكِرَٰتِ","dan wanita yang ingat"],["أَعَدَّ","Allah dah sediakan"],["ٱللَّهُ","Allah dah sediakan"],["لَهُم","bagi mereka"],["مَّغْفِرَةًۭ","pengampunan"],["وَأَجْرًا","dan ganjaran"],["عَظِيمًۭا","yang besar"]]],"3569":["(Dan tidaklah patut bagi laki-laki yang Mukmin dan tidak pula bagi perempuan yang Mukmin, apabila Allah dan Rasul-Nya telah menetapkan suatu ketetapan akan ada) Yakuuna dapat dibaca Takuuna (bagi mereka pilihan yang lain) (tentang urusan mereka) yang berbeda dengan apa yang telah ditetapkan oleh Allah dan Rasul-Nya. Ayat ini diturunkan berkenaan dengan Abdullah bin Jahsy beserta saudara perempuannya yang bernama Zainab; Nabi saw. melamarnya untuk dikawinkan kepada Zaid bin Haritsah, lalu keduanya tidak menyukai hal tersebut ketika keduanya mengetahui bahwa Nabi melamar saudara perempuannya bukanlah untuk dirinya sendiri, melainkan untuk anak angkatnya yaitu Zaid bin Haritsah. Akan tetapi setelah turun ayat ini keduanya menjadi rela. (Dan barang siapa mendurhakai Allah dan Rasul-Nya maka sungguh dia telah sesat, sesat yang nyata) nyata sesatnya. Kemudian Nabi mengawinkan Zainab binti Jahsy dengan Zaid. Akan tetapi sesudah beberapa waktu dalam diri Zaid timbul rasa tidak senang terhadap istrinya itu, lalu ia berkata kepada Nabi saw. bahwa ia bermaksud untuk menalaknya. Maka Nabi saw. menjawab, \"Peganglah istrimu itu di dalam pemeliharaanmu\" sebagaimana yang disitir oleh firman selanjutnya.",[["وَمَا","Dan tidak"],["كَانَ","(ia) ialah"],["لِمُؤْمِنٍۢ","untuk lelaki yang beriman"],["وَلَا","dan bukan"],["مُؤْمِنَةٍ","(untuk) wanita yang beriman"],["إِذَا","apabila"],["قَضَى","Allah dah tentukan"],["ٱللَّهُ","Allah dah tentukan"],["وَرَسُولُهُۥٓ","dan Rasul-Nya"],["أَمْرًا","sesuatu perkara"],["أَن","bahawa"],["يَكُونَ","(ada) sepatutnya"],["لَهُمُ","bagi mereka"],["ٱلْخِيَرَةُ","(sebarang) pilihan"],["مِنْ","tentang"],["أَمْرِهِمْ ۗ","urusan mereka"],["وَمَن","Dan sesiapa"],["يَعْصِ","ingkar"],["ٱللَّهَ","Allah"],["وَرَسُولَهُۥ","dan Rasul-Nya"],["فَقَدْ","sudah tentu"],["ضَلَّ","dia (telah) sesat"],["ضَلَـٰلًۭا","(menjadi) kesilapan"],["مُّبِينًۭا","yang nyata"]]],"3570":["(Dan ketika) ingatlah ketika (kamu berkata kepada orang yang Allah telah melimpahkan nikmat kepadanya) yakni nikmat Islam (dan kamu juga telah memberi nikmat kepadanya,) dengan memerdekakannya, yang dimaksud adalah Zaid bin Haritsah, dahulu pada zaman jahiliah dia adalah tawanan kemudian ia dibeli oleh Rasulullah, lalu dimerdekakan dan diangkat menjadi anak angkatnya sendiri (\"Tahanlah terus istrimu dan bertakwalah kepada Allah\") dalam hal menalaknya (sedangkan kamu menyembunyikan di dalam hatimu apa yang Allah akan menyatakannya) akan membeberkannya, yaitu perasaan cinta kepada Zainab binti Jahsy, dan kamu berharap seandainya Zaid menalaknya, maka kamu akan menikahinya (dan kamu takut kepada manusia) bila mereka mengatakan bahwa dia telah menikahi bekas istri anaknya (sedangkan Allahlah yang lebih berhak untuk kamu takuti) dalam segala hal dan dalam masalah menikahinya, dan janganlah kamu takuti perkataan manusia. Kemudian Zaid menalak istrinya dan setelah idahnya habis, Allah swt. berfirman, (\"Maka tatkala Zaid telah mengakhiri keperluan terhadap istrinya) yakni kebutuhannya (Kami kawinkan kamu dengan dia) maka Nabi saw. langsung mengawininya tanpa meminta persetujuannya dulu, kemudian beliau membuat walimah buat kaum Muslimin dengan hidangan roti dan daging yang mengenyangkan mereka (supaya tidak ada keberatan bagi orang Mukmin untuk mengawini istri-istri anak-anak angkat mereka, apabila anak-anak angkat itu telah menyelesaikan keperluannya daripada istrinya. Dan adalah ketetapan Allah itu) apa yang telah dipastikan oleh-Nya (pasti terjadi.\")",[["وَإِذْ","Dan apabila"],["تَقُولُ","kamu kata"],["لِلَّذِىٓ","kepada yang satu"],["أَنْعَمَ","Allah kurniakan nikmat"],["ٱللَّهُ","Allah kurniakan nikmat"],["عَلَيْهِ","pada dia"],["وَأَنْعَمْتَ","dan kamu telah memberi nikmat"],["عَلَيْهِ","pada dia"],["أَمْسِكْ","Simpan"],["عَلَيْكَ","kepada diri sendiri"],["زَوْجَكَ","isteri kamu"],["وَٱتَّقِ","dan ketakutan"],["ٱللَّهَ","Allah"],["وَتُخْفِى","Tapi kamu sembunyikan"],["فِى","dalam"],["نَفْسِكَ","diri sendiri"],["مَا","apa"],["ٱللَّهُ","Allah"],["مُبْدِيهِ","(adalah) mendedahkan"],["وَتَخْشَى","Dan kamu takut"],["ٱلنَّاسَ","manusia"],["وَٱللَّهُ","sedangkan Allah"],["أَحَقُّ","mempunyai lebih hak"],["أَن","bahawa"],["تَخْشَىٰهُ ۖ","kamu (hendaklah) takut kepada-Nya"],["فَلَمَّا","Maka apabila"],["قَضَىٰ","tamat"],["زَيْدٌۭ","Zaid"],["مِّنْهَا","daripada dia"],["وَطَرًۭا","perlu (formaliti)"],["زَوَّجْنَـٰكَهَا","Kami kahwinkan dia dengan kamu"],["لِكَىْ","supaya"],["لَا","tidak"],["يَكُونَ","ada"],["عَلَى","pada"],["ٱلْمُؤْمِنِينَ","orang yang beriman"],["حَرَجٌۭ","sebarang ketidakselesaan"],["فِىٓ","tentang"],["أَزْوَٰجِ","para isteri"],["أَدْعِيَآئِهِمْ","(dari) anak angkat mereka"],["إِذَا","apabila"],["قَضَوْا۟","mereka telah berakhir"],["مِنْهُنَّ","daripada mereka"],["وَطَرًۭا ۚ","perlu (formaliti)"],["وَكَانَ","Dan adakah"],["أَمْرُ","(the) Perintah"],["ٱللَّهِ","(milik) Allah"],["مَفْعُولًۭا","dicapai"]]],"3571":["(Tidak ada suatu keberatan pun atas Nabi tentang apa yang telah ditetapkan) yang telah dihalalkan (Allah baginya, sebagai sunah Allah) lafal Sunatallah dinashabkan setelah huruf Jarnya dicabut (pada orang-orang yang telah berlalu dahulu) dari kalangan para nabi, yaitu bahwasanya tidak ada dosa bagi mereka dalam hal tersebut sebagai kemurahan bagi mereka dalam masalah nikah. (Dan adalah ketetapan Allah itu) yakni keputusan-Nya (suatu ketetapan yang pasti berlaku) pasti terlaksana.",[["مَّا","Tidak"],["كَانَ","(boleh) ada"],["عَلَى","ke atas"],["ٱلنَّبِىِّ","Nabi"],["مِنْ","sebarang"],["حَرَجٍۢ","ketidakselesaan"],["فِيمَا","pada apa"],["فَرَضَ","Allah telah mewajibkan"],["ٱللَّهُ","Allah telah mewajibkan"],["لَهُۥ ۖ","pada dia"],["سُنَّةَ","(Itulah) Jalan"],["ٱللَّهِ","(milik) Allah"],["فِى","tentang"],["ٱلَّذِينَ","orang yang"],["خَلَوْا۟","meninggal dunia"],["مِن","sebelum"],["قَبْلُ ۚ","sebelum"],["وَكَانَ","Dan adakah"],["أَمْرُ","(the) Perintah"],["ٱللَّهِ","(milik) Allah"],["قَدَرًۭا","sebuah dekri"],["مَّقْدُورًا","ditakdirkan"]]],"3572":["(Yaitu orang-orang) lafal Al Ladziina menjadi Na'at atau sifat dari lafal Al Ladziina yang sebelumnya (yang menyampaikan risalah-risalah Allah, mereka takut kepada-Nya, dan mereka tiada merasa takut kepada seorang pun selain kepada Allah) mereka tidak takut kepada perkataan manusia dalam hal melaksanakan apa yang telah dihalalkan oleh Allah buat mereka. (Dan cukuplah Allah sebagai pembuat perhitungan) yakni yang memelihara amal-amal makhluk-Nya dan yang menghisab mereka.",[["ٱلَّذِينَ","Orang yang"],["يُبَلِّغُونَ","menyampaikan"],["رِسَـٰلَـٰتِ","(the) Mesej"],["ٱللَّهِ","(milik) Allah"],["وَيَخْشَوْنَهُۥ","dan takut kepada-Nya"],["وَلَا","dan jangan"],["يَخْشَوْنَ","bertakwa"],["أَحَدًا","sesiapa sahaja"],["إِلَّا","kecuali"],["ٱللَّهَ ۗ","Allah"],["وَكَفَىٰ","Dan cukuplah Allah"],["بِٱللَّهِ","Dan cukuplah Allah"],["حَسِيبًۭا","(sebagai) seorang yang membuat perhitungan"]]],"3573":["(Muhammad itu sekali-kali bukanlah bapak dari seorang laki-laki di antara kalian) dia bukan bapak Zaid, Zaid bukanlah anaknya, maka tidak diharamkan baginya untuk mengawini bekas istri anak angkatnya yaitu Zainab (tetapi dia) adalah (Rasulullah dan penutup nabi-nabi) artinya tidak akan lahir lagi nabi sesudahnya. Dan menurut suatu qiraat dibaca Khataman Nabiyyiina, sama dengan alat untuk mencap atau cincin, yang maksudnya sesudah dia para nabi dilak atau ditutup. (Dan adalah Allah Maha Mengetahui segala sesuatu) antara lain Dia mengetahui bahwa tidak akan ada nabi lagi sesudah Nabi Muhammad saw. seumpama Nabi Isa turun nanti, maka ia akan memerintah dengan memakai syariat Nabi Muhammad.",[["مَّا","Tidak"],["كَانَ","ialah"],["مُحَمَّدٌ","Muhammad"],["أَبَآ","(si) bapa"],["أَحَدٍۢ","(dari) sesiapa sahaja"],["مِّن","daripada"],["رِّجَالِكُمْ","anak buah kamu"],["وَلَـٰكِن","tetapi"],["رَّسُولَ","(dia adalah) Rasul"],["ٱللَّهِ","(milik) Allah"],["وَخَاتَمَ","dan Meterai"],["ٱلنَّبِيِّـۧنَ ۗ","(dari) para Nabi"],["وَكَانَ","Dan Allah adalah"],["ٱللَّهُ","Dan Allah adalah"],["بِكُلِّ","daripada setiap"],["شَىْءٍ","perkara"],["عَلِيمًۭا","Maha Mengetahui"]]],"3574":["(Hai orang-orang yang beriman! Berzikirlah dengan menyebut nama Allah, zikir yang sebanyak-banyaknya.)",[["يَـٰٓأَيُّهَا","Wahai orang yang beriman"],["ٱلَّذِينَ","Wahai orang yang beriman"],["ءَامَنُوا۟","Wahai orang yang beriman"],["ٱذْكُرُوا۟","Ingat"],["ٱللَّهَ","Allah"],["ذِكْرًۭا","(dengan) zikir"],["كَثِيرًۭا","banyak"]]],"3575":["(Dan bertasbihlah kepada-Nya di waktu pagi dan petang) yakni pada permulaan siang dan akhir siang.",[["وَسَبِّحُوهُ","Dan bertasbihlah kepada-Nya"],["بُكْرَةًۭ","pagi"],["وَأَصِيلًا","dan petang"]]],"3576":["(Dialah Yang memberi rahmat kepada kalian) yang membelaskasihani kalian (dan malaikat-Nya) memohonkan ampunan buat kalian (supaya Dia mengeluarkan kalian) supaya Dia terus menerus mengeluarkan kalian (dari kegelapan) yakni kekafiran (kepada cahaya) yaitu keimanan. (Dan adalah Dia Maha Penyayang kepada orang-orang yang beriman).",[["هُوَ","Dia"],["ٱلَّذِى","(ialah) Yang"],["يُصَلِّى","mengirimkan rahmat-Nya"],["عَلَيْكُمْ","ke atas kamu"],["وَمَلَـٰٓئِكَتُهُۥ","dan MalaikatNya"],["لِيُخْرِجَكُم","supaya Dia mengeluarkan kamu"],["مِّنَ","daripada"],["ٱلظُّلُمَـٰتِ","kegelapan[es]"],["إِلَى","kepada"],["ٱلنُّورِ ۚ","cahaya itu"],["وَكَانَ","Dan Dia adalah"],["بِٱلْمُؤْمِنِينَ","kepada orang yang beriman"],["رَحِيمًۭا","Penyayang"]]],"3577":["(Salam penghormatan kepada mereka) dari Allah swt. (pada hari mereka menemui-Nya ialah \"Salaam\") melalui lisan Malaikat (dan Dia menyediakan pahala yang mulia bagi mereka) yaitu surga.",[["تَحِيَّتُهُمْ","salam mereka"],["يَوْمَ","(pada) hari"],["يَلْقَوْنَهُۥ","mereka akan menemui-Nya"],["سَلَـٰمٌۭ ۚ","(akan menjadi), \"Kedamaian"],["وَأَعَدَّ","dan Dia telah menyediakan"],["لَهُمْ","bagi mereka"],["أَجْرًۭا","ganjaran"],["كَرِيمًۭا","mulia"]]],"3578":["(Hai Nabi, sesungguhnya Kami mengutusmu untuk jadi saksi) atas orang-orang yang kamu diutus kepada mereka (dan pembawa kabar gembira) bagi orang yang percaya kepadamu, yaitu diberi surga (dan pemberi peringatan) kepada orang yang mendustakanmu, yaitu akan dimasukkan ke dalam neraka.",[["يَـٰٓأَيُّهَا","Wahai Nabi"],["ٱلنَّبِىُّ","Wahai Nabi"],["إِنَّآ","Sesungguhnya Kami"],["أَرْسَلْنَـٰكَ","telah menghantar kamu"],["شَـٰهِدًۭا","(sebagai) saksi"],["وَمُبَشِّرًۭا","dan pembawa berita gembira"],["وَنَذِيرًۭا","dan (sebagai) pemberi amaran"]]],"3579":["(Dan untuk jadi penyeru kepada Allah) untuk taat kepada-Nya (dengan izin-Nya) dengan perintah-Nya (dan untuk jadi pelita yang menerangi) sebagaimana pelita yang memberi petunjuk ke jalan agama Allah.",[["وَدَاعِيًا","Dan sebagai seorang yang menjemput"],["إِلَى","kepada"],["ٱللَّهِ","Allah"],["بِإِذْنِهِۦ","dengan izinNya"],["وَسِرَاجًۭا","dan (sebagai) lampu"],["مُّنِيرًۭا","menerangi"]]],"3580":["(Dan sampaikanlah berita gembira kepada orang-orang Mukmin, bahwa sesungguhnya bagi mereka karunia yang besar dari Allah) yaitu surga.",[["وَبَشِّرِ","Dan sampaikanlah berita gembira"],["ٱلْمُؤْمِنِينَ","(kepada) orang-orang yang beriman"],["بِأَنَّ","bahawa"],["لَهُم","bagi mereka"],["مِّنَ","(adalah) daripada"],["ٱللَّهِ","Allah"],["فَضْلًۭا","sebuah Bounty"],["كَبِيرًۭا","yang besar"]]],"3581":["(Dan janganlah kamu menuruti orang-orang yang kafir dan orang-orang munafik itu) dalam hal-hal yang bertentangan dengan syariatmu (dan janganlah kamu hiraukan) artinya biarkanlah (gangguan mereka) janganlah kamu mengadakan pembalasan terhadap mereka, sampai dengan adanya perintah tentang apa yang harus kamu lakukan terhadap mereka (dan bertawakallah kepada Allah) Dialah Yang mencukupimu. (Dan cukuplah Allah sebagai Pelindung) maksudnya, serahkanlah semua urusanmu kepada-Nya.",[["وَلَا","Dan jangan"],["تُطِعِ","patuh"],["ٱلْكَـٰفِرِينَ","orang kafir"],["وَٱلْمُنَـٰفِقِينَ","dan orang-orang munafik"],["وَدَعْ","dan tidak mengendahkan"],["أَذَىٰهُمْ","kemudaratan mereka"],["وَتَوَكَّلْ","dan meletakkan kepercayaan kamu"],["عَلَى","dalam"],["ٱللَّهِ ۚ","Allah"],["وَكَفَىٰ","Dan cukuplah Allah"],["بِٱللَّهِ","Dan cukuplah Allah"],["وَكِيلًۭا","(sebagai) Pemegang Amanah"]]],"3582":["(Hai orang-orang yang beriman! Apabila kalian menikahi perempuan-perempuan yang beriman, kemudian kalian ceraikan mereka sebelum kalian mencampurinya) menurut suatu qiraat lafal Tamassuuhunna dibaca Tumaassuuhunna, artinya sebelum kalian menyetubuhi mereka (maka sekali-kali tidak wajib atas mereka idah bagi kalian yang kalian minta menyempurnakannya) yaitu yang kalian hitung dengan quru' atau bilangan yang lainnya. (Maka berilah mereka mutah) artinya berilah mereka uang mutah sebagai pesangon dengan jumlah yang secukupnya. Demikian itu apabila pihak lelaki belum mengucapkan jumlah maharnya kepada mereka, apabila ternyata ia telah mengucapkan jumlahnya, maka uang mutah itu adalah separuh dari mahar yang telah diucapkannya. Demikianlah menurut pendapat Ibnu Abbas kemudian pendapatnya itu dijadikan pegangan oleh Imam Syafii (dan lepaskanlah mereka itu dengan cara yang sebaik-baiknya) yaitu dengan tanpa menimbulkan kemudaratan pada dirinya.",[["يَـٰٓأَيُّهَا","Wahai orang yang beriman"],["ٱلَّذِينَ","Wahai orang yang beriman"],["ءَامَنُوٓا۟","Wahai orang yang beriman"],["إِذَا","Apabila"],["نَكَحْتُمُ","kamu kahwin"],["ٱلْمُؤْمِنَـٰتِ","wanita beriman"],["ثُمَّ","dan kemudian"],["طَلَّقْتُمُوهُنَّ","ceraikan mereka"],["مِن","sebelum"],["قَبْلِ","sebelum"],["أَن","[bahawa]"],["تَمَسُّوهُنَّ","kamu telah menyentuh mereka"],["فَمَا","maka tidak"],["لَكُمْ","bagi kamu"],["عَلَيْهِنَّ","ke atas mereka"],["مِنْ","sebarang"],["عِدَّةٍۢ","tempoh menunggu"],["تَعْتَدُّونَهَا ۖ","(untuk) mengira tentang mereka"],["فَمَتِّعُوهُنَّ","Maka berikanlah rezeki kepada mereka"],["وَسَرِّحُوهُنَّ","dan lepaskan mereka"],["سَرَاحًۭا","(dengan) pelepasan"],["جَمِيلًۭا","kebaikan"]]],"3583":["(Hai Nabi! Sesungguhnya Kami telah menghalalkan bagi kamu istri-istrimu yang telah kamu berikan maskawinnya) yakni maharnya (dan hamba sahaya yang kamu miliki yang termasuk apa yang dikaruniakan oleh Allah kepadamu) dari orang-orang kafir melalui peperangan, yaitu sebagai tawananmu, seperti Shofiah dan Juwairiah (dan demikian pula anak-anak perempuan dari saudara laki-laki bapakmu, anak-anak perempuan dari saudara perempuan bapakmu, anak-anak perempuan dari saudara laki-laki ibumu, dan anak-anak perempuan dari saudara perempuan ibumu yang turut hijrah bersama kamu) berbeda halnya dengan perempuan-perempuan dari kalangan mereka yang tidak ikut berhijrah (dan perempuan Mukmin yang menyerahkan dirinya kepada Nabi kalau Nabi mau mengawininya) bermaksud untuk menikahinya tanpa memakai maskawin (sebagai pengkhususan bagimu, bukan untuk semua orang Mukmin) dalam pengertian nikah yang memakai lafal Hibah tanpa maskawin, (Sesungguhnya Kami telah mengetahui apa yang Kami wajibkan kepada mereka) kepada orang-orang Mukmin (tentang istri-istri mereka) berupa hukum-hukum dan ketentuan-ketentuan, yaitu hendaknya mereka mempunyai istri tidak lebih dari empat orang wanita dan hendaknya mereka tidak melakukan perkawinan melainkan harus dengan adanya seorang wali dan saksi-saksi serta maskawin (dan) di dalam (hamba sahaya yang mereka miliki) hamba sahaya perempuan yang dimilikinya melalui jalan pembelian dan jalan yang lainnya, seumpamanya, hamba sahaya perempuan itu termasuk orang yang dihalalkan bagi pemiliknya, karena ia adalah wanita ahli kitab, berbeda halnya dengan sahaya wanita yang beragama majusi atau watsani, dan hendaknya sahaya wanita itu melakukan istibra' atau menyucikan rahimnya terlebih dahulu sebelum digauli oleh tuannya (supaya tidak) lafal ayat ini berta'alluq pada kalimat sebelumnya (menjadi kesempitan bagimu) dalam masalah pernikahan. (Dan adalah Allah Maha Pengampun) dalam hal-hal yang memang sulit untuk dapat dihindari (lagi Maha Penyayang) dengan memberikan keleluasaan dan kemurahan dalam hal ini.",[["يَـٰٓأَيُّهَا","Wahai Nabi"],["ٱلنَّبِىُّ","Wahai Nabi"],["إِنَّآ","Sesungguhnya Kami"],["أَحْلَلْنَا","[Kami] telah menghalalkan"],["لَكَ","kepada kamu"],["أَزْوَٰجَكَ","isteri-isteri kamu"],["ٱلَّـٰتِىٓ","(kepada) siapa"],["ءَاتَيْتَ","kamu telah memberi"],["أُجُورَهُنَّ","wang pengantin mereka"],["وَمَا","dan siapa"],["مَلَكَتْ","kamu mempunyai hak"],["يَمِينُكَ","kamu mempunyai hak"],["مِمَّآ","daripada mereka (yang)"],["أَفَآءَ","Allah dah bagi"],["ٱللَّهُ","Allah dah bagi"],["عَلَيْكَ","kepada kamu"],["وَبَنَاتِ","dan anak perempuan"],["عَمِّكَ","(daripada) bapa saudara sebelah bapa kamu"],["وَبَنَاتِ","dan anak perempuan"],["عَمَّـٰتِكَ","(daripada) ibu saudara sebelah bapa kamu"],["وَبَنَاتِ","dan anak perempuan"],["خَالِكَ","(daripada) bapa saudara sebelah ibu kamu"],["وَبَنَاتِ","dan anak perempuan"],["خَـٰلَـٰتِكَ","(daripada) ibu saudara sebelah ibu kamu"],["ٱلَّـٰتِى","yang"],["هَاجَرْنَ","berhijrah"],["مَعَكَ","bersama kamu"],["وَٱمْرَأَةًۭ","dan seorang perempuan"],["مُّؤْمِنَةً","beriman"],["إِن","jika"],["وَهَبَتْ","dia memberi"],["نَفْسَهَا","dirinya"],["لِلنَّبِىِّ","kepada Nabi"],["إِنْ","jika"],["أَرَادَ","kehendak"],["ٱلنَّبِىُّ","Nabi"],["أَن","kepada"],["يَسْتَنكِحَهَا","kahwin dengan dia"],["خَالِصَةًۭ","sahaja"],["لَّكَ","bagi kamu"],["مِن","tidak termasuk"],["دُونِ","tidak termasuk"],["ٱلْمُؤْمِنِينَ ۗ","orang yang beriman"],["قَدْ","Sungguh"],["عَلِمْنَا","Kami tahu"],["مَا","apa"],["فَرَضْنَا","Kami telah mewajibkan"],["عَلَيْهِمْ","ke atas mereka"],["فِىٓ","tentang"],["أَزْوَٰجِهِمْ","isteri mereka"],["وَمَا","dan siapa"],["مَلَكَتْ","mereka mempunyai hak"],["أَيْمَـٰنُهُمْ","mereka mempunyai hak"],["لِكَيْلَا","itu tidak"],["يَكُونَ","sepatutnya"],["عَلَيْكَ","pada kamu"],["حَرَجٌۭ ۗ","sebarang ketidakselesaan"],["وَكَانَ","Dan Allah adalah"],["ٱللَّهُ","Dan Allah adalah"],["غَفُورًۭا","Selalu Memaafkan"],["رَّحِيمًۭا","Maha Mengasihani"]]],"3584":["(Kamu boleh menangguhkan) dapat dibaca Turji-u dengan memakai huruf Hamzah pada akhirnya, juga dapat dibaca Turjiy dengan memakai huruf Ya pada akhirnya sebagai ganti dari Hamzah, artinya menangguhkan (siapa yang kamu kehendaki di antara mereka) yakni istri-istrimu itu dari gilirannya (dan boleh pula kamu menggilir) yaitu mengumpulkan gilirannya (siapa yang kamu kehendaki) di antara mereka kemudian kamu mendatanginya. (Dan siapa-siapa yang kamu ingini) kamu sukai untuk menggaulinya kembali (dari perempuan yang telah kamu pisahkan) dari gilirannya (maka tidak ada dosa bagimu) di dalam memintanya dan menggaulinya untukmu. Hal ini disuruh dipilih oleh Nabi sesudah ditentukan bahwa gilir itu wajib baginya. (Yang demikian itu) yakni boleh memilih itu (lebih dekat) kepada ketenangan hati mereka dan mereka tidak merasa sedih, dan semuanya rela dengan apa yang telah kamu berikan kepada mereka) yaitu tentang hal-hal yang telah disebutkan tadi menyangkut masalah boleh memilih di dalam menggilir (tanpa kecuali) lafal ayat ini mengukuhkan makna Fa'il yang terkandung di dalam lafal Yardhaina. (Dan Allah mengetahui apa yang tersimpan dalam hati kalian) mengenai masalah wanita atau istri dan kecenderungan hatimu kepada sebagian dari mereka. Dan sesungguhnya Kami menyuruh kamu memilih hanyalah untuk mempermudah kamu di dalam melakukan apa yang kamu kehendaki. (Dan adalah Allah Maha Mengetahui) tentang makhluk-Nya (lagi Maha Penyantun) mengenai menghukum mereka.",[["۞ تُرْجِى","Kamu boleh menangguhkan"],["مَن","yang"],["تَشَآءُ","kamu akan"],["مِنْهُنَّ","daripada mereka"],["وَتُـْٔوِىٓ","atau kamu boleh ambil"],["إِلَيْكَ","kepada diri sendiri"],["مَن","yang"],["تَشَآءُ ۖ","kamu akan"],["وَمَنِ","Dan sesiapa"],["ٱبْتَغَيْتَ","kamu inginkan"],["مِمَّنْ","daripada mereka yang"],["عَزَلْتَ","kamu (telah) ketepikan"],["فَلَا","maka (ada) tidak"],["جُنَاحَ","salahkan"],["عَلَيْكَ ۚ","ke atas kamu"],["ذَٰلِكَ","Itu"],["أَدْنَىٰٓ","(adalah) lebih sesuai"],["أَن","bahawa"],["تَقَرَّ","boleh disejukkan"],["أَعْيُنُهُنَّ","mata mereka"],["وَلَا","dan bukan"],["يَحْزَنَّ","mereka bersedih"],["وَيَرْضَيْنَ","dan mereka mungkin gembira"],["بِمَآ","dengan apa"],["ءَاتَيْتَهُنَّ","kamu telah memberi mereka"],["كُلُّهُنَّ ۚ","kesemuanya"],["وَٱللَّهُ","Dan Allah"],["يَعْلَمُ","mengetahui"],["مَا","apa"],["فِى","(berada) dalam"],["قُلُوبِكُمْ ۚ","hati kamu"],["وَكَانَ","Dan Allah adalah"],["ٱللَّهُ","Dan Allah adalah"],["عَلِيمًا","Maha Mengetahui"],["حَلِيمًۭا","Maha Penyabar"]]],"3585":["(Tidak halal) dapat dibaca Tahillu atau Yahillu (bagimu mengawini perempuan-perempuan sesudah itu) sesudah sembilan orang istri yang telah Aku pilih buatmu (dan tidak boleh pula mengganti) lafal Tabaddala asalnya adalah Tatabaddala, kemudian salah satu huruf Ta dibuang sehingga jadilah Tabaddala, (mereka dengan istri-istri yang lain) misalnya kamu menalak mereka atau sebagian dari mereka, kemudian kamu menggantikannya dengan istri yang lain (meskipun kecantikannya menarik hatimu kecuali perempuan-perempuan hamba sahaya yang kamu miliki) yakni wanita sahaya yang kamu miliki, ia halal bagimu. Dan Nabi saw. sesudah sembilan orang istri itu memiliki Siti Mariah, yang daripadanya lahir Ibrahim, akan tetapi Ibrahim meninggal dunia semasa Nabi saw. masih hidup. (Dan adalah Allah Maha Mengawasi segala sesuatu) Maha Memelihara segala sesuatu.",[["لَّا","(Ia) tidak"],["يَحِلُّ","halal"],["لَكَ","bagi kamu"],["ٱلنِّسَآءُ","(menikahi) perempuan"],["مِنۢ","selepas (ini)"],["بَعْدُ","selepas (ini)"],["وَلَآ","dan bukan"],["أَن","kepada"],["تَبَدَّلَ","pertukaran"],["بِهِنَّ","mereka"],["مِنْ","bagi"],["أَزْوَٰجٍۢ","isteri (lain-lain)."],["وَلَوْ","walaupun"],["أَعْجَبَكَ","menggembirakan kamu"],["حُسْنُهُنَّ","kecantikan mereka"],["إِلَّا","kecuali"],["مَا","yang"],["مَلَكَتْ","kamu mempunyai hak"],["يَمِينُكَ ۗ","kamu mempunyai hak"],["وَكَانَ","Dan Allah adalah"],["ٱللَّهُ","Dan Allah adalah"],["عَلَىٰ","atas"],["كُلِّ","semua"],["شَىْءٍۢ","benda"],["رَّقِيبًۭا","seorang Pemerhati"]]],"3586":["(Hai orang-orang yang beriman! Janganlah kalian memasuki rumah-rumah Nabi kecuali bila kalian diizinkan) memasukinya karena mendapat undangan (untuk makan) kemudian kalian boleh memasukinya (dengan tidak menunggu-nunggu) tanpa menunggu lagi (waktu masak makanannya) yakni sampai makanan masak terlebih dahulu; Inaa berakar dari kata Anaa Ya-niy (tetapi jika kalian diundang maka masuklah dan bila kalian selesai makan, keluarlah kalian tanpa) berdiam lagi (asyik memperpanjang percakapan) sebagian dari kalian kepada sebagian yang lain. (Sesungguhnya yang demikian itu) yakni berdiamnya kalian sesudah makan (akan mengganggu nabi lalu nabi malu kepada kalian) untuk menyuruh kalian keluar (dan Allah tidak malu menerangkan yang hak) yakni menerangkan supaya kalian keluar; atau dengan kata lain Dia tidak akan mengabaikan penjelasannya. Menurut qiraat yang lain lafal Yastahyi dibaca dengan hanya memakai satu huruf Ya sehingga bacaannya menjadi Yastahiy. (Apabila kalian meminta sesuatu kepada mereka) kepada istri-istri Nabi saw. (yakni suatu keperluan, maka mintalah dari belakang tabir) dari belakang hijab. (Cara yang demikian itu lebih suci bagi hati kalian dan hati mereka) dari perasaan-perasaan yang mencurigakan. (Dan tidak boleh kalian menyakiti hati Rasulullah) dengan sesuatu perbuatan apa pun (dan tidak pula mengawini istri-istrinya sesudah ia wafat selama-lamanya. Sesungguhnya perbuatan itu di sisi Allah) dosanya (besar).",[["يَـٰٓأَيُّهَا","Wahai orang yang beriman"],["ٱلَّذِينَ","Wahai orang yang beriman"],["ءَامَنُوا۟","Wahai orang yang beriman"],["لَا","Jangan"],["تَدْخُلُوا۟","masuk"],["بُيُوتَ","(the) rumah"],["ٱلنَّبِىِّ","(dari) Nabi"],["إِلَّآ","kecuali"],["أَن","apabila"],["يُؤْذَنَ","kebenaran diberi"],["لَكُمْ","kepada kamu"],["إِلَىٰ","bagi"],["طَعَامٍ","hidangan"],["غَيْرَ","tanpa"],["نَـٰظِرِينَ","sedang menunggu"],["إِنَىٰهُ","penyediaannya"],["وَلَـٰكِنْ","Tetapi"],["إِذَا","apabila"],["دُعِيتُمْ","kamu dijemput"],["فَٱدْخُلُوا۟","kemudian masuk"],["فَإِذَا","dan apabila"],["طَعِمْتُمْ","kamu dah makan"],["فَٱنتَشِرُوا۟","kemudian bersurai"],["وَلَا","dan bukan"],["مُسْتَـْٔنِسِينَ","berusaha untuk kekal"],["لِحَدِيثٍ ۚ","untuk perbualan"],["إِنَّ","Sesungguhnya"],["ذَٰلِكُمْ","bahawa"],["كَانَ","adalah"],["يُؤْذِى","merisaukan"],["ٱلنَّبِىَّ","Nabi"],["فَيَسْتَحْىِۦ","dan dia malu"],["مِنكُمْ ۖ","daripada (memecat) kamu"],["وَٱللَّهُ","Tetapi Allah"],["لَا","tidak malu"],["يَسْتَحْىِۦ","tidak malu"],["مِنَ","daripada"],["ٱلْحَقِّ ۚ","kebenaran"],["وَإِذَا","Dan apabila"],["سَأَلْتُمُوهُنَّ","kamu bertanya kepada mereka"],["مَتَـٰعًۭا","(untuk) apa-apa"],["فَسْـَٔلُوهُنَّ","kemudian bertanya kepada mereka"],["مِن","daripada"],["وَرَآءِ","belakang"],["حِجَابٍۢ ۚ","skrin"],["ذَٰلِكُمْ","Itu"],["أَطْهَرُ","(adalah) lebih tulen"],["لِقُلُوبِكُمْ","untuk hati kamu"],["وَقُلُوبِهِنَّ ۚ","dan hati mereka"],["وَمَا","Dan tidak"],["كَانَ","ialah"],["لَكُمْ","bagi kamu"],["أَن","bahawa"],["تُؤْذُوا۟","kamu menyusahkan"],["رَسُولَ","(the) Rasul"],["ٱللَّهِ","(milik) Allah"],["وَلَآ","dan bukan"],["أَن","bahawa"],["تَنكِحُوٓا۟","kamu patut kahwin"],["أَزْوَٰجَهُۥ","isteri-isterinya"],["مِنۢ","selepas dia"],["بَعْدِهِۦٓ","selepas dia"],["أَبَدًا ۚ","pernah"],["إِنَّ","Sesungguhnya"],["ذَٰلِكُمْ","bahawa"],["كَانَ","ialah"],["عِندَ","dekat"],["ٱللَّهِ","Allah"],["عَظِيمًا","satu kebesaran"]]],"3587":["(Jika kalian melahirkan sesuatu atau menyembunyikannya) keinginan untuk menikahi mereka sesudah Nabi saw. wafat (maka sesungguhnya Allah adalah Maha Mengetahui segala sesuatu) Dia kelak akan membalasnya kepada kalian.",[["إِن","sama ada"],["تُبْدُوا۟","kamu dedahkan"],["شَيْـًٔا","sesuatu perkara"],["أَوْ","atau"],["تُخْفُوهُ","menyembunyikannya"],["فَإِنَّ","sesungguhnya"],["ٱللَّهَ","Allah"],["كَانَ","ialah"],["بِكُلِّ","daripada semua"],["شَىْءٍ","benda"],["عَلِيمًۭا","Maha Mengetahui"]]],"3588":["(Tidak ada dosa atas istri-istri Nabi terhadap bapak-bapak mereka, anak-anak laki-laki mereka, saudara laki-laki mereka, anak laki-laki dari saudara laki-laki mereka, anak laki-laki dari saudara mereka yang perempuan, perempuan-perempuan) yang beriman (dan hamba sahaya yang mereka miliki) yakni hamba sahaya laki-laki dan perempuan, untuk melihat dan bercakap dengan mereka tanpa memakai hijab (dan bertakwalah kalian kepada Allah) dalam hal-hal yang diperintahkan-Nya kepada kalian. (Sesungguhnya Allah Maha Menyaksikan segala sesuatu) tidak ada sesuatu pun yang samar dari pengetahuan-Nya.",[["لَّا","(Ada) tidak"],["جُنَاحَ","salahkan"],["عَلَيْهِنَّ","ke atas mereka"],["فِىٓ","tentang"],["ءَابَآئِهِنَّ","bapa mereka"],["وَلَآ","dan bukan"],["أَبْنَآئِهِنَّ","anak lelaki mereka"],["وَلَآ","dan bukan"],["إِخْوَٰنِهِنَّ","saudara mereka"],["وَلَآ","dan bukan"],["أَبْنَآءِ","anak lelaki"],["إِخْوَٰنِهِنَّ","(dari) saudara-saudara mereka"],["وَلَآ","dan bukan"],["أَبْنَآءِ","anak lelaki"],["أَخَوَٰتِهِنَّ","(dari) saudara perempuan mereka"],["وَلَا","dan bukan"],["نِسَآئِهِنَّ","wanita mereka"],["وَلَا","dan bukan"],["مَا","apa"],["مَلَكَتْ","mereka mempunyai hak"],["أَيْمَـٰنُهُنَّ ۗ","mereka mempunyai hak"],["وَٱتَّقِينَ","Dan ketakutan"],["ٱللَّهَ ۚ","Allah"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["كَانَ","ialah"],["عَلَىٰ","atas"],["كُلِّ","semua"],["شَىْءٍۢ","benda"],["شَهِيدًا","seorang Saksi"]]],"3589":["(Sesungguhnya Allah dan malaikat-malaikat-Nya bersalawat untuk Nabi) untuk Nabi Muhammad saw. (Hai orang-orang yang beriman! Bersalawatlah kalian untuk Nabi dan ucapkanlah salam penghormatan kepadanya) yaitu katakanlah oleh kalian, \"Allaahumma Shalli 'Alaa Sayyidinaa Muhammad Wa Sallim\", artinya, \"Ya Allah! Limpahkanlah salawat dan Salam-Mu kepada junjungan kami Nabi Muhammad.\"",[["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["وَمَلَـٰٓئِكَتَهُۥ","dan MalaikatNya"],["يُصَلُّونَ","kirim berkat"],["عَلَى","ke atas"],["ٱلنَّبِىِّ ۚ","Nabi"],["يَـٰٓأَيُّهَا","Wahai orang yang beriman"],["ٱلَّذِينَ","Wahai orang yang beriman"],["ءَامَنُوا۟","Wahai orang yang beriman"],["صَلُّوا۟","Kirim berkat"],["عَلَيْهِ","pada dia"],["وَسَلِّمُوا۟","dan memberi salam kepadanya"],["تَسْلِيمًا","(dengan) salam"]]],"3590":["(Sesungguhnya orang-orang yang menyakiti Allah dan Rasul-Nya) mereka adalah orang-orang kafir, mereka mensifati Allah dengan sifat-sifat yang Dia Maha Suci daripadanya, yaitu mempunyai anak dan mempunyai sekutu, kemudian mereka mendustakan rasul-Nya. (Allah akan melaknatinya di dunia dan di akhirat) yakni menjauhkannya dari rahmat-Nya (dan menyediakan baginya siksa yang menghinakan) siksaan yang menghinakan yaitu neraka.",[["إِنَّ","Sesungguhnya"],["ٱلَّذِينَ","orang yang"],["يُؤْذُونَ","mengganggu"],["ٱللَّهَ","Allah"],["وَرَسُولَهُۥ","dan Rasul-Nya"],["لَعَنَهُمُ","Allah telah melaknat mereka"],["ٱللَّهُ","Allah telah melaknat mereka"],["فِى","dalam"],["ٱلدُّنْيَا","dunia"],["وَٱلْـَٔاخِرَةِ","dan akhirat"],["وَأَعَدَّ","dan disediakan"],["لَهُمْ","bagi mereka"],["عَذَابًۭا","azab"],["مُّهِينًۭا","memalukan"]]],"3591":["(Dan orang-orang yang menyakiti orang-orang Mukmin dan Mukminat tanpa kesalahan yang mereka perbuat) yaitu menuduh mereka mengerjakan hal-hal yang tidak mereka lakukan (maka sesungguhnya mereka telah memikul kebohongan) melancarkan tuduhan bohong (dan dosa yang nyata) yakni perbuatan yang nyata dosanya.",[["وَٱلَّذِينَ","Dan orang yang"],["يُؤْذُونَ","kemudaratan"],["ٱلْمُؤْمِنِينَ","lelaki yang beriman"],["وَٱلْمُؤْمِنَـٰتِ","dan wanita yang beriman"],["بِغَيْرِ","untuk selain"],["مَا","apa"],["ٱكْتَسَبُوا۟","mereka telah perolehi"],["فَقَدِ","maka sudah tentu"],["ٱحْتَمَلُوا۟","mereka menanggung"],["بُهْتَـٰنًۭا","tuduhan palsu"],["وَإِثْمًۭا","dan dosa"],["مُّبِينًۭا","nyata"]]],"3592":["(Hai Nabi! Katakanlah kepada istri-istrimu, anak-anak perempuanmu dan istri-istri orang Mukmin, \"Hendaklah mereka mengulurkan jilbabnya ke seluruh tubuh mereka\") lafal Jalaabiib adalah bentuk jamak dari lafal Jilbaab, yaitu kain yang dipakai oleh seorang wanita untuk menutupi seluruh tubuhnya. Maksudnya hendaknya mereka mengulurkan sebagian daripada kain jilbabnya itu untuk menutupi muka mereka, jika mereka hendak keluar karena suatu keperluan, kecuali hanya bagian yang cukup untuk satu mata. (Yang demikian itu supaya mereka lebih mudah) lebih gampang (untuk dikenal) bahwasanya mereka adalah wanita-wanita yang merdeka (karena itu mereka tidak diganggu) maksudnya tidak ada orang yang berani mengganggunya, berbeda halnya dengan hamba sahaya wanita, mereka tidak diperintahkan untuk menutupi mukanya, sehingga orang-orang munafik selalu mengganggu mereka. (Dan adalah Allah Maha Pengampun) terhadap hal-hal yang telah lalu pada kaum wanita Mukmin yang merdeka, yaitu tidak menutupi wajah mereka (lagi Maha Penyayang) kepada mereka jika mereka mau menutupinya.",[["يَـٰٓأَيُّهَا","Wahai Nabi"],["ٱلنَّبِىُّ","Wahai Nabi"],["قُل","Katakanlah"],["لِّأَزْوَٰجِكَ","kepada isteri-isteri kamu"],["وَبَنَاتِكَ","dan anak perempuan kamu"],["وَنِسَآءِ","dan (para) perempuan"],["ٱلْمُؤْمِنِينَ","(dari) orang-orang yang beriman"],["يُدْنِينَ","untuk melukis"],["عَلَيْهِنَّ","atas diri mereka sendiri"],["مِن","[daripada]"],["جَلَـٰبِيبِهِنَّ ۚ","pakaian luar mereka"],["ذَٰلِكَ","Itu"],["أَدْنَىٰٓ","(adalah) lebih sesuai"],["أَن","bahawa"],["يُعْرَفْنَ","mereka harus dikenali"],["فَلَا","dan bukan"],["يُؤْذَيْنَ ۗ","dicederakan"],["وَكَانَ","Dan adakah"],["ٱللَّهُ","Allah"],["غَفُورًۭا","Selalu Memaafkan"],["رَّحِيمًۭا","Maha Mengasihani"]]],"3593":["(Sesungguhnya jika) huruf Lam bermaksud Qasam/sumpah (tidak berhenti orang-orang munafik) dari kemunafikan mereka (orang-orang yang berpenyakit dalam hati mereka) disebabkan telah melakukan perbuatan zina (dan orang-orang yang menyebarkan kabar bohong di Madinah) terhadap orang-orang Mukmin melalui perkataan mereka, bahwa musuh telah siap menyerang kalian berikut pasukan kalian; apakah mereka akan menang atau kalah kami tidak mengetahui (niscaya Kami gerakkan kamu untuk memerangi mereka) maksudnya Kami membuatmu berkuasa atas mereka (kemudian mereka tidak menjadi tetanggamu) tidak hidup berdampingan lagi denganmu (di Madinah melainkan dalam waktu sebentar) setelah itu mereka diusir daripadanya.",[["۞ لَّئِن","Jika"],["لَّمْ","jangan"],["يَنتَهِ","berhenti"],["ٱلْمُنَـٰفِقُونَ","golongan munafik"],["وَٱلَّذِينَ","dan orang yang"],["فِى","dalam"],["قُلُوبِهِم","hati mereka"],["مَّرَضٌۭ","(adalah) penyakit"],["وَٱلْمُرْجِفُونَ","dan mereka yang menyebarkan khabar angin"],["فِى","dalam"],["ٱلْمَدِينَةِ","bandar itu"],["لَنُغْرِيَنَّكَ","Kami akan membiarkan kamu mengalahkan mereka"],["بِهِمْ","Kami akan membiarkan kamu mengalahkan mereka"],["ثُمَّ","kemudian"],["لَا","tidak"],["يُجَاوِرُونَكَ","mereka akan kekal sebagai jiran kamu"],["فِيهَآ","di dalamnya"],["إِلَّا","kecuali"],["قَلِيلًۭا","(untuk) sedikit"]]],"3594":["(dalam keadaan terlaknat) dalam keadaan dijauhkan dari rahmat Allah. (Di mana saja mereka dijumpai) ditemui (mereka ditangkap dan dibunuh dengan sehebat-hebatnya) yakni keputusan tentang nasib mereka ini berdasarkan perintah dari-Nya.",[["مَّلْعُونِينَ ۖ","Terkutuklah"],["أَيْنَمَا","di mana sahaja"],["ثُقِفُوٓا۟","mereka ditemui"],["أُخِذُوا۟","mereka disita"],["وَقُتِّلُوا۟","dan dibunuh secara beramai-ramai"],["تَقْتِيلًۭا","dan dibunuh secara beramai-ramai"]]],"3595":["(Sebagai sunah Allah) yakni Allah telah menetapkan hal tersebut sebagai sunah-Nya (yang berlaku atas orang-orang yang telah terdahulu) atas umat-umat yang dahulu, yaitu atas orang-orang munafik yang selalu menyebarkan rasa takut ke dalam hati orang-orang yang beriman (dan kamu sekali-kali tiada akan mendapati perubahan pada sunah Allah) sebagai pengganti dari-Nya.",[["سُنَّةَ","(Begitulah) Jalan"],["ٱللَّهِ","(milik) Allah"],["فِى","dengan"],["ٱلَّذِينَ","orang yang"],["خَلَوْا۟","meninggal dunia"],["مِن","sebelum"],["قَبْلُ ۖ","sebelum"],["وَلَن","dan tidak pernah"],["تَجِدَ","kamu akan dapati"],["لِسُنَّةِ","dalam (cara) itu"],["ٱللَّهِ","(milik) Allah"],["تَبْدِيلًۭا","sebarang perubahan"]]],"3596":["(Manusia bertanya kepadamu) yakni penduduk Mekah (tentang hari kiamat) kapankah akan terjadi. (Katakanlah! \"Sesungguhnya pengetahuan tentang hari kiamat itu hanya di sisi Allah\". Dan tahukah kamu) maksudnya kamu tiada mengetahui kapan ia akan terjadi (boleh jadi hari kiamat itu waktunya) yakni terjadinya (sudah dekat).",[["يَسْـَٔلُكَ","Tanya kamu"],["ٱلنَّاسُ","manusia"],["عَنِ","tentang"],["ٱلسَّاعَةِ ۖ","Jam itu"],["قُلْ","Katakanlah"],["إِنَّمَا","Hanya"],["عِلْمُهَا","pengetahuannya"],["عِندَ","(adalah) dengan"],["ٱللَّهِ ۚ","Allah"],["وَمَا","Dan apa"],["يُدْرِيكَ","akan membuat kamu tahu"],["لَعَلَّ","barangkali"],["ٱلسَّاعَةَ","Jam itu"],["تَكُونُ","ialah"],["قَرِيبًا","dekat"]]],"3597":["(Sesungguhnya Allah melaknati orang-orang kafir) yakni menjauhkan mereka dari rahmat-Nya (dan menyediakan bagi mereka api yang menyala-nyala) yaitu neraka yang keras apinya tempat mereka dimasukkan.",[["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["لَعَنَ","telah mengutuk"],["ٱلْكَـٰفِرِينَ","orang kafir"],["وَأَعَدَّ","dan telah menyediakan"],["لَهُمْ","bagi mereka"],["سَعِيرًا","a Blaze"]]],"3598":["(Mereka kekal) dipastikan kekekalan mereka (di dalamnya selama-lamanya, mereka tidak memperoleh seorang pelindung pun) yang memelihara mereka dari neraka (dan tidak pula seorang penolong) yang dapat mencegah neraka daripada mereka.",[["خَـٰلِدِينَ","Kekal"],["فِيهَآ","di dalamnya"],["أَبَدًۭا ۖ","selama-lamanya"],["لَّا","tidak"],["يَجِدُونَ","mereka akan dapati"],["وَلِيًّۭا","mana-mana pelindung"],["وَلَا","dan bukan"],["نَصِيرًۭا","mana-mana pembantu"]]],"3599":["(Pada hari ketika muka mereka dibolak-balikkan dalam neraka, mereka berkata, \"Aduhai!) lafal Yaa menunjukkan makna Tanbih atau memohon perhatian (andai kata kami taat kepada Allah dan taat pula kepada Rasul.\")",[["يَوْمَ","(The) Hari"],["تُقَلَّبُ","akan dipusingkan"],["وُجُوهُهُمْ","muka mereka"],["فِى","dalam"],["ٱلنَّارِ","neraka"],["يَقُولُونَ","mereka akan berkata"],["يَـٰلَيْتَنَآ","Wahai kami mahu"],["أَطَعْنَا","kami (telah) patuh"],["ٱللَّهَ","Allah"],["وَأَطَعْنَا","dan dipatuhi"],["ٱلرَّسُولَا۠","Rasul"]]],"3600":["(Dan mereka berkata) yakni para pengikut dari kalangan mereka, (\"Ya Rabb kami! Sesungguhnya kami telah menaati pemimpin-pemimpin kami) menurut suatu qiraat dibaca Saadatanaa, dalam bentuk Jam'ul Jam'i (dan pembesar-pembesar kami, lalu mereka menyesatkan kami dari jalan petunjuk) dari jalan hidayah.",[["وَقَالُوا۟","Dan mereka akan berkata"],["رَبَّنَآ","Wahai Tuhan kami"],["إِنَّآ","Sesungguhnya kami"],["أَطَعْنَا","[kami] patuh"],["سَادَتَنَا","ketua kami"],["وَكُبَرَآءَنَا","dan orang hebat kita"],["فَأَضَلُّونَا","dan mereka menyesatkan kita"],["ٱلسَّبِيلَا۠","(dari) Jalan"]]],"3601":["(Ya Rabb kami! Timpakanlah kepada mereka azab dua kali lipat) daripada azab yang kami terima (dan kutuklah mereka) azablah mereka terus (dengan kutukan yang banyak.\") bilangannya; dan menurut Qiraat lain lafal Kabiiran dibaca Katsiiran yang artinya kutukan yang besar.",[["رَبَّنَآ","Wahai Tuhan kami"],["ءَاتِهِمْ","Beri mereka"],["ضِعْفَيْنِ","berganda"],["مِنَ","[daripada]"],["ٱلْعَذَابِ","hukuman"],["وَٱلْعَنْهُمْ","dan kutuk mereka"],["لَعْنًۭا","(dengan) sumpahan"],["كَبِيرًۭا","yang besar"]]],"3602":["(Hai orang-orang yang beriman! Janganlah kalian menjadi) bersama Nabi kalian (seperti orang-orang yang menyakiti Musa) seperti perkataan mereka kepada Nabi Musa, \"Sesungguhnya tidak ada yang mencegahnya untuk mandi bersama kita melainkan karena pelirnya burut (maka Allah membersihkannya dari tuduhan-tuduhan yang mereka katakan) yaitu pada suatu hari Nabi Musa ketika hendak mandi meletakkan pakaiannya pada sebuah batu, kemudian batu itu membawa lari pakaiannya, dan berhenti di tengah-tengah segolongan kaum Bani Israel. Lalu Nabi Musa mengejarnya dan dapat menyusulnya, segera ia mengambil pakaiannya untuk menutupi dirinya. Pada saat itu orang-orang melihatnya dalam keadaan telanjang, ternyata pelir Nabi Musa tidak burut. (Dan adalah dia seorang yang mempunyai kedudukan terhormat di sisi Allah.\"). Di antara perlakuan yang menyakitkan Nabi saw. ialah pada suatu hari ia membagi-bagi ganimah, kemudian ada seorang lelaki berkata, \"Ini adalah pembagian yang tidak berdasarkan keridaan Allah swt.\" Maka pada saat itu wajah Nabi saw. merah padam mendengar perkataan itu, lalu beliau segera bersabda, \"Semoga Allah melimpahkan rahmat-Nya kepada Musa, sesungguhnya dia telah disakiti lebih dari ini tetapi dia tetap bersabar.\" Demikianlah menurut hadis yang diriwayatkan oleh Imam Bukhari.",[["يَـٰٓأَيُّهَا","Wahai orang yang beriman"],["ٱلَّذِينَ","Wahai orang yang beriman"],["ءَامَنُوا۟","Wahai orang yang beriman"],["لَا","Jangan"],["تَكُونُوا۟","jadilah"],["كَٱلَّذِينَ","seperti mereka yang"],["ءَاذَوْا۟","didera"],["مُوسَىٰ","Musa"],["فَبَرَّأَهُ","kemudian Allah membersihkannya"],["ٱللَّهُ","kemudian Allah membersihkannya"],["مِمَّا","tentang apa"],["قَالُوا۟ ۚ","mereka berkata"],["وَكَانَ","Dan dia"],["عِندَ","dekat"],["ٱللَّهِ","Allah"],["وَجِيهًۭا","terhormat"]]],"3603":["(Hai orang-orang yang beriman! Bertakwalah kamu sekalian kepada Allah dan katakanlah perkataan yang benar) yakni perkataan yang tidak menyalahi.",[["يَـٰٓأَيُّهَا","Wahai orang yang beriman"],["ٱلَّذِينَ","Wahai orang yang beriman"],["ءَامَنُوا۟","Wahai orang yang beriman"],["ٱتَّقُوا۟","Takut"],["ٱللَّهَ","Allah"],["وَقُولُوا۟","dan bercakap"],["قَوْلًۭا","satu perkataan"],["سَدِيدًۭا","betul"]]],"3604":["(Niscaya Allah memperbaiki bagi kalian amal-amal kalian) yakni Dia menerimanya (dan mengampuni bagi kalian dosa-dosa kalian. Siapa yang menaati Allah dan Rasul-Nya, maka sesungguhnya ia telah mendapatkan kemenangan yang besar) yaitu dia telah memperoleh apa yang paling didambakannya.",[["يُصْلِحْ","Dia akan meminda"],["لَكُمْ","bagi kamu"],["أَعْمَـٰلَكُمْ","perbuatan kamu"],["وَيَغْفِرْ","dan memaafkan"],["لَكُمْ","bagi kamu"],["ذُنُوبَكُمْ ۗ","dosa kamu"],["وَمَن","Dan sesiapa"],["يُطِعِ","patuh"],["ٱللَّهَ","Allah"],["وَرَسُولَهُۥ","dan Rasul-Nya"],["فَقَدْ","sudah tentu"],["فَازَ","telah dicapai"],["فَوْزًا","suatu pencapaian"],["عَظِيمًا","yang besar"]]],"3605":["(Sesungguhnya Kami telah mengemukakan amanat) yaitu ibadah salat dan ibadah-ibadah lainnya, apabila dikerjakan, pelakunya akan mendapat pahala, dan apabila ditinggalkan, pelakunya akan disiksa (pada langit, bumi dan gunung-gunung) seumpamanya Allah menciptakan pada masing-masing pemahaman dan dapat berbicara (maka semuanya enggan untuk memikul amanat itu dan mereka khawatir) yakni merasa takut (akan mengkhianatinya lalu dipikullah amanat itu oleh manusia) oleh Nabi Adam, sesudah terlebih dahulu ditawarkan kepadanya. (Sesungguhnya manusia itu amat zalim) terhadap dirinya sendiri, disebabkan apa yang telah dipikulnya itu (lagi amat bodoh) tidak mengerti tentang apa yang dipikulnya itu.",[["إِنَّا","Sesungguhnya Kami"],["عَرَضْنَا","[Kami] menawarkan"],["ٱلْأَمَانَةَ","Amanah"],["عَلَى","kepada"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ","dan bumi"],["وَٱلْجِبَالِ","dan pergunungan"],["فَأَبَيْنَ","tetapi mereka menolak"],["أَن","kepada"],["يَحْمِلْنَهَا","menanggungnya"],["وَأَشْفَقْنَ","dan mereka takut"],["مِنْهَا","daripadanya"],["وَحَمَلَهَا","tetapi menanggungnya"],["ٱلْإِنسَـٰنُ ۖ","lelaki itu"],["إِنَّهُۥ","Sesungguhnya dia"],["كَانَ","adalah"],["ظَلُومًۭا","tidak adil"],["جَهُولًۭا","jahil"]]],"3606":["(Sehingga Allah mengazab) huruf Lam berta'alluq kepada lafal 'Aradhnaa, sebagai akibat dari apa yang telah dipikul oleh Nabi Adam (orang-orang munafik laki-laki dan perempuan dan orang-orang musyrik laki-laki dan perempuan) yakni orang-orang yang menyia-nyiakan amanat itu (dan sehingga Allah menerima tobat orang-orang Mukmin laki-laki dan perempuan) yaitu orang-orang yang menunaikan amanahnya. (Dan adalah Allah Maha Pengampun) kepada orang-orang Mukmin (lagi Maha Penyayang) kepada mereka.",[["لِّيُعَذِّبَ","Supaya Allah mengazab"],["ٱللَّهُ","Supaya Allah mengazab"],["ٱلْمُنَـٰفِقِينَ","lelaki munafik"],["وَٱلْمُنَـٰفِقَـٰتِ","dan perempuan-perempuan munafik"],["وَٱلْمُشْرِكِينَ","dan orang-orang musyrik"],["وَٱلْمُشْرِكَـٰتِ","dan perempuan-perempuan musyrik"],["وَيَتُوبَ","dan Allah akan kembali (dengan rahmat)"],["ٱللَّهُ","dan Allah akan kembali (dengan rahmat)"],["عَلَى","kepada"],["ٱلْمُؤْمِنِينَ","lelaki yang beriman"],["وَٱلْمُؤْمِنَـٰتِ ۗ","dan wanita yang beriman"],["وَكَانَ","Dan Allah adalah"],["ٱللَّهُ","Dan Allah adalah"],["غَفُورًۭا","Selalu Memaafkan"],["رَّحِيمًۢا","Maha Mengasihani"]]],"3607":["(Segala puji bagi Allah) Allah swt. memuji diri-Nya dengan kalimat ini, maksudnya ialah pujian berikut apa yang terkandung di dalamnya yaitu pujian yang bersifat tetap. Memuji Allah artinya menyanjung-Nya dengan sebutan-sebutan yang baik (yang memiliki apa yang di langit dan apa yang di bumi) sebagai milik dan makhluk-Nya (dan bagi-Nya pula segala puji di akhirat) sebagaimana di dunia, yaitu Dia dipuji oleh kekasih-kekasih-Nya bilamana mereka telah berada di dalam surga. (Dan Dialah Yang Maha Bijaksana) di dalam perbuatan-Nya (lagi Maha Mengetahui) tentang makhluk-Nya.",[["ٱلْحَمْدُ","Semua pujian"],["لِلَّهِ","bagi Allah"],["ٱلَّذِى","kepunyaan-Nya"],["لَهُۥ","kepunyaan-Nya"],["مَا","apa sahaja"],["فِى","(berada) dalam"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَمَا","dan apa sahaja"],["فِى","(berada) dalam"],["ٱلْأَرْضِ","bumi"],["وَلَهُ","dan untuk Dia"],["ٱلْحَمْدُ","(adalah) segala pujian"],["فِى","dalam"],["ٱلْـَٔاخِرَةِ ۚ","akhirat"],["وَهُوَ","Dan Dia"],["ٱلْحَكِيمُ","(ialah) Yang Maha Bijaksana"],["ٱلْخَبِيرُ","yang Maha Mengetahui"]]],"3608":["(Dia mengetahui apa yang masuk) yang meresap (ke dalam bumi) seperti air dan lain-lainnya (dan apa yang keluar daripadanya) seperti tumbuh-tumbuhan dan lain-lainnya (dan apa yang turun dari langit) berupa rezeki atau hujan dan lain-lainnya (dan apa yang naik) yakni yang terangkat (kepadanya) berupa amal perbuatan dan lain-lainnya. (Dan Dialah Yang Maha Penyayang) kepada kekasih-kekasih-Nya (lagi Maha Pengampun) kepada mereka.",[["يَعْلَمُ","Dia tahu"],["مَا","apa"],["يَلِجُ","menembusi"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["وَمَا","dan apa"],["يَخْرُجُ","keluar"],["مِنْهَا","daripadanya"],["وَمَا","dan apa"],["يَنزِلُ","turun"],["مِنَ","daripada"],["ٱلسَّمَآءِ","syurga itu"],["وَمَا","dan apa"],["يَعْرُجُ","naik"],["فِيهَا ۚ","di dalamnya"],["وَهُوَ","Dan Dia"],["ٱلرَّحِيمُ","(adalah) Yang Maha Penyayang"],["ٱلْغَفُورُ","Yang Maha Pengampun"]]],"3609":["(Dan orang-orang yang kafir berkata, \"Hari terakhir itu tidak akan datang kepada kami\") yakni hari kiamat. (Katakanlah) kepada mereka, (\"Pasti datang, demi Rabbku Yang mengetahui yang gaib, sesungguhnya kiamat itu pasti akan datang kepada kalian) kalau dibaca 'Aalimil Ghaibi berarti menjadi sifat dari lafal Rabbii. Kalau dibaca 'Aalimul Ghaibi berarti menjadi Khabar dari Mubtada, sehingga artinya menjadi seperti berikut, Ya, pasti datang, demi Rabbku, hari kiamat itu pasti akan datang kepada kalian; Dia mengetahui yang gaib. Bacaan yang kedua ini lebih sesuai dengan kalimat yang sesudahnya, yaitu, (tidak ada yang tersembunyi) tiada yang tidak tampak (bagi-Nya seberat) sebesar (zarah pun) zarah artinya semut yang paling kecil (yang ada di langit dan yang ada di bumi, dan tidak ada pula yang lebih kecil dari itu dan yang lebih besar, melainkan semuanya tercatat dalam Kitab yang nyata.) Kitab yang jelas, yang dimaksud adalah Lohmahfuz.",[["وَقَالَ","Tetapi katakan"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["لَا","Tidak"],["تَأْتِينَا","akan datang kepada kita"],["ٱلسَّاعَةُ ۖ","Jam itu"],["قُلْ","Katakanlah"],["بَلَىٰ","Bahkan"],["وَرَبِّى","oleh Tuhanku"],["لَتَأْتِيَنَّكُمْ","nescaya ia akan datang kepada kamu"],["عَـٰلِمِ","(Dialah yang) Maha Mengetahui"],["ٱلْغَيْبِ ۖ","(dari) yang ghaib"],["لَا","Tidak"],["يَعْزُبُ","melarikan diri"],["عَنْهُ","daripadaNya"],["مِثْقَالُ","(yang) berat"],["ذَرَّةٍۢ","(dari) atom"],["فِى","dalam"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَلَا","dan bukan"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["وَلَآ","dan bukan"],["أَصْغَرُ","lebih kecil"],["مِن","daripada"],["ذَٰلِكَ","bahawa"],["وَلَآ","dan bukan"],["أَكْبَرُ","lebih besar"],["إِلَّا","tetapi"],["فِى","(berada) dalam"],["كِتَـٰبٍۢ","sebuah Rekod"],["مُّبِينٍۢ","Jelas"]]],"3610":["(Supaya Allah memberi balasan) pada hari kiamat itu (kepada orang-orang yang beriman dan mengerjakan amal yang saleh. Mereka itu adalah orang-orang yang baginya ampunan dan rezeki yang mulia.\") rezeki yang baik di surga.",[["لِّيَجْزِىَ","Supaya Dia dapat pahala"],["ٱلَّذِينَ","orang yang"],["ءَامَنُوا۟","beriman"],["وَعَمِلُوا۟","dan melakukan"],["ٱلصَّـٰلِحَـٰتِ ۚ","amal soleh"],["أُو۟لَـٰٓئِكَ","Itu"],["لَهُم","bagi mereka"],["مَّغْفِرَةٌۭ","(akan) pengampunan"],["وَرِزْقٌۭ","dan peruntukan"],["كَرِيمٌۭ","mulia"]]],"3611":["(Dan orang-orang yang berusaha untuk) menentang atau membatalkan (ayat-ayat Kami) yaitu Alquran (dengan anggapan mereka dapat melepaskan diri dari Kami) dan menurut qiraat yang lain, lafal Mu'aajiziina pada ayat ini dan pada ayat yang lainnya nanti dibaca Mu'jiziina. Maksudnya menganggap Kami tidak mampu mengazab mereka, atau mereka beranggapan dapat melepaskan diri dari azab Kami, karena mereka mempunyai dugaan, bahwa tidak ada hari berbangkit dan tidak ada azab (mereka itu memperoleh buruknya azab) azab yang paling buruk (yang pedih) yang menyakitkan, kalau dibaca Aliimin berarti menjadi sifat daripada lafal Rijzin dan kalau dibaca Aliimun berarti menjadi sifat daripada lafal 'Adzaabun.",[["وَٱلَّذِينَ","Tetapi mereka yang"],["سَعَوْ","berusaha"],["فِىٓ","terhadap"],["ءَايَـٰتِنَا","Ayat Kami"],["مُعَـٰجِزِينَ","(untuk) menyebabkan kegagalan"],["أُو۟لَـٰٓئِكَ","mereka"],["لَهُمْ","bagi mereka"],["عَذَابٌۭ","(ialah) azab"],["مِّن","daripada"],["رِّجْزٍ","sifat busuk"],["أَلِيمٌۭ","yang pedih"]]],"3612":["(Dan berpendapat) yakni telah mengetahui (orang-orang yang diberi ilmu) yang dimaksud adalah orang-orang yang beriman dari kalangan ahli kitab, seperti Abdullah bin Salam dan teman-temannya (bahwa wahyu yang diturunkan kepadamu dari Rabbmu) yakni Alquran (itulah) keputusan (yang benar dan menunjuki manusia kepada jalan) tuntunan (Tuhan Yang Maha Perkasa lagi Maha Terpuji) Allah yang memiliki keperkasaan lagi terpuji.",[["وَيَرَى","Dan lihat"],["ٱلَّذِينَ","orang yang"],["أُوتُوا۟","telah diberikan"],["ٱلْعِلْمَ","pengetahuan itu"],["ٱلَّذِىٓ","(itu) apa"],["أُنزِلَ","didedahkan"],["إِلَيْكَ","kepada kamu"],["مِن","daripada"],["رَّبِّكَ","Tuhanmu"],["هُوَ","[ia]"],["ٱلْحَقَّ","(adalah) Kebenaran"],["وَيَهْدِىٓ","dan ia membimbing"],["إِلَىٰ","kepada"],["صِرَٰطِ","(the) Jalan"],["ٱلْعَزِيزِ","(dari) Yang Maha Perkasa"],["ٱلْحَمِيدِ","yang Terpuji"]]],"3613":["(Dan orang-orang kafir berkata) sebagian dari mereka berkata kepada sebagian yang lain dengan nada yang penuh keheranan, (\"Maukah kalian kami tunjukkan kepada kalian seorang laki-laki) yang mereka maksud adalah Nabi Muhammad (yang memberitakan kepada kalian) yang membawa berita kepada kalian, bahwasanya (apabila badan kalian telah hancur) telah berantakan (sehancur-hancurnya) menjadi berkeping-keping (sesungguhnya kalian akan dibangkitkan kembali dalam ciptaan yang baru?\")",[["وَقَالَ","Tetapi katakan"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["هَلْ","hendaklah"],["نَدُلُّكُمْ","kami mengarahkan kamu"],["عَلَىٰ","kepada"],["رَجُلٍۢ","seorang lelaki"],["يُنَبِّئُكُمْ","yang memberitahu kamu"],["إِذَا","apabila"],["مُزِّقْتُمْ","kamu telah hancur"],["كُلَّ","(dalam) jumlah"],["مُمَزَّقٍ","perpecahan"],["إِنَّكُمْ","sesungguhnya kamu"],["لَفِى","nescaya (akan) masuk"],["خَلْقٍۢ","sebuah ciptaan"],["جَدِيدٍ","baru"]]],"3614":["(Apakah dia mengada-adakan) lafal Aftaraa pada asalnya adalah A-iftaraa, kemudian Hamzah Washalnya tidak dibutuhkan lagi karena Hamzah Istifham sudah difathahkan, sehingga menjadi Aftaraa (kebohongan terhadap Allah) dalam hal tersebut (ataukah ada padanya penyakit gila?) yakni gangguan pada otaknya hingga ia mengkhayal yang bukan-bukan. Maka, Allah berfirman menyanggah mereka, (\"Tidak, tetapi orang-orang yang tidak beriman kepada negeri akhirat) yang di dalamnya terdapat hari berbangkit dan azab pembalasan (berada dalam siksaan) di akhirat nanti (dan kesesatan yang jauh.) dari kebenaran dalam kehidupan dunia.",[["أَفْتَرَىٰ","Adakah dia mencipta"],["عَلَى","tentang"],["ٱللَّهِ","Allah"],["كَذِبًا","satu pembohongan"],["أَم","atau"],["بِهِۦ","dalam dirinya"],["جِنَّةٌۢ ۗ","(adalah) kegilaan"],["بَلِ","Bahkan"],["ٱلَّذِينَ","orang yang"],["لَا","jangan"],["يُؤْمِنُونَ","beriman"],["بِٱلْـَٔاخِرَةِ","di akhirat"],["فِى","(akan) masuk"],["ٱلْعَذَابِ","azab"],["وَٱلضَّلَـٰلِ","dan kesilapan"],["ٱلْبَعِيدِ","jauh"]]],"3615":["(Maka, apakah mereka tidak melihat) tidak memperhatikan (kepada apa yang ada di hadapan mereka dan apa yang ada di belakang mereka) maksudnya apa yang ada di atas dan di bawah mereka (yaitu langit dan bumi? Jika Kami menghendaki, niscaya Kami benamkan mereka di bumi atau Kami jatuhkan kepada mereka gumpalan) dapat dibaca Kisfan atau Kisafan artinya gumpalan-gumpalan (dari langit) menurut qiraat yang lain lafal Nasya', Nakhsif, dan Nusqith dibaca Yasya', Yakhsif dan Yusqith. (Sesungguhnya pada yang demikian itu) hal-hal yang terlihat itu (benar-benar terdapat tanda bagi setiap hamba yang kembali.\") kepada Rabbnya, yaitu tanda yang menunjukkan akan kekuasaan Allah yang mampu membangkitkan hidup kembali dan menciptakan apa yang dikehendaki-Nya.",[["أَفَلَمْ","Kemudian, jangan"],["يَرَوْا۟","mereka lihat"],["إِلَىٰ","ke arah"],["مَا","apa"],["بَيْنَ","(ada) di hadapan mereka"],["أَيْدِيهِمْ","(ada) di hadapan mereka"],["وَمَا","dan apa"],["خَلْفَهُم","(ada) di belakang mereka"],["مِّنَ","daripada"],["ٱلسَّمَآءِ","syurga itu"],["وَٱلْأَرْضِ ۚ","dan bumi"],["إِن","Jika"],["نَّشَأْ","Kami akan"],["نَخْسِفْ","Kami (boleh) menyebabkan untuk menelan mereka"],["بِهِمُ","Kami (boleh) menyebabkan untuk menelan mereka"],["ٱلْأَرْضَ","bumi"],["أَوْ","atau"],["نُسْقِطْ","menyebabkan jatuh"],["عَلَيْهِمْ","ke atas mereka"],["كِسَفًۭا","serpihan"],["مِّنَ","daripada"],["ٱلسَّمَآءِ ۚ","langit"],["إِنَّ","Sesungguhnya"],["فِى","dalam"],["ذَٰلِكَ","bahawa"],["لَـَٔايَةًۭ","sesungguhnya adalah suatu tanda"],["لِّكُلِّ","untuk setiap"],["عَبْدٍۢ","hamba"],["مُّنِيبٍۢ","yang kembali (kepada Allah)"]]],"3616":["(Dan sesungguhnya telah Kami berikan kepada Daud karunia dari Kami) berupa kenabian dan Kitab Zabur. Dan Kami berfirman, (\"Hai gunung-gunung! Lakukanlah berulang-ulang) yakni ulang-ulanglah (bersama Daud) melakukan tasbih; maksudnya bertasbihlah berulang-ulang bersamanya (dan burung-burung\") dibaca Nashab karena di'athafkan secara Mahall pada lafal Al Jibaalu maksudnya Kami menyeru mereka supaya bertasbih bersamanya (dan Kami telah melunakkan besi untuknya) sehingga besi di tangan Nabi Daud bagaikan adonan roti lunaknya.",[["۞ وَلَقَدْ","Dan sungguh"],["ءَاتَيْنَا","Kami memberi"],["دَاوُۥدَ","Dawood"],["مِنَّا","daripada Kami"],["فَضْلًۭا ۖ","Bounty"],["يَـٰجِبَالُ","Wahai gunung"],["أَوِّبِى","Ulang pujian"],["مَعَهُۥ","dengan dia"],["وَٱلطَّيْرَ ۖ","dan burung"],["وَأَلَنَّا","Dan Kami jadikan mudah lentur"],["لَهُ","baginya"],["ٱلْحَدِيدَ","besi"]]],"3617":["Dan kami berfirman pula, (\"Buatlah) dari besi itu (baju besi yang besar-besar) yang menutupi tubuh pemakainya, sehingga terseret ke tanah karena besarnya (dan ukurlah anyamannya) anyamlah baju besi itu, oleh karenanya pembuat baju besi dinamakan Sarrad. Maksudnya jadikanlah baju besi itu sehingga sesuai dengan ukuran pemakainya (dan kerjakanlah oleh kalian) oleh keluarga Daud bersama-sama Daud sendiri (amalan yang saleh. Sesungguhnya Aku melihat apa yang kalian kerjakan.\") maka, Aku akan membalasnya kepada kalian.",[["أَنِ","Itu"],["ٱعْمَلْ","buat"],["سَـٰبِغَـٰتٍۢ","kot penuh surat"],["وَقَدِّرْ","dan mengukur dengan tepat"],["فِى","[daripada]"],["ٱلسَّرْدِ ۖ","pautan (perisai)"],["وَٱعْمَلُوا۟","dan kerja"],["صَـٰلِحًا ۖ","kebenaran"],["إِنِّى","Sesungguhnya, Aku"],["بِمَا","tentang apa"],["تَعْمَلُونَ","kamu lakukan"],["بَصِيرٌۭ","Maha Melihat"]]],"3618":["(Dan) Kami tundukkan (bagi Sulaiman angin) menurut qiraat yang lain lafal Ar Riiha dibaca Ar Riihu yaitu dengan memperkirakan keberadaan lafal Taskhiirun (yang perjalanannya di waktu pagi) perjalanannya mulai dari pagi hingga waktu tergelincir matahari (sama dengan perjalanan sebulan, dan perjalanannya di waktu sore hari) yaitu mulai dari tergelincir matahari sampai terbenam (sama dengan perjalanan sebulan) maksudnya sama dengan perjalanan selama itu (dan Kami alirkan) Kami leburkan (cairan tembaga baginya) sehingga tembaga itu menjadi lebur selama tiga hari tiga malam, sebagaimana air mengalir dan umat manusia sampai sekarang dapat mengeksploitasinya berkat ilmu yang telah diberikan oleh Allah kepada Nabi Sulaiman. (Dan sebagian dari jin ada yang bekerja di bawah kekuasaannya dengan izin) yakni berdasarkan perintah (Rabbnya. Dan siapa yang menyimpang) menyeleweng (di antara mereka dari perintah Kami) yang menyuruhnya untuk taat kepada Nabi Sulaiman (Kami rasakan kepadanya azab neraka yang apinya menyala-nyala) di akhirat nanti. Menurut suatu pendapat azab tersebut terjadi di dunia, yaitu malaikat memukulnya dengan cambuk api, yang setiap pukulan dapat membakar dan menghanguskannya.",[["وَلِسُلَيْمَـٰنَ","Dan kepada Sulaiman"],["ٱلرِّيحَ","angin"],["غُدُوُّهَا","kursus paginya"],["شَهْرٌۭ","(adalah) sebulan"],["وَرَوَاحُهَا","dan kursus petangnya"],["شَهْرٌۭ ۖ","(adalah) sebulan"],["وَأَسَلْنَا","dan Kami jadikan mengalir"],["لَهُۥ","baginya"],["عَيْنَ","sebuah mata air"],["ٱلْقِطْرِ ۖ","(daripada) kuprum cair"],["وَمِنَ","Dan [daripada]"],["ٱلْجِنِّ","jin"],["مَن","yang"],["يَعْمَلُ","bekerja"],["بَيْنَ","sebelum dia"],["يَدَيْهِ","sebelum dia"],["بِإِذْنِ","dengan izin"],["رَبِّهِۦ ۖ","(dari) Tuhannya"],["وَمَن","Dan sesiapa"],["يَزِغْ","menyimpang"],["مِنْهُمْ","antara mereka"],["عَنْ","daripada"],["أَمْرِنَا","Perintah Kami"],["نُذِقْهُ","Kita akan buat dia rasa"],["مِنْ","daripada"],["عَذَابِ","azab"],["ٱلسَّعِيرِ","(dari) Api"]]],"3619":["(Para jin itu membuat untuk Sulaiman apa yang dikehendakinya dari gedung-gedung yang tinggi) bangunan-bangunan tinggi yang memakai tangga untuk orang yang mau memasukinya (dan patung-patung) lafal Tamaatsiil adalah bentuk jamak dari lafal Timtsaalun, yaitu segala sesuatu yang dibuat menurut gambaran objek yang dipahatnya. Maksudnya adalah patung-patung yang terbuat dari tembaga, ada pula yang terbuat dari kaca serta batu pualam. Perlu diketahui bahwa membuat patung atau gambar tidak diharamkan menurut syariat Nabi Sulaiman (dan piring-piring besar) lafal Jifaanin bentuk jamak dari lafal Jafnah (yang besarnya seperti kolam) lafal Jawaabii bentuk jamak dari lafal Jaabiyah artinya kolam yang besar; piring besar itu dapat dipakai untuk makan seribu orang (dan periuk yang tetap) berada di atas tungkunya serta tidak bergerak dari tempatnya karena saking besarnya. Periuk tersebut terbuat dari bukit negeri Yaman dan bagi orang yang memasak harus menaiki tangga, demikian pula bagi orang yang mau mengambil makanan daripadanya. Dan Kami berfirman, (\"Bekerjalah kalian) hai (keluarga Daud) untuk taat kepada Allah (sebagai tanda syukur) kepada-Nya atas apa yang telah Dia limpahkan kepada kalian berupa nikmat-nikmat. (Dan sedikit sekali dari hamba-hamba-Ku yang berterima kasih.\") yang mau bekerja untuk taat kepada-Ku sebagai ungkapan rasa syukurnya kepada-Ku atas nikmat-nikmat yang telah Kuberikan kepadanya.",[["يَعْمَلُونَ","Mereka bekerja"],["لَهُۥ","baginya"],["مَا","apa"],["يَشَآءُ","dia berkehendak"],["مِن","daripada"],["مَّحَـٰرِيبَ","bilik bertingkat"],["وَتَمَـٰثِيلَ","dan patung"],["وَجِفَانٍۢ","dan mangkuk"],["كَٱلْجَوَابِ","seperti takungan"],["وَقُدُورٍۢ","dan periuk masak"],["رَّاسِيَـٰتٍ ۚ","tetap"],["ٱعْمَلُوٓا۟","Kerja"],["ءَالَ","Wahai keluarga"],["دَاوُۥدَ","(daripada) Dawud"],["شُكْرًۭا ۚ","(dalam) kesyukuran"],["وَقَلِيلٌۭ","Tetapi sedikit"],["مِّنْ","daripada"],["عِبَادِىَ","budak-budak aku"],["ٱلشَّكُورُ","(adalah) bersyukur"]]],"3620":["(Maka tatkala Kami telah menetapkan terhadapnya) terhadap Sulaiman (kematian) ia mati dalam keadaan diam berdiri bertopang pada tongkatnya selama setahun penuh. Para jin masih tetap melakukan pekerjaan-pekerjaan yang berat sebagaimana biasanya, karena mereka tidak menduga bahwa Nabi Sulaiman telah mati. Ketika rayap menggerogoti tongkatnya lalu tongkat itu patah, kemudian Nabi Sulaiman jatuh terjungkal maka menjadi nyatalah kematiannya di mata para jin itu (tidak ada yang menunjukkan kepada mereka kematiannya itu kecuali rayap) lafal Al Ardhu adalah bentuk Mashdar dari lafal Uridhatul Khasyabatu, artinya kayu itu digerogoti oleh rayap (yang memakan tongkatnya) lafal Minsa-atahuu dapat pula dibaca Minsaatahuu, yakni tongkatnya, dinamakan demikian karena tongkat itu dipakai untuk mengusir dan menghardik. (Maka, tatkala ia telah tersungkur) dalam keadaan telah mati (tahulah jin itu) yakni jelaslah bagi mereka (bahwa) \"an\" berasal dari Anna yang kemudian ditakhfifkan, asalnya Annahum (kalau sekiranya mereka mengetahui yang gaib) antara lain ialah apa yang gaib di mata mereka tentang kematian Nabi Sulaiman (tentulah mereka tidak akan tetap dalam siksa yang menghinakan) kerja berat yang selama ini mereka lakukan, karena mereka menduga bahwa Nabi Sulaiman masih tetap hidup, berbeda halnya jika mereka mengetahui ilmu gaib. Mereka baru mengetahui kematiannya setelah satu tahun berdasarkan perhitungan masa yang diperkirakan jika sebuah tongkat dimakan rayap, sejak sehari semalam sesudah kematiannya.",[["فَلَمَّا","Kemudian apabila"],["قَضَيْنَا","Kami memutuskan"],["عَلَيْهِ","baginya"],["ٱلْمَوْتَ","kematian itu"],["مَا","tidak"],["دَلَّهُمْ","ditunjukkan kepada mereka"],["عَلَىٰ","[pada]"],["مَوْتِهِۦٓ","kematiannya"],["إِلَّا","kecuali"],["دَآبَّةُ","makhluk"],["ٱلْأَرْضِ","(dari) bumi"],["تَأْكُلُ","makan"],["مِنسَأَتَهُۥ ۖ","kakitangannya"],["فَلَمَّا","Tetapi apabila"],["خَرَّ","dia terjatuh"],["تَبَيَّنَتِ","menjadi jelas"],["ٱلْجِنُّ","(kepada) jin"],["أَن","bahawa"],["لَّوْ","jika"],["كَانُوا۟","mereka telah"],["يَعْلَمُونَ","diketahui"],["ٱلْغَيْبَ","yang ghaib"],["مَا","tidak"],["لَبِثُوا۟","mereka (akan) kekal"],["فِى","dalam"],["ٱلْعَذَابِ","azab"],["ٱلْمُهِينِ","memalukan"]]],"3621":["(Sesungguhnya bagi kaum Saba) lafal Saba dapat dibaca dengan memakai harakat Tanwin pada akhirnya atau bisa juga tidak. Saba adalah nama suatu kabilah bangsa Arab yang diambil dari nenek moyang mereka (di tempat kediaman mereka) di negeri Yaman (ada tanda) yang menunjukkan akan kekuasaan Allah swt. (yaitu dua buah kebun) lafal Jannataani ini menjadi Badal dari lafal Aayatun (di sebelah kanan dan di sebelah kiri) lembah tempat mereka tinggal. Dan dikatakan kepada mereka, (\"Makanlah oleh kalian dari rezeki Rabb kalian dan bersyukurlah kalian kepada-Nya.\") atas apa yang telah dikaruniakan-Nya kepada kalian berupa nikmat-nikmat yang ada di negeri Saba. (Negeri kalian, adalah negeri yang baik) tidak ada tanah yang tandus, tidak ada nyamuk, tidak ada lalat, tidak ada lalat pengisap darah, tidak ada kalajengking dan tidak ada ular. Seandainya ada orang asing lewat ke negeri itu dan pada bajunya terdapat kutu, maka kutu itu otomatis akan mati karena harum dan bersihnya udara negeri Saba. (Dan) Allah (Rabb Yang Maha Pengampun.)",[["لَقَدْ","Sungguh"],["كَانَ","(ada) ada"],["لِسَبَإٍۢ","untuk Saba"],["فِى","dalam"],["مَسْكَنِهِمْ","tempat kediaman mereka"],["ءَايَةٌۭ ۖ","tanda:"],["جَنَّتَانِ","Dua taman"],["عَن","pada"],["يَمِينٍۢ","(yang) betul"],["وَشِمَالٍۢ ۖ","dan (di sebelah) kiri"],["كُلُوا۟","makan"],["مِن","daripada"],["رِّزْقِ","(peruntukan)."],["رَبِّكُمْ","Tuhanmu"],["وَٱشْكُرُوا۟","dan bersyukurlah"],["لَهُۥ ۚ","kepada-Nya"],["بَلْدَةٌۭ","Sebuah tanah"],["طَيِّبَةٌۭ","kebaikan"],["وَرَبٌّ","dan Tuhan"],["غَفُورٌۭ","Selalu Memaafkan"]]],"3622":["(Tetapi mereka berpaling) tidak mau bersyukur kepada-Nya dan bahkan mereka kafir kepada-Nya (maka Kami datangkan kepada mereka banjir yang besar) lafal Al 'Arim adalah bentuk jamak dari lafal 'Urmah yang artinya adalah bendungan yang menampung air sampai waktu yang dibutuhkan. Maksudnya dam yang membendung kebutuhan air mereka pecah sehingga menenggelamkan kebun-kebun dan harta benda mereka (dan Kami ganti kedua kebun mereka dengan dua kebun yang ditumbuhi) lafal Dzawaatai merupakan bentuk Tatsniyah dari lafal Dzawaatun yang Mufrad (pohon-pohon yang berbuah pahit) yang sangat pahit buahnya lagi tidak enak rasanya; dapat dibaca Ukuli Khamthin yaitu dengan di-mudhaf-kan, lafal Ukulin ini bermakna Maakuulin yaitu yang dimakan sebagaimana dapat pula dibaca Ukulin Khamthin, lalu dibaca Ukulin Wa Khamtin (pohon Atsl dan sedikit pohon Sidr).",[["فَأَعْرَضُوا۟","Tetapi mereka berpaling"],["فَأَرْسَلْنَا","maka Kami hantarkan"],["عَلَيْهِمْ","ke atas mereka"],["سَيْلَ","(yang) banjir"],["ٱلْعَرِمِ","(dari) empangan"],["وَبَدَّلْنَـٰهُم","dan Kami ganti untuk mereka"],["بِجَنَّتَيْهِمْ","dua kebun mereka"],["جَنَّتَيْنِ","(dengan) dua taman"],["ذَوَاتَىْ","menghasilkan buah"],["أُكُلٍ","menghasilkan buah"],["خَمْطٍۢ","pahit"],["وَأَثْلٍۢ","dan tamariska"],["وَشَىْءٍۢ","dan (beberapa) perkara"],["مِّن","daripada"],["سِدْرٍۢ","pokok lote"],["قَلِيلٍۢ","sedikit"]]],"3623":["(Demikianlah) penggantian itu (Kami memberi balasan kepada mereka karena kekafiran mereka) sebab kekafiran mereka. (Dan Kami tidak menjatuhkan pembalasan melainkan hanya kepada orang-orang yang sangat kafir) lafal Nujaazii dapat pula dibaca Yujaazii, artinya tidaklah diberi balasan azab melainkan hanya orang-orang yang sangat ingkar.",[["ذَٰلِكَ","Itu"],["جَزَيْنَـٰهُم","Kami membalas mereka"],["بِمَا","kerana"],["كَفَرُوا۟ ۖ","mereka kafir"],["وَهَلْ","Dan tidak"],["نُجَـٰزِىٓ","Kami membalas"],["إِلَّا","kecuali"],["ٱلْكَفُورَ","yang tidak bersyukur"]]],"3624":["(Dan Kami jadikan antara mereka) yakni penduduk negeri Saba yang berada di Yaman (dan antara negeri-negeri yang Kami limpahkan berkat kepadanya) dengan melimpahnya air dan banyaknya pohon-pohonan, yang dimaksud adalah kampung-kampung negeri Syam tempat lalu mereka untuk tujuan berdagang (beberapa negeri yang berdekatan) mulai dari Yaman sampai ke Syam (dan Kami tetapkan antara negeri-negeri itu jarak-jarak perjalanan) hingga mereka dapat beristirahat pada suatu tempat, kemudian menginap pada tempat lainnya sampai pada akhir perjalanan mereka. Di dalam perjalanan, mereka tak perlu lagi membawa bekal dan air. Kami katakan, (\"Berjalanlah kalian di kota-kota itu pada malam dan siang hari dengan aman\") tanpa merasa takut lagi, baik kalian melakukan perjalanan pada malam hari maupun pada siang hari.",[["وَجَعَلْنَا","Dan Kami jadikan"],["بَيْنَهُمْ","antara mereka"],["وَبَيْنَ","dan antara"],["ٱلْقُرَى","bandar-bandar"],["ٱلَّتِى","yang"],["بَـٰرَكْنَا","Kami telah memberkati"],["فِيهَا","di dalamnya"],["قُرًۭى","bandar-bandar"],["ظَـٰهِرَةًۭ","nampak"],["وَقَدَّرْنَا","Dan Kami tentukan"],["فِيهَا","antara mereka"],["ٱلسَّيْرَ ۖ","perjalanan itu"],["سِيرُوا۟","Perjalanan"],["فِيهَا","antara mereka"],["لَيَالِىَ","(menjelang) malam"],["وَأَيَّامًا","dan (mengikut) hari"],["ءَامِنِينَ","dengan selamat"]]],"3625":["(Mereka berkata, \"Ya Rabb kami! Jauhkanlah) menurut suatu qiraat huruf 'Ain-nya di-tasydid-kan (jarak perjalanan kami\") ke negeri Syam, maksudnya jadikanlah tempat-tempat yang dilalui itu menjadi padang sahara, supaya jarak perjalanan itu dianggap sangat jauh bagi orang-orang yang miskin, yaitu karena membutuhkan bekal-bekal yang banyak dan persediaan air yang cukup. Maka mereka mengingkari nikmat tersebut (dan mereka menganiaya diri mereka sendiri) dengan melakukan kekafiran (maka Kami jadikan mereka buah mulut) bagi orang-orang yang sesudah mereka dalam hal itu (dan Kami hancurkan mereka sehancur-hancurnya) Kami cerai-beraikan mereka dari negeri tempat tinggal mereka. (Sesungguhnya pada yang demikian itu) pada yang telah disebutkan itu (benar-benar terdapat tanda-tanda) yakni pelajaran (bagi setiap orang yang sabar) menahan diri dari perbuatan-perbuatan maksiat (lagi bersyukur) atas nikmat-nikmat-Nya.",[["فَقَالُوا۟","Tetapi mereka berkata"],["رَبَّنَا","Wahai Tuhan kami"],["بَـٰعِدْ","memanjangkan (jarak)"],["بَيْنَ","antara"],["أَسْفَارِنَا","perjalanan kami"],["وَظَلَمُوٓا۟","Dan mereka berbuat zalim"],["أَنفُسَهُمْ","diri mereka"],["فَجَعَلْنَـٰهُمْ","maka Kami jadikan mereka"],["أَحَادِيثَ","riwayat-riwayat"],["وَمَزَّقْنَـٰهُمْ","dan Kami mencerai-beraikan mereka"],["كُلَّ","(dalam) jumlah"],["مُمَزَّقٍ ۚ","penyebaran"],["إِنَّ","Sesungguhnya"],["فِى","dalam"],["ذَٰلِكَ","bahawa"],["لَـَٔايَـٰتٍۢ","sesungguhnya (adalah) tanda-tanda"],["لِّكُلِّ","untuk semua orang"],["صَبَّارٍۢ","sabar"],["شَكُورٍۢ","(dan) bersyukur"]]],"3626":["(Dan sesungguhnya telah membuktikan kebenaran) dapat dibaca Shadaqa atau Shaddaqa (terhadap mereka) terhadap orang-orang kafir, antara lain adalah penduduk negeri Saba (iblis akan kebenaran sangkaannya) bahwasanya apabila ia menggoda mereka, maka niscaya mereka akan mengikutinya (lalu mereka mengikutinya) maka benarlah dugaan iblis itu atau nyata benarlah apa yang diduga oleh iblis itu (kecuali) tetapi (sebagian dari orang-orang yang beriman) yang benar-benar beriman, tidak mau mengikuti iblis.",[["وَلَقَدْ","Dan sungguh"],["صَدَّقَ","didapati benar"],["عَلَيْهِمْ","tentang mereka"],["إِبْلِيسُ","Iblis"],["ظَنَّهُۥ","andaian beliau"],["فَٱتَّبَعُوهُ","maka mereka mengikutinya"],["إِلَّا","kecuali"],["فَرِيقًۭا","satu kumpulan"],["مِّنَ","daripada"],["ٱلْمُؤْمِنِينَ","orang yang beriman"]]],"3627":["(Dan tidak ada kekuasaan iblis terhadap mereka) maksudnya iblis tidak mempunyai kekuasaan apa-apa terhadap mereka (melainkan hanyalah agar Kami dapat mengetahui) yakni menyatakan (siapa yang beriman kepada adanya kehidupan akhirat dan siapa yang ragu-ragu tentang itu) maka kelak Kami akan membalasnya kepada masing-masing. (Dan Rabbmu Maha Memelihara segala sesuatu) yakni Maha Mengawasi.",[["وَمَا","Dan tidak"],["كَانَ","adalah"],["لَهُۥ","baginya"],["عَلَيْهِم","atas mereka"],["مِّن","sebarang"],["سُلْطَـٰنٍ","pihak berkuasa"],["إِلَّا","kecuali"],["لِنَعْلَمَ","yang Kami nyatakan"],["مَن","yang"],["يُؤْمِنُ","beriman"],["بِٱلْـَٔاخِرَةِ","di akhirat"],["مِمَّنْ","daripada (satu) siapa"],["هُوَ","[dia]"],["مِنْهَا","mengenainya"],["فِى","(berada) dalam"],["شَكٍّۢ ۗ","keraguan"],["وَرَبُّكَ","Dan Tuhanmu"],["عَلَىٰ","atas"],["كُلِّ","semua"],["شَىْءٍ","benda"],["حَفِيظٌۭ","(adalah) seorang Penjaga"]]],"3628":["(Katakanlah) hai Muhammad kepada orang-orang kafir Mekah, (\"Serulah mereka yang kalian anggap) sebagai tuhan-tuhan (selain Allah) untuk memberi manfaat kepada diri kalian sesuai dengan dugaan dan sangkaan kalian. Maka Allah berfirman mengenai yang dipertuhankan mereka itu (mereka tidak memiliki seberat) walau hanya seberat (zarah) kebaikan atau keburukan (di langit dan di bumi, dan mereka tidak mempunyai suatu saham pun dalam penciptaan langit dan bumi) tidak ikut andil (dan tidak ada bagi-Nya) yakni bagi Allah swt. (dari mereka) yang dianggap sebagai tuhan-tuhan itu (seorang pembantu pun\") yaitu yang membantu-Nya.",[["قُلِ","Katakanlah"],["ٱدْعُوا۟","Seruan"],["ٱلَّذِينَ","mereka yang"],["زَعَمْتُم","kamu mendakwa"],["مِّن","selain"],["دُونِ","selain"],["ٱللَّهِ ۖ","Allah"],["لَا","Tidak"],["يَمْلِكُونَ","mereka miliki"],["مِثْقَالَ","(yang) berat"],["ذَرَّةٍۢ","(dari) atom"],["فِى","dalam"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَلَا","dan bukan"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["وَمَا","dan bukan"],["لَهُمْ","bagi mereka"],["فِيهِمَا","dalam kedua-duanya"],["مِن","sebarang"],["شِرْكٍۢ","perkongsian"],["وَمَا","dan bukan"],["لَهُۥ","untuk Dia"],["مِنْهُم","daripada mereka"],["مِّن","sebarang"],["ظَهِيرٍۢ","penyokong"]]],"3629":["(Dan tiadalah berguna syafaat di sisi Allah) Maha Tinggi Allah, ayat ini merupakan sanggahan terhadap perkataan mereka, bahwa sesungguhnya tuhan-tuhan sesembahan mereka akan dapat memberikan syafaat kepada mereka di sisi-Nya (melainkan bagi orang yang telah diizinkan) dapat dibaca Adzina atau Udzina (baginya) untuk memberi syafaat itu (sehingga apabila telah dihilangkan ketakutan) dapat dibaca Fazza'a atau Fuzzi'a (dari hati mereka) karena ada orang yang diizinkan untuk memberi syafaat (mereka berkata) sebagian dari mereka berkata kepada sebagian yang lain karena mendapat berita gembira itu, (\"Apakah yang telah difirmankan oleh Rabb kalian?\") mengenai syafaat itu. (Mereka menjawab) \"Perkataan (yang benar\") yakni Dia telah memberi izin kepadanya untuk memberi syafaat (dan Dialah Yang Maha Tinggi) di atas semua makhluk-Nya dengan mengalahkan mereka semuanya (lagi Maha Besar) yakni Maha Agung.",[["وَلَا","Dan tidak"],["تَنفَعُ","faedah"],["ٱلشَّفَـٰعَةُ","syafaat itu"],["عِندَهُۥٓ","dengan Dia"],["إِلَّا","kecuali"],["لِمَنْ","untuk (seorang) siapa"],["أَذِنَ","Dia izinkan"],["لَهُۥ ۚ","baginya"],["حَتَّىٰٓ","Sehinggalah"],["إِذَا","apabila"],["فُزِّعَ","ketakutan dihilangkan"],["عَن","pada"],["قُلُوبِهِمْ","hati mereka"],["قَالُوا۟","mereka akan berkata"],["مَاذَا","Apa itu"],["قَالَ","Tuhanmu telah berfirman"],["رَبُّكُمْ ۖ","Tuhanmu telah berfirman"],["قَالُوا۟","Mereka akan berkata"],["ٱلْحَقَّ ۖ","Kebenaran"],["وَهُوَ","Dan Dia"],["ٱلْعَلِىُّ","(adalah) Yang Maha Tinggi"],["ٱلْكَبِيرُ","yang Maha Agung"]]],"3630":["(Katakanlah! \"Siapakah yang memberi rezeki kepada kalian dari langit) melalui hujan (dan dari bumi?\") melalui tumbuh-tumbuhan (Katakanlah! \"Allah\") jika mereka tidak mengatakan demikian, maka tidak akan ada jawaban lain yang benar (dan sesungguhnya kami atau kalian) yakni salah satu di antara kedua golongan (pasti berada dalam petunjuk atau dalam kesesatan yang nyata) nyata sesatnya, apakah kami atau kalian orang-orang kafir. Dikatakan dengan ungkapan yang samar demi untuk melunakkan hati orang yang kafir, dengan maksud menyeru mereka kepada iman, yaitu apabila mereka sesuai dengan Nabi saw.",[["۞ قُلْ","Katakanlah"],["مَن","Siapa"],["يَرْزُقُكُم","menyediakan (untuk) kamu"],["مِّنَ","daripada"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ ۖ","dan bumi"],["قُلِ","Katakanlah"],["ٱللَّهُ ۖ","Allah"],["وَإِنَّآ","Dan sesungguhnya, kita"],["أَوْ","atau"],["إِيَّاكُمْ","kamu"],["لَعَلَىٰ","(ada) pasti atas"],["هُدًى","bimbingan"],["أَوْ","atau"],["فِى","dalam"],["ضَلَـٰلٍۢ","ralat"],["مُّبِينٍۢ","yang nyata"]]],"3631":["(Katakanlah! \"Kalian tidak akan ditanya tentang dosa yang kami perbuat) tentang dosa-dosa kami (dan kami tidak akan ditanya pula tentang apa yang kalian perbuat\") karena sesungguhnya kami berlepas diri dari kalian.",[["قُل","Katakanlah"],["لَّا","Tidak"],["تُسْـَٔلُونَ","kamu akan ditanya"],["عَمَّآ","tentang apa"],["أَجْرَمْنَا","dosa yang kita lakukan"],["وَلَا","dan bukan"],["نُسْـَٔلُ","kita akan ditanya"],["عَمَّا","tentang apa"],["تَعْمَلُونَ","kamu lakukan"]]],"3632":["(Katakanlah! \"Rabb kita akan mengumpulkan kita semua) kelak di hari kiamat (kemudian Dia memberi keputusan) memutuskan (antara kita dengan benar) maka orang-orang yang benar akan dimasukkan-Nya ke dalam surga, dan orang-orang yang salah akan dimasukkan-Nya ke dalam neraka. (Dan Dialah Maha Pemberi keputusan) Yang menghukumi (lagi Maha Mengetahui\") tentang keputusan hukum yang diambil-Nya.",[["قُلْ","Katakanlah"],["يَجْمَعُ","Akan berkumpul"],["بَيْنَنَا","kita bersama"],["رَبُّنَا","Tuhan kami"],["ثُمَّ","kemudian"],["يَفْتَحُ","Dia akan menilai"],["بَيْنَنَا","antara kita"],["بِٱلْحَقِّ","dalam kebenaran"],["وَهُوَ","Dan Dia"],["ٱلْفَتَّاحُ","(ialah) Hakim"],["ٱلْعَلِيمُ","yang Maha Mengetahui"]]],"3633":["(Katakanlah! \"Perlihatkanlah kepadaku) maksudnya beritahukanlah kepadaku (sesembahan-sesembahan yang kalian hubungkan dengan Dia sebagai sekutu-sekutu-Nya) untuk kalian sembah (sekali-kali tidak mungkin! Dialah Allah Yang Maha Perkasa) yakni Maha Menang atas semua perkara-Nya (lagi Maha Bijaksana\") di dalam mengatur makhluk-Nya, maka tiadalah bagi-Nya sekutu dalam kerajaan-Nya.",[["قُلْ","Katakanlah"],["أَرُونِىَ","Tunjukkan aku"],["ٱلَّذِينَ","mereka yang"],["أَلْحَقْتُم","kamu telah menyertai"],["بِهِۦ","dengan Dia"],["شُرَكَآءَ ۖ","(sebagai) rakan kongsi"],["كَلَّا ۚ","sama sekali tidak"],["بَلْ","Bahkan"],["هُوَ","Dia"],["ٱللَّهُ","(ialah) Allah"],["ٱلْعَزِيزُ","Yang Maha Perkasa"],["ٱلْحَكِيمُ","Yang Maha Bijaksana"]]],"3634":["(Dan Kami tidak mengutus kamu, melainkan untuk semua) lafal Kaaffatan berkedudukan menjadi Hal atau kata keterangan keadaan dari lafal An Naas yang sesudahnya, didahulukan mengingat kedudukannya yang sangat penting (manusia sebagai pembawa berita gembira) kepada orang-orang yang beriman, bahwa mereka akan masuk surga (dan sebagai pemberi peringatan) kepada orang-orang kafir bahwa mereka akan dimasukkan ke dalam neraka (tetapi kebanyakan manusia) yakni orang-orang kafir Mekah (tidak mengetahui hal ini).",[["وَمَآ","Dan tidak"],["أَرْسَلْنَـٰكَ","Kami telah menghantar kamu"],["إِلَّا","kecuali"],["كَآفَّةًۭ","secara menyeluruh"],["لِّلنَّاسِ","kepada manusia"],["بَشِيرًۭا","(sebagai) pemberi khabar gembira"],["وَنَذِيرًۭا","dan (sebagai) pemberi amaran"],["وَلَـٰكِنَّ","Tetapi"],["أَكْثَرَ","kebanyakannya"],["ٱلنَّاسِ","[orang]"],["لَا","jangan"],["يَعْلَمُونَ","mengetahui"]]],"3635":["(Dan mereka berkata, \"Kapankah datangnya janji ini) yakni azab yang kamu janjikan itu (jika kamu adalah orang-orang yang benar?\") dalam janjimu itu.",[["وَيَقُولُونَ","Dan mereka berkata"],["مَتَىٰ","Apabila"],["هَـٰذَا","(adalah) ini"],["ٱلْوَعْدُ","janji"],["إِن","jika"],["كُنتُمْ","kamu"],["صَـٰدِقِينَ","jujur"]]],"3636":["(Katakanlah! \"Bagi kalian ada hari yang telah dijanjikan yang tiada dapat kalian minta mundur daripadanya barang sesaat pun dan tidak pula kalian dapat meminta supaya diajukan\") daripadanya, hari yang dimaksud adalah hari kiamat.",[["قُل","Katakanlah"],["لَّكُم","Untuk kamu"],["مِّيعَادُ","(ialah) pelantikan"],["يَوْمٍۢ","(dari) sehari"],["لَّا","tidak"],["تَسْتَـْٔخِرُونَ","kamu boleh menangguhkan"],["عَنْهُ","[daripada] itu"],["سَاعَةًۭ","(selama) satu jam"],["وَلَا","dan bukan"],["تَسْتَقْدِمُونَ","(boleh) kamu mendahului (ia)"]]],"3637":["(Dan orang-orang kafir berkata) yakni sebagian dari penduduk Mekah (\"Kami sekali-kali tidak akan beriman kepada Alquran ini dan tidak pula kepada kitab sebelumnya\") kitab-kitab yang telah mendahuluinya, seperti kitab Taurat dan Injil yang di dalam kedua kitab tersebut disebutkan tentang adanya hari berbangkit, demikian itu karena mereka ingkar kepada Alquran. Lalu Allah berfirman mengenai mereka itu, (\"Dan kalau kamu lihat) hai Muhammad ketika orang-orang yang lalim itu) yakni orang-orang yang kafir (dihadapkan kepada Rabbnya, sebagian dari mereka menghadapkan perkataan kepada sebagian yang lain. Orang-orang yang dianggap lemah berkata) yaitu para pengikut dari mereka (kepada orang-orang yang menyombongkan diri) yakni para pemimpinnya, ('Kalau tidak karena kalian) maksudnya seandainya kalian tidak menghalang-halangi kami untuk beriman (tentulah kami menjadi orang-orang yang beriman') kepada Nabi saw.",[["وَقَالَ","Dan katakan"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["لَن","Tidak akan pernah"],["نُّؤْمِنَ","kami beriman"],["بِهَـٰذَا","dalam ini"],["ٱلْقُرْءَانِ","Quran"],["وَلَا","dan bukan"],["بِٱلَّذِى","dalam (itu) yang"],["بَيْنَ","(ada) sebelum itu"],["يَدَيْهِ ۗ","(ada) sebelum itu"],["وَلَوْ","Tetapi jika"],["تَرَىٰٓ","kamu (boleh) lihat"],["إِذِ","apabila"],["ٱلظَّـٰلِمُونَ","orang yang zalim"],["مَوْقُوفُونَ","akan dibuat berdiri"],["عِندَ","sebelum"],["رَبِّهِمْ","Tuhan mereka"],["يَرْجِعُ","akan membuang balik"],["بَعْضُهُمْ","sebahagian mereka"],["إِلَىٰ","kepada"],["بَعْضٍ","yang lain"],["ٱلْقَوْلَ","perkataan itu"],["يَقُولُ","Akan berkata"],["ٱلَّذِينَ","orang yang"],["ٱسْتُضْعِفُوا۟","telah ditindas"],["لِلَّذِينَ","kepada mereka yang"],["ٱسْتَكْبَرُوا۟","adalah sombong"],["لَوْلَآ","Jika tidak"],["أَنتُمْ","(untuk) kamu"],["لَكُنَّا","sesungguhnya kami (akan) begitu"],["مُؤْمِنِينَ","orang yang beriman"]]],"3638":["(Orang-orang yang menyombongkan diri berkata kepada orang-orang yang dianggap lemah, 'Kamikah yang telah menghalang-halangi kalian dari petunjuk sesudah petunjuk itu datang kepada kalian?) Tidak, (sebenarnya kalian sendirilah orang-orang yang berdosa') terhadap diri kalian sendiri.",[["قَالَ","Akan berkata"],["ٱلَّذِينَ","orang yang"],["ٱسْتَكْبَرُوا۟","adalah sombong"],["لِلَّذِينَ","kepada mereka"],["ٱسْتُضْعِفُوٓا۟","yang ditindas"],["أَنَحْنُ","Adakah kita"],["صَدَدْنَـٰكُمْ","mengelak kamu"],["عَنِ","daripada"],["ٱلْهُدَىٰ","bimbingan"],["بَعْدَ","selepas"],["إِذْ","apabila"],["جَآءَكُم ۖ","ia telah datang kepada kamu"],["بَلْ","Bahkan"],["كُنتُم","kamu dahulu"],["مُّجْرِمِينَ","penjenayah"]]],"3639":["(Dan orang-orang yang dianggap lemah berkata kepada orang-orang yang menyombongkan diri, 'Sebenarnya tipu daya di waktu malam hari dan siang hari) yaitu tipu daya kalian terhadap kami yang kalian lakukan malam dan siang hari (ketika kalian menyeru kami supaya kami kafir kepada Allah dan menjadikan sekutu-sekutu bagi-Nya.') (Mereka menyembunyikan) kedua golongan itu, yaitu mereka yang menjadi pengikut kesesatan dan yang menjadi pemimpin kesesatan (penyesalannya) karena tidak mau beriman kepada Nabi saw. (tatkala mereka melihat azab.\") masing-masing golongan menyembunyikan penyesalannya karena takut dicela. (Dan Kami pasang belenggu di leher orang-orang yang kafir) di dalam neraka. (Tiadalah) (mereka dibalas melainkan) dengan pembalasan (apa yang telah mereka kerjakan) di dunia.",[["وَقَالَ","Dan akan berkata"],["ٱلَّذِينَ","orang yang"],["ٱسْتُضْعِفُوا۟","telah ditindas"],["لِلَّذِينَ","kepada mereka yang"],["ٱسْتَكْبَرُوا۟","adalah sombong"],["بَلْ","Bahkan"],["مَكْرُ","(ia adalah) plot"],["ٱلَّيْلِ","(menjelang) malam"],["وَٱلنَّهَارِ","dan (mengikut) hari"],["إِذْ","apabila"],["تَأْمُرُونَنَآ","kamu telah memesan kepada kami"],["أَن","bahawa"],["نَّكْفُرَ","kita tak beriman"],["بِٱللَّهِ","kepada Allah"],["وَنَجْعَلَ","dan kami sediakan"],["لَهُۥٓ","untuk Dia"],["أَندَادًۭا ۚ","sama"],["وَأَسَرُّوا۟","Tetapi mereka akan menyembunyikan"],["ٱلنَّدَامَةَ","penyesalan itu"],["لَمَّا","apabila"],["رَأَوُا۟","mereka lihat"],["ٱلْعَذَابَ","azab"],["وَجَعَلْنَا","Dan Kami akan meletakkan"],["ٱلْأَغْلَـٰلَ","belenggu"],["فِىٓ","pada"],["أَعْنَاقِ","(the) leher"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟ ۚ","kufur"],["هَلْ","akan"],["يُجْزَوْنَ","mereka mendapat balasan"],["إِلَّا","kecuali"],["مَا","(untuk) apa"],["كَانُوا۟","mereka dahulu"],["يَعْمَلُونَ","lakukan"]]],"3640":["(Dan Kami tidak mengutus kepada suatu negeri seorang pemberi peringatan pun, melainkan orang-orang yang hidup mewah di negeri itu berkata) yakni para pemimpinnya hidup bergelimang dengan kemewahan, (\"Sesungguhnya kami mengingkari apa yang kamu diutus untuk menyampaikannya.\")",[["وَمَآ","Dan tidak"],["أَرْسَلْنَا","Kami utus"],["فِى","kepada"],["قَرْيَةٍۢ","sebuah bandar"],["مِّن","sebarang"],["نَّذِيرٍ","pemberi amaran"],["إِلَّا","tetapi"],["قَالَ","berkata"],["مُتْرَفُوهَآ","yang kaya raya"],["إِنَّا","Sesungguhnya kita"],["بِمَآ","pada apa"],["أُرْسِلْتُم","kamu telah dihantar"],["بِهِۦ","dengan"],["كَـٰفِرُونَ","(adalah) orang-orang kafir"]]],"3641":["(Dan mereka berkata, \"Kami lebih banyak mempunyai harta dan anak-anak) daripada orang-orang yang beriman (dan kami sekali-kali tidak akan diazab.\")",[["وَقَالُوا۟","Dan mereka berkata"],["نَحْنُ","Kami"],["أَكْثَرُ","(mempunyai) lebih"],["أَمْوَٰلًۭا","kekayaan"],["وَأَوْلَـٰدًۭا","dan kanak-kanak"],["وَمَا","dan bukan"],["نَحْنُ","kita"],["بِمُعَذَّبِينَ","akan dihukum"]]],"3642":["(Katakanlah! \"Sesungguhnya Rabbku melapangkan rezeki) meluaskannya (bagi siapa yang dikehendaki-Nya) sebagai ujian (dan membatasinya) menyempitkannya bagi siapa yang dikehendakinya sebagai cobaan baginya (akan tetapi kebanyakan manusia) orang-orang kafir Mekah (tidak mengetahui\") hal tersebut.",[["قُلْ","Katakanlah"],["إِنَّ","Sesungguhnya"],["رَبِّى","Tuhanku"],["يَبْسُطُ","memanjang"],["ٱلرِّزْقَ","peruntukan itu"],["لِمَن","untuk siapa"],["يَشَآءُ","Dia kehendaki"],["وَيَقْدِرُ","dan menyekat"],["وَلَـٰكِنَّ","tetapi"],["أَكْثَرَ","kebanyakannya"],["ٱلنَّاسِ","[orang]"],["لَا","jangan"],["يَعْلَمُونَ","mengetahui"]]],"3643":["(Dan sekali-kali bukanlah harta dan bukan pula anak-anak kalian yang mendekatkan kalian kepada Kami sedikit pun) yang dapat mendekatkan diri kalian kepada Kami (tetapi) (orang-orang yang beriman dan mengerjakan amal-amal saleh, mereka itulah yang memperoleh balasan yang berlipat ganda disebabkan apa yang telah mereka kerjakan;) yakni sebagai balasan amalnya, yaitu satu amal kebaikan akan dibalas sepuluh kali lipat dan lebih banyak lagi dari itu (dan mereka di tempat-tempat yang tinggi) di dalam surga (hidup aman sentosa) tidak akan mati dan tidak akan tertimpa penyakit dan lain sebagainya. Menurut qiraat yang lain lafal Ghurufaati dibaca Ghurfah dalam bentuk Mufrad tetapi maknanya jamak.",[["وَمَآ","Dan tidak"],["أَمْوَٰلُكُمْ","kekayaan kamu"],["وَلَآ","dan bukan"],["أَوْلَـٰدُكُم","anak-anak kamu"],["بِٱلَّتِى","[bahawa]"],["تُقَرِّبُكُمْ","akan membawa kamu dekat"],["عِندَنَا","kepada Kami"],["زُلْفَىٰٓ","(dalam) kedudukan"],["إِلَّا","tetapi"],["مَنْ","sesiapa sahaja"],["ءَامَنَ","beriman"],["وَعَمِلَ","dan melakukan"],["صَـٰلِحًۭا","kebenaran"],["فَأُو۟لَـٰٓئِكَ","kemudian mereka"],["لَهُمْ","bagi mereka"],["جَزَآءُ","(akan menjadi) pahala"],["ٱلضِّعْفِ","dua kali ganda"],["بِمَا","bagi apa"],["عَمِلُوا۟","mereka lakukan"],["وَهُمْ","dan mereka"],["فِى","(akan) masuk"],["ٱلْغُرُفَـٰتِ","kediaman yang tinggi"],["ءَامِنُونَ","selamat"]]],"3644":["(Dan orang-orang yang berusaha menentang ayat-ayat Kami) yakni membatalkan Alquran (dengan anggapan untuk dapat melepaskan diri dari azab Kami) yakni mereka menganggap Kami tidak mampu mengazab mereka dan mereka dapat meloloskan diri dari azab Kami (mereka itu dimasukkan ke dalam azab.)",[["وَٱلَّذِينَ","Dan orang yang"],["يَسْعَوْنَ","berusaha"],["فِىٓ","terhadap"],["ءَايَـٰتِنَا","Ayat Kami"],["مُعَـٰجِزِينَ","(untuk) menyebabkan kegagalan"],["أُو۟لَـٰٓئِكَ","mereka"],["فِى","ke dalam"],["ٱلْعَذَابِ","azab"],["مُحْضَرُونَ","(akan) dibawa"]]],"3645":["(Katakanlah! \"Sesungguhnya Rabbku melapangkan rezeki) meluaskannya (bagi siapa yang dikehendaki-Nya di antara hamba-hamba-Nya) sebagai ujian buatnya (dan membatasinya) menyempitkannya (baginya) sesudah Dia melapangkannya, atau Dia menyempitkannya bagi siapa yang dikehendaki-Nya sebagai cobaan buatnya. (Dan barang apa saja yang kalian nafkahkan) dalam hal kebaikan (maka Allah akan menggantinya dan Dialah Pemberi rezeki yang sebaik-baiknya.\") dikatakan, setiap orang memberi rezeki kepada keluarganya, yakni dari rezeki Allah swt.",[["قُلْ","Katakanlah"],["إِنَّ","Sesungguhnya"],["رَبِّى","Tuhanku"],["يَبْسُطُ","memanjang"],["ٱلرِّزْقَ","peruntukan itu"],["لِمَن","untuk siapa"],["يَشَآءُ","Dia kehendaki"],["مِنْ","daripada"],["عِبَادِهِۦ","hambanya"],["وَيَقْدِرُ","dan menyekat"],["لَهُۥ ۚ","baginya"],["وَمَآ","Tetapi apa"],["أَنفَقْتُم","kamu belanjakan"],["مِّن","daripada"],["شَىْءٍۢ","sesuatu"],["فَهُوَ","kemudian Dia"],["يُخْلِفُهُۥ ۖ","akan membayarnya"],["وَهُوَ","dan Dia"],["خَيْرُ","(adalah) Terbaik"],["ٱلرَّٰزِقِينَ","(dari) Pembekal"]]],"3646":["(Dan) ingatlah (hari, yang di waktu itu, Allah mengumpulkan mereka semuanya) yakni orang-orang musyrik (kemudian Allah berfirman kepada malaikat, \"Apakah mereka ini) dapat dibaca Tahqiq dan Tas-hil (dahulu menyembah kalian?\")",[["وَيَوْمَ","Dan (hari) itu"],["يَحْشُرُهُمْ","Dia akan mengumpulkan mereka"],["جَمِيعًۭا","semua"],["ثُمَّ","kemudian"],["يَقُولُ","Dia akan berkata"],["لِلْمَلَـٰٓئِكَةِ","kepada para Malaikat"],["أَهَـٰٓؤُلَآءِ","Adakah kamu ini"],["إِيَّاكُمْ","Adakah kamu ini"],["كَانُوا۟","mereka adalah"],["يَعْبُدُونَ","beribadat"]]],"3647":["(Malaikat-malaikat itu menjawab, \"Maha Suci Engkau) dari semua sekutu (Engkaulah Pelindung kami, bukan mereka\") maksudnya tidak ada saling lindung-melindungi antara kami dan mereka dari pihak kami (bahkan) lafal Bal di sini menunjukkan makna Intiqal, yakni sebenarnya (mereka telah menyembah jin) setan-setan, yaitu mereka menaati setan-setan yang menyuruh mereka untuk menyembah kami (kebanyakan mereka beriman kepada jin) yakni mereka selalu mempercayai apa yang dikatakan oleh jin kepada mereka.",[["قَالُوا۟","Mereka akan berkata"],["سُبْحَـٰنَكَ","Maha Suci Engkau"],["أَنتَ","kamu"],["وَلِيُّنَا","(adalah) Pelindung kami"],["مِن","bukan mereka"],["دُونِهِم ۖ","bukan mereka"],["بَلْ","Bahkan"],["كَانُوا۟","mereka gunakan"],["يَعْبُدُونَ","(untuk) beribadat"],["ٱلْجِنَّ ۖ","jin"],["أَكْثَرُهُم","kebanyakan mereka"],["بِهِم","dalam diri mereka"],["مُّؤْمِنُونَ","(adalah) orang-orang yang beriman"]]],"3648":["Allah swt. berfirman, (\"Maka pada hari ini sebagian kalian terhadap sebagian yang lain tidak memiliki) yakni orang-orang yang disembah terhadap orang-orang yang menyembahnya tidak memiliki (kemanfaatan) yaitu syafaat (dan tidak pula kemudaratan\") yaitu hak mengazab. (Dan Kami katakan kepada orang-orang yang zalim) yakni kepada orang-orang kafir, (\"Rasakanlah oleh kalian azab neraka yang dahulunya kalian dustakan.\")",[["فَٱلْيَوْمَ","Tetapi hari ini"],["لَا","tidak"],["يَمْلِكُ","memiliki kuasa"],["بَعْضُكُمْ","sebahagian daripada kamu"],["لِبَعْضٍۢ","pada orang lain"],["نَّفْعًۭا","untuk mendapat manfaat"],["وَلَا","dan bukan"],["ضَرًّۭا","untuk membahayakan"],["وَنَقُولُ","dan Kami akan berkata"],["لِلَّذِينَ","kepada mereka"],["ظَلَمُوا۟","siapa yang salah"],["ذُوقُوا۟","rasa"],["عَذَابَ","azab"],["ٱلنَّارِ","(dari) api"],["ٱلَّتِى","yang"],["كُنتُم","kamu guna"],["بِهَا","kepada [itu]"],["تُكَذِّبُونَ","menafikan"]]],"3649":["(Dan apabila dibacakan kepada mereka ayat-ayat Kami) yakni Alquran (yang terang) yang jelas melalui lisan nabi Kami, yaitu Muhammad saw. (mereka berkata, \"Orang ini tiada lain hanyalah seorang laki-laki yang ingin menghalangi kalian dari apa yang disembah oleh bapak-bapak kalian\") yaitu berupa berhala-berhala (dan mereka berkata, \"Tidak lain ini) yakni Alquran ini (hanyalah kebohongan) (yang diada-adakan saja\") atas nama Allah. (Dan orang-orang kafir berkata terhadap kebenaran) yakni Alquran (tatkala kebenaran itu datang kepada mereka, \"Tidak lain) (ini hanyalah sihir yang nyata\") sihir yang jelas.",[["وَإِذَا","Dan apabila"],["تُتْلَىٰ","dibacakan"],["عَلَيْهِمْ","kepada mereka"],["ءَايَـٰتُنَا","Ayat Kami"],["بَيِّنَـٰتٍۢ","yang nyata"],["قَالُوا۟","mereka berkata"],["مَا","Tidak"],["هَـٰذَآ","(adalah) ini"],["إِلَّا","tetapi"],["رَجُلٌۭ","seorang lelaki"],["يُرِيدُ","yang berkehendak"],["أَن","kepada"],["يَصُدَّكُمْ","menghalang kamu"],["عَمَّا","daripada apa"],["كَانَ","digunakan"],["يَعْبُدُ","(untuk) beribadat"],["ءَابَآؤُكُمْ","nenek moyang kamu"],["وَقَالُوا۟","Dan mereka berkata"],["مَا","Tidak"],["هَـٰذَآ","(adalah) ini"],["إِلَّآ","kecuali"],["إِفْكٌۭ","satu pembohongan"],["مُّفْتَرًۭى ۚ","dicipta"],["وَقَالَ","Dan berkata"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["لِلْحَقِّ","tentang kebenaran"],["لَمَّا","apabila"],["جَآءَهُمْ","ia datang kepada mereka"],["إِنْ","Tidak"],["هَـٰذَآ","(adalah) ini"],["إِلَّا","kecuali"],["سِحْرٌۭ","sihir"],["مُّبِينٌۭ","jelas"]]],"3650":["(Dan Kami tidak pernah memberikan kepada mereka Kitab-kitab yang mereka baca dan sekali-kali tidak pernah pula mengutus kepada mereka sebelum kamu seorang pemberi peringatan pun) maka berdasarkan alasan apakah mereka mendustakanmu?",[["وَمَآ","Dan tidak"],["ءَاتَيْنَـٰهُم","Kami (telah) memberikan mereka"],["مِّن","sebarang"],["كُتُبٍۢ","kitab suci"],["يَدْرُسُونَهَا ۖ","yang boleh mereka pelajari"],["وَمَآ","dan bukan"],["أَرْسَلْنَآ","Kami utus"],["إِلَيْهِمْ","kepada mereka"],["قَبْلَكَ","sebelum kamu"],["مِن","sebarang"],["نَّذِيرٍۢ","pemberi amaran"]]],"3651":["(Dan orang-orang yang sebelum mereka telah mendustakan sedangkan orang-orang kafir itu belum sampai menerima) yakni orang-orang kafir Mekah (sepersepuluh dari apa yang telah Kami berikan kepada orang-orang dahulu itu) yaitu berupa kekuatan, usia yang panjang dan banyaknya harta (lalu mereka mendustakan rasul-rasul-Ku) yang Aku utus kepada mereka. (Maka alangkah hebatnya akibat kemurkaan-Ku) yaitu hukuman dan pembinasaan-Ku terhadap mereka, kemurkaan-Ku itu benar-benar pada tempatnya.",[["وَكَذَّبَ","Dan dinafikan"],["ٱلَّذِينَ","orang yang"],["مِن","(ada) sebelum mereka"],["قَبْلِهِمْ","(ada) sebelum mereka"],["وَمَا","dan bukan"],["بَلَغُوا۟","mereka telah capai"],["مِعْشَارَ","sepersepuluh"],["مَآ","apa"],["ءَاتَيْنَـٰهُمْ","Kami (telah) memberikan mereka"],["فَكَذَّبُوا۟","Tetapi mereka menafikan"],["رُسُلِى ۖ","Utusan-utusanku"],["فَكَيْفَ","jadi bagaimana"],["كَانَ","adalah"],["نَكِيرِ","penolakan aku"]]],"3652":["(Katakanlah! \"Sesungguhnya aku hendak memperingatkan kepada kalian suatu hal saja) yaitu (supaya kalian menghadap Allah) dengan ikhlas hanya karena-Nya (dua-dua) yakni berduaan (atau sendiri-sendiri) satu persatu (kemudian kalian pikirkan tentang -Muhammad-) sehingga kalian mengetahui (tidak ada pada diri kawan kalian ini) yakni Nabi Muhammad (penyakit gila sedikit pun) yakni kegilaan (tidak lain dia hanyalah pemberi peringatan bagi kalian sebelum) kalian menghadapi (azab yang keras.\") di akhirat nanti jika kalian mendurhakainya.",[["۞ قُلْ","Katakanlah"],["إِنَّمَآ","Hanya"],["أَعِظُكُم","Aku nasihatkan kamu"],["بِوَٰحِدَةٍ ۖ","untuk satu (perkara)"],["أَن","bahawa"],["تَقُومُوا۟","kamu berdiri"],["لِلَّهِ","kerana Allah"],["مَثْنَىٰ","(dalam) berpasangan"],["وَفُرَٰدَىٰ","dan (sebagai) individu"],["ثُمَّ","kemudian"],["تَتَفَكَّرُوا۟ ۚ","merenung"],["مَا","Tidak"],["بِصَاحِبِكُم","(ada dalam) temanmu"],["مِّن","sebarang"],["جِنَّةٍ ۚ","kegilaan"],["إِنْ","Tidak"],["هُوَ","dia"],["إِلَّا","(adalah) kecuali"],["نَذِيرٌۭ","seorang pemberi amaran"],["لَّكُم","bagi kamu"],["بَيْنَ","sebelum"],["يَدَىْ","sebelum"],["عَذَابٍۢ","azab"],["شَدِيدٍۢ","teruk"]]],"3653":["(Katakanlah) kepada mereka! (\"Upah apa pun yang aku minta kepada kalian) atas menyampaikan peringatan dan menyampaikan risalah Rabbku (maka upah itu untuk kalian) maksudnya aku tidak meminta upah apa pun atas hal ini. (Upahku tiada lain) tidak lain upahku (hanyalah dari Allah, dan Dia Maha Mengetahui segala sesuatu\") Maha Menyaksikan dan Maha Mengetahui tentang kebenaranku.",[["قُلْ","Katakanlah"],["مَا","Tidak"],["سَأَلْتُكُم","aku tanya kamu"],["مِّنْ","bagi"],["أَجْرٍۢ","sebarang bayaran"],["فَهُوَ","tetapi ia (adalah)"],["لَكُمْ ۖ","bagi kamu"],["إِنْ","Tidak"],["أَجْرِىَ","(ialah) bayaran aku"],["إِلَّا","tetapi"],["عَلَى","daripada"],["ٱللَّهِ ۖ","Allah"],["وَهُوَ","Dan Dia"],["عَلَىٰ","(sudah) tamat"],["كُلِّ","semua"],["شَىْءٍۢ","benda"],["شَهِيدٌۭ","seorang Saksi"]]],"3654":["(Katakanlah! \"Sesungguhnya Rabbku mewahyukan kebenaran) yakni menyampaikannya kepada nabi-nabi-Nya (Dia Maha Mengetahui segala yang gaib\") semua apa yang gaib dari makhluk-Nya baik yang di langit maupun yang di bumi.",[["قُلْ","Katakanlah"],["إِنَّ","Sesungguhnya"],["رَبِّى","Tuhanku"],["يَقْذِفُ","projek"],["بِٱلْحَقِّ","kebenaran"],["عَلَّـٰمُ","(yang) Maha Mengetahui"],["ٱلْغُيُوبِ","(dari) yang ghaib"]]],"3655":["(Katakanlah, \"Kebenaran telah datang) yakni agama Islam (dan yang batil itu tidak akan memulai) kekafiran itu tidak akan memulai (dan tidak pula akan mengulangi\") tidak akan ada bekasnya lagi.",[["قُلْ","Katakanlah"],["جَآءَ","Telah datang"],["ٱلْحَقُّ","kebenaran"],["وَمَا","dan bukan"],["يُبْدِئُ","(boleh) berasal"],["ٱلْبَـٰطِلُ","kepalsuan itu"],["وَمَا","dan bukan"],["يُعِيدُ","ulang"]]],"3656":["(Katakanlah! \"Jika aku sesat) dari kebenaran (maka sesungguhnya aku sesat atas kemudaratan diriku sendiri) yakni dosa kesesatanku ditanggung oleh diriku (dan jika aku mendapat petunjuk maka itu adalah disebabkan apa yang diwahyukan Rabbku kepadaku) berupa Alquran dan Hadis Hikmah. (Sesungguhnya Dia Maha Mendengar) Maha mengabulkan doa (lagi Maha Dekat.\")",[["قُلْ","Katakanlah"],["إِن","Jika"],["ضَلَلْتُ","aku tersilap"],["فَإِنَّمَآ","kemudian sahaja"],["أَضِلُّ","Aku akan tersilap"],["عَلَىٰ","terhadap"],["نَفْسِى ۖ","diri sendiri"],["وَإِنِ","Tetapi jika"],["ٱهْتَدَيْتُ","aku dibimbing"],["فَبِمَا","maka ia adalah dengan apa"],["يُوحِىٓ","mendedahkan"],["إِلَىَّ","kepada aku"],["رَبِّىٓ ۚ","Tuhanku"],["إِنَّهُۥ","Sesungguhnya Dia"],["سَمِيعٌۭ","(adalah) Yang Maha Mendengar"],["قَرِيبٌۭ","Selalu-Dekat"]]],"3657":["(Dan jika kamu melihat) hai Muhammad (ketika mereka terperanjat ketakutan) sewaktu mereka dibangkitkan, niscaya kamu akan melihat perkara yang hebat (maka mereka tidak dapat melepaskan diri) dari kekuasaan Kami yang dimaksud adalah dari azab Kami (dan mereka ditangkap dari tempat yang dekat) yaitu dari kubur mereka secara langsung.",[["وَلَوْ","Dan jika"],["تَرَىٰٓ","kamu (boleh) lihat"],["إِذْ","apabila"],["فَزِعُوا۟","mereka akan ketakutan"],["فَلَا","tetapi (akan ada) tidak"],["فَوْتَ","melarikan diri"],["وَأُخِذُوا۟","dan mereka akan ditangkap"],["مِن","daripada"],["مَّكَانٍۢ","sebuah tempat"],["قَرِيبٍۢ","dekat"]]],"3658":["(Dan di waktu itu mereka berkata, \"Kami beriman kepada-Nya) yakni kepada Nabi Muhammad, atau kepada Alquran (bagaimanakah mereka dapat mencapai) meraih keimanan; dapat dibaca Tanaawusy atau huruf Wau diganti menjadi Hamzah, sehingga bacaannya menjadi Tanaa-usy maksudnya amat mustahillah mereka dapat mencapai keimanan (dari tempat yang jauh itu\") dari tempatnya yang sekarang, karena mereka sekarang berada di alam akhirat dan tempat keimanan itu ada di dunia.",[["وَقَالُوٓا۟","Dan mereka akan berkata"],["ءَامَنَّا","Kami beriman"],["بِهِۦ","di dalamnya"],["وَأَنَّىٰ","Tetapi bagaimana"],["لَهُمُ","bagi mereka"],["ٱلتَّنَاوُشُ","(akan menjadi) yang menerima"],["مِن","daripada"],["مَّكَانٍۭ","sebuah tempat"],["بَعِيدٍۢ","jauh sekali"]]],"3659":["(Dan sesungguhnya mereka telah mengingkari Allah sebelum itu) sewaktu mereka hidup di dunia (dan mereka menduga-duga) meramal-ramal (tentang yang gaib dari tempat yang jauh) yaitu terhadap hal-hal yang tidak dapat dijangkau oleh pengetahuan mereka, karena mereka sewaktu di dunia mengatakan terhadap Nabi, bahwa Dia adalah penyihir, tukang syair dan tukang ramal. Mereka mengatakan tentang Alquran, bahwa itu adalah sihir, syair, dan ramalan.",[["وَقَدْ","Dan sungguh"],["كَفَرُوا۟","mereka kafir"],["بِهِۦ","di dalamnya"],["مِن","sebelum"],["قَبْلُ ۖ","sebelum"],["وَيَقْذِفُونَ","Dan mereka mengucapkan sangkaan"],["بِٱلْغَيْبِ","tentang yang ghaib"],["مِن","daripada"],["مَّكَانٍۭ","sebuah tempat"],["بَعِيدٍۢ","jauh sekali"]]],"3660":["(Dan dihalangi antara mereka dengan apa yang mereka ingini) yakni ingin beriman, maksudnya iman mereka tidak diterima lagi, karena waktunya sudah habis (sebagaimana dilakukan terhadap orang-orang yang serupa dengan mereka) yakni golongan-golongan mereka dalam hal kekafiran (pada masa dahulu) sebelum mereka. (Sesungguhnya mereka dahulu di dunia dalam keraguan yang mendalam) tentang hal-hal yang sekarang mereka imani; disebabkan sewaktu di dunia mereka tidak mau menganggap dalil-dalil yang menunjuk ke arahnya.",[["وَحِيلَ","Dan penghalang akan diletakkan"],["بَيْنَهُمْ","antara mereka"],["وَبَيْنَ","dan antara"],["مَا","apa"],["يَشْتَهُونَ","mereka inginkan"],["كَمَا","seperti"],["فُعِلَ","telah dilakukan"],["بِأَشْيَاعِهِم","dengan jenis mereka"],["مِّن","sebelum"],["قَبْلُ ۚ","sebelum"],["إِنَّهُمْ","Sesungguhnya mereka"],["كَانُوا۟","adalah"],["فِى","dalam"],["شَكٍّۢ","keraguan"],["مُّرِيبٍۭ","meresahkan"]]],"3661":["(Segala puji bagi Allah) Allah memuji diri-Nya dengan kalimat tersebut, sebagaimana keterangan yang telah disebutkan dalam awal surah As-Saba (Pencipta langit dan bumi) yang menciptakan keduanya tanpa konsep terlebih dahulu (Yang menjadikan malaikat sebagai utusan-utusan) kepada para nabi (yang mempunyai sayap, masing-masing ada yang dua, tiga dan empat. Allah menambahkan pada ciptaan-Nya) yakni menciptakan malaikat dan lain-lainnya (apa yang Dia kehendaki. Sesungguhnya Allah Maha Kuasa atas segala sesuatu.)",[["ٱلْحَمْدُ","Semua pujian"],["لِلَّهِ","bagi Allah"],["فَاطِرِ","Pemula"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ","dan bumi"],["جَاعِلِ","(Siapa) yang membuat"],["ٱلْمَلَـٰٓئِكَةِ","para Malaikat"],["رُسُلًا","utusan"],["أُو۟لِىٓ","mempunyai sayap"],["أَجْنِحَةٍۢ","mempunyai sayap"],["مَّثْنَىٰ","dua"],["وَثُلَـٰثَ","atau tiga"],["وَرُبَـٰعَ ۚ","atau empat"],["يَزِيدُ","Dia bertambah"],["فِى","dalam"],["ٱلْخَلْقِ","penciptaan"],["مَا","apa"],["يَشَآءُ ۚ","Dia kehendaki"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["عَلَىٰ","(berada) di atas"],["كُلِّ","setiap"],["شَىْءٍۢ","perkara"],["قَدِيرٌۭ","Maha Berkuasa"]]],"3662":["(Apa saja yang Allah anugerahkan kepada manusia berupa rahmat) seperti rezeki dan hujan (maka tidak ada seorang pun yang dapat menahannya; dan apa saja yang ditahan oleh Allah) dari hal-hal tersebut (maka tidak seorang pun yang sanggup untuk melepaskannya sesudah itu) sesudah Allah menahannya. (Dan Dialah Yang Maha Perkasa) Maha Menang atas perkara-Nya (lagi Maha Bijaksana) dalam perbuatan-Nya.",[["مَّا","Apa"],["يَفْتَحِ","Allah makbulkan"],["ٱللَّهُ","Allah makbulkan"],["لِلنَّاسِ","kepada manusia"],["مِن","daripada"],["رَّحْمَةٍۢ","belas kasihan"],["فَلَا","maka tiada"],["مُمْسِكَ","(boleh) menahan"],["لَهَا ۖ","ia"],["وَمَا","Dan apa"],["يُمْسِكْ","Dia menahan"],["فَلَا","maka tiada"],["مُرْسِلَ","(boleh) melepaskan"],["لَهُۥ","ia"],["مِنۢ","selepas itu"],["بَعْدِهِۦ ۚ","selepas itu"],["وَهُوَ","Dan Dia"],["ٱلْعَزِيزُ","(ialah) Yang Maha Perkasa"],["ٱلْحَكِيمُ","Yang Maha Bijaksana"]]],"3663":["(Hai manusia!) penduduk Mekah (Ingatlah akan nikmat Allah kepada kalian) yang telah menempatkan kalian di tanah suci dan yang mencegah serangan-serangan dari luar terhadap kalian. (Adakah sesuatu pencipta) huruf Min di sini adalah Zaidah atau tambahan, lafal Khaaliqin sebagai Mubtada (selain Allah) kalau dibaca Ghairu berarti menjadi Na'at atau sifat secara Mahall dari lafal Khaaliqin, kalau dibaca Ghairi berarti di'athafkan kepada lafal Khaaliqin secara Lafzhan, dan Khabar Mubtadanya adalah (yang dapat memberikan rezeki kepada kalian dari langit) yakni berupa hujan (dan) dari (bumi?) berupa tumbuh-tumbuhan. Istifham atau kata tanya di sini mengandung makna Taqrir, yakni tidak ada pencipta dan tidak ada pemberi rezeki selain Allah. (Tidak ada Tuhan selain Dia; maka mengapakah kalian berpaling) dari mentauhidkan-Nya? Padahal kalian telah mengakui, bahwa Dia adalah Yang Maha Pencipta dan Maha Pemberi rezeki.",[["يَـٰٓأَيُّهَا","Wahai"],["ٱلنَّاسُ","manusia"],["ٱذْكُرُوا۟","Ingat"],["نِعْمَتَ","(yang) nikmat"],["ٱللَّهِ","(milik) Allah"],["عَلَيْكُمْ ۚ","ke atas kamu"],["هَلْ","Adakah"],["مِنْ","(ada) mana-mana"],["خَـٰلِقٍ","pencipta"],["غَيْرُ","selain daripada Allah"],["ٱللَّهِ","selain daripada Allah"],["يَرْزُقُكُم","yang menyediakan untuk kamu"],["مِّنَ","daripada"],["ٱلسَّمَآءِ","langit"],["وَٱلْأَرْضِ ۚ","dan bumi"],["لَآ","(Ada) tidak"],["إِلَـٰهَ","tuhan"],["إِلَّا","tetapi"],["هُوَ ۖ","Dia"],["فَأَنَّىٰ","Kemudian, bagaimana"],["تُؤْفَكُونَ","(adakah) kamu tertipu"]]],"3664":["(Dan jika mereka mendustakan kamu) hai Muhammad, tentang ajaran tauhid yang engkau bawa dan berita adanya hari kebangkitan yang kamu sampaikan serta adanya hari penghisaban dan pembalasan amal perbuatan (maka sungguh telah didustakan pula rasul-rasul sebelum kamu) dalam hal tersebut maka bersabarlah kamu sebagaimana mereka bersabar. (Dan hanya kepada Allahlah dikembalikan segala urusan) di akhirat. Dia kelak akan mengazab orang-orang yang mendustakan dan menolong orang-orang yang berserah diri atau orang-orang muslim.",[["وَإِن","Dan jika"],["يُكَذِّبُوكَ","mereka menafikan kamu"],["فَقَدْ","maka sudah tentu"],["كُذِّبَتْ","telah dinafikan"],["رُسُلٌۭ","Utusan"],["مِّن","sebelum kamu"],["قَبْلِكَ ۚ","sebelum kamu"],["وَإِلَى","Dan kepada"],["ٱللَّهِ","Allah"],["تُرْجَعُ","kembali"],["ٱلْأُمُورُ","perkara-perkara"]]],"3665":["(Hai manusia! Sesungguhnya janji Allah) tentang adanya hari berbangkit dan lain-lainnya (adalah benar, maka sekali-kali janganlah kehidupan dunia memperdayakan kalian) sehingga kalian tidak mau beriman kepada adanya hari berbangkit dan lain-lainnya (dan sekali-kali janganlah memperdayakan kalian tentang Allah) tentang sifat dan Penyantun-Nya dan sifat Sabar-Nya yang menangguhkan kalian tidak diazab (orang yang pandai menipu) yakni setan.",[["يَـٰٓأَيُّهَا","Wahai"],["ٱلنَّاسُ","manusia"],["إِنَّ","Sesungguhnya"],["وَعْدَ","(janji) itu"],["ٱللَّهِ","(milik) Allah"],["حَقٌّۭ ۖ","(adalah) benar"],["فَلَا","Jadi (biar) jangan"],["تَغُرَّنَّكُمُ","menipu kamu"],["ٱلْحَيَوٰةُ","kehidupan"],["ٱلدُّنْيَا ۖ","dunia"],["وَلَا","dan (biar) jangan"],["يَغُرَّنَّكُم","menipu kamu"],["بِٱللَّهِ","tentang Allah"],["ٱلْغَرُورُ","si Penipu"]]],"3666":["(Sesungguhnya setan itu adalah musuh bagi kalian, maka anggaplah ia musuh) dengan cara taat kepada Allah dan tidak menaati setan (karena sesungguhnya setan-setan itu hanya mengajak golongannya) yakni pengikut-pengikutnya yang sama-sama kafir dengannya (supaya menjadi penghuni neraka yang menyala-nyala) yakni neraka yang keras siksaannya.",[["إِنَّ","Sesungguhnya"],["ٱلشَّيْطَـٰنَ","syaitan"],["لَكُمْ","(adalah) kepada kamu"],["عَدُوٌّۭ","seorang musuh"],["فَٱتَّخِذُوهُ","jadi bawa dia"],["عَدُوًّا ۚ","(sebagai) musuh"],["إِنَّمَا","Hanya"],["يَدْعُوا۟","dia mengajak"],["حِزْبَهُۥ","partinya"],["لِيَكُونُوا۟","bahawa mereka mungkin"],["مِنْ","antara"],["أَصْحَـٰبِ","(para) sahabat"],["ٱلسَّعِيرِ","(dari) Api"]]],"3667":["(Orang-orang yang kafir bagi mereka azab yang keras. Dan orang-orang yang beriman serta mengerjakan amal saleh bagi mereka ampunan dan pahala yang besar) ini penjelasan tentang nasib orang-orang yang menuruti kemauan setan dan orang-orang yang menentangnya, kelak di akhirat.",[["ٱلَّذِينَ","Orang yang"],["كَفَرُوا۟","kufur"],["لَهُمْ","bagi mereka"],["عَذَابٌۭ","(akan menjadi) azab"],["شَدِيدٌۭ ۖ","teruk"],["وَٱلَّذِينَ","dan mereka"],["ءَامَنُوا۟","yang beriman"],["وَعَمِلُوا۟","dan melakukan"],["ٱلصَّـٰلِحَـٰتِ","amal soleh"],["لَهُم","bagi mereka"],["مَّغْفِرَةٌۭ","(akan) pengampunan"],["وَأَجْرٌۭ","dan ganjaran"],["كَبِيرٌ","yang besar"]]],"3668":["Ayat ini diturunkan berkenaan dengan Abu Jahal dan orang-orang sepertinya. (Maka apakah orang yang dihiasi pekerjaannya yang buruk) karena setan telah menyulapnya (lalu ia menganggapnya baik?) lafal Man adalah Mubtada, sedangkan Khabarnya ialah, sebagaimana orang yang mendapat petunjuk dari Allah. Tentu saja tidak sama. Khabar ini disimpulkan dari ayat selanjutnya, yaitu, (Maka sesungguhnya Allah menyesatkan siapa yang dikehendaki-Nya dan menunjuki siapa yang dikehendaki-Nya; maka janganlah dirimu binasa sebab ulah mereka itu) yaitu atas orang-orang yang menganggap baik perbuatannya yang buruk itu (karena kesedihan) yaitu kamu merasa sedih karena mereka tidak mau beriman (Sesungguhnya Allah Maha Mengetahui apa yang mereka perbuat) kelak Dia akan membalasnya kepada mereka.",[["أَفَمَن","Maka adakah (dia) yang"],["زُيِّنَ","dibuat kelihatan adil"],["لَهُۥ","kepadanya"],["سُوٓءُ","(yang) jahat"],["عَمَلِهِۦ","(dari) perbuatannya"],["فَرَءَاهُ","supaya dia melihatnya"],["حَسَنًۭا ۖ","(sebagai) baik"],["فَإِنَّ","Kerana sesungguhnya"],["ٱللَّهَ","Allah"],["يُضِلُّ","biarlah sesat"],["مَن","yang"],["يَشَآءُ","Dia kehendaki"],["وَيَهْدِى","dan panduan"],["مَن","yang"],["يَشَآءُ ۖ","Dia kehendaki"],["فَلَا","Jadi (biar) jangan"],["تَذْهَبْ","keluar"],["نَفْسُكَ","jiwa kamu"],["عَلَيْهِمْ","bagi mereka"],["حَسَرَٰتٍ ۚ","(dalam) menyesal"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["عَلِيمٌۢ","Maha Mengetahui"],["بِمَا","tentang apa"],["يَصْنَعُونَ","mereka lakukan"]]],"3669":["(Dan Allah, Dialah Yang mengirimkan angin) menurut qiraat yang lain dibaca Ar Riih dalam bentuk Mufrad (lalu angin itu menggerakkan awan) lafal Mudhari' di sini untuk menceritakan keadaan di masa lalu, maksudnya angin itu menggerakkannya (lalu Kami halau awan itu) di dalam ungkapan ayat ini terkandung Iltifat dari dhamir Gaib (ke suatu negeri yang mati) tanah yang tandus yang tidak ada tumbuh-tumbuhannya. Dapat dibaca Mayyitin atau Mayitin (lalu Kami hidupkan dengan hujan itu bumi) yang dikenainya (setelah matinya) setelah ia mengalami kekeringan, yaitu Kami tumbuhkan padanya tumbuh-tumbuhan dan rumput-rumputan. (Demikianlah kebangkitan itu) cara membangkitkan yang mati menjadi hidup kembali.",[["وَٱللَّهُ","Dan Allah"],["ٱلَّذِىٓ","(ialah) Yang"],["أَرْسَلَ","menghantar"],["ٱلرِّيَـٰحَ","angin"],["فَتُثِيرُ","supaya mereka naikkan"],["سَحَابًۭا","(the) awan"],["فَسُقْنَـٰهُ","dan Kami memandu mereka"],["إِلَىٰ","kepada"],["بَلَدٍۢ","sebuah tanah"],["مَّيِّتٍۢ","mati"],["فَأَحْيَيْنَا","dan Kami hidupkan"],["بِهِ","dengan itu"],["ٱلْأَرْضَ","bumi"],["بَعْدَ","selepas"],["مَوْتِهَا ۚ","kematiannya"],["كَذَٰلِكَ","Demikianlah"],["ٱلنُّشُورُ","(akan menjadi) hari kiamat"]]],"3670":["(Barang siapa yang menghendaki kemuliaan, maka bagi Allahlah kemuliaan itu semuanya) di dunia dan di akhirat, maka kemuliaan itu tidak akan dapat diraih melainkan dengan jalan taat kepada-Nya, oleh karenanya taatlah kepada-Nya. (Kepada-Nyalah naik perkataan-perkataan yang baik) yang telah dipermaklumkan oleh-Nya, yaitu kalimat \"Laa Ilaaha Illallaah\", artinya, \"Tidak ada Tuhan selain Allah\", dan kalimat-kalimat yang baik lainnya (dan amal saleh dinaikkan-Nya) diterima oleh-Nya. (Dan orang-orang yang merencanakan) membuat rencana makar (kejahatan) terhadap diri Nabi di Darun Nadwah, yaitu untuk mengikatnya, atau membunuhnya atau mengusirnya, sebagaimana keterangan yang telah disebutkan dalam surah Al-Anfal (bagi mereka azab yang keras. Dan rencana jahat mereka akan hancur) yakni akan berantakan.",[["مَن","Siapa pun"],["كَانَ","[adalah] keinginan"],["يُرِيدُ","[adalah] keinginan"],["ٱلْعِزَّةَ","penghormatan"],["فَلِلَّهِ","maka untuk Allah"],["ٱلْعِزَّةُ","(ialah) Yang Mulia"],["جَمِيعًا ۚ","semua"],["إِلَيْهِ","KepadaNya"],["يَصْعَدُ","naik"],["ٱلْكَلِمُ","kata-kata"],["ٱلطَّيِّبُ","kebaikan"],["وَٱلْعَمَلُ","dan perbuatan itu"],["ٱلصَّـٰلِحُ","soleh"],["يَرْفَعُهُۥ ۚ","menaikkannya"],["وَٱلَّذِينَ","Tetapi mereka yang"],["يَمْكُرُونَ","plot"],["ٱلسَّيِّـَٔاتِ","yang jahat"],["لَهُمْ","bagi mereka"],["عَذَابٌۭ","(ialah) azab"],["شَدِيدٌۭ ۖ","teruk"],["وَمَكْرُ","dan (yang) merancang"],["أُو۟لَـٰٓئِكَ","(daripada) mereka"],["هُوَ","ia"],["يَبُورُ","(akan) binasa"]]],"3671":["(Dan Allah menciptakan kalian dari tanah) yaitu menciptakan Adam dari tanah liat (kemudian dari air mani) lalu Dia menciptakan anak cucunya dari air mani (kemudian Dia menjadikan kalian berpasang-pasang) terdiri dari kaum pria dan wanita. (Dan tidak ada seorang perempuan pun mengandung dan tidak pula melahirkan melainkan dengan sepengetahuan-Nya) lafal Bi'ilmihi berkedudukan menjadi Hal atau kata keterangan keadaan, yakni telah diketahui oleh-Nya. (Dan sekali-kali tidak dipanjangkan umur seorang yang berumur panjang) tidak diperpanjang (dan tidak pula dikurangi umurnya) yakni orang yang diberi umur panjang itu (melainkan tercatat dalam Kitab) di Lohmahfuz (Sesungguhnya yang demikian itu bagi Allah adalah mudah) amat gampang.",[["وَٱللَّهُ","Dan Allah"],["خَلَقَكُم","mencipta kamu"],["مِّن","daripada"],["تُرَابٍۢ","habuk"],["ثُمَّ","kemudian"],["مِن","daripada"],["نُّطْفَةٍۢ","titisan air mani"],["ثُمَّ","kemudian"],["جَعَلَكُمْ","Dia buat kamu"],["أَزْوَٰجًۭا ۚ","berpasangan"],["وَمَا","Dan tidak"],["تَحْمِلُ","mengandung"],["مِنْ","sebarang"],["أُنثَىٰ","perempuan"],["وَلَا","dan bukan"],["تَضَعُ","melahirkan anak"],["إِلَّا","kecuali"],["بِعِلْمِهِۦ ۚ","dengan ilmuNya"],["وَمَا","Dan tidak"],["يُعَمَّرُ","diberi nyawa"],["مِن","sebarang"],["مُّعَمَّرٍۢ","orang tua"],["وَلَا","dan bukan"],["يُنقَصُ","dikurangkan"],["مِنْ","daripada"],["عُمُرِهِۦٓ","hidupnya"],["إِلَّا","tetapi"],["فِى","(berada) dalam"],["كِتَـٰبٍ ۚ","a Daftar"],["إِنَّ","Sesungguhnya"],["ذَٰلِكَ","bahawa"],["عَلَى","bagi"],["ٱللَّهِ","Allah"],["يَسِيرٌۭ","(adalah) mudah"]]],"3672":["(Dan tiada sama -antara- dua laut; yang ini tawar, segar) sangat tawar (sedap diminum) sedap rasanya (dan yang lain asin lagi pahit) karena terlalu asin. (Dan dari masing-masing) kedua laut itu (kalian dapat memakan daging yang segar) yaitu ikan (dan kalian dapat mengeluarkan) dari laut yang asin, menurut pendapat yang lain dari laut yang tawar juga (perhiasan yang dapat kalian memakainya) yaitu berupa mutiara dan batu Marjan (dan kamu lihat) kamu dapat menyaksikan (bahtera) perahu (padanya) yakni pada masing-masing dari keduanya (dapat berlayar) dapat membelah airnya karena dapat melaju di atasnya; baik maju atau pun mundur hanya dengan satu arah angin (supaya kalian dapat mencari) berupaya mencari (karunia-Nya) karunia Allah swt. melalui berniaga dengan memakai jalan laut (dan supaya kalian bersyukur) kepada Allah atas hal tersebut.",[["وَمَا","Dan tidak"],["يَسْتَوِى","adalah sama"],["ٱلْبَحْرَانِ","dua lautan itu"],["هَـٰذَا","Ini"],["عَذْبٌۭ","(adalah) segar"],["فُرَاتٌۭ","manis"],["سَآئِغٌۭ","menyenangkan"],["شَرَابُهُۥ","minumannya"],["وَهَـٰذَا","dan ini"],["مِلْحٌ","masin"],["أُجَاجٌۭ ۖ","(dan) pahit"],["وَمِن","Dan daripada"],["كُلٍّۢ","setiap satu"],["تَأْكُلُونَ","kamu makan"],["لَحْمًۭا","daging"],["طَرِيًّۭا","segar"],["وَتَسْتَخْرِجُونَ","dan kamu ekstrak"],["حِلْيَةًۭ","perhiasan"],["تَلْبَسُونَهَا ۖ","kamu memakainya"],["وَتَرَى","dan kamu lihat"],["ٱلْفُلْكَ","kapal-kapal itu"],["فِيهِ","di dalamnya"],["مَوَاخِرَ","membelah"],["لِتَبْتَغُوا۟","supaya kamu dapat mencari"],["مِن","daripada"],["فَضْلِهِۦ","Bounty-Nya"],["وَلَعَلَّكُمْ","dan supaya kamu boleh"],["تَشْكُرُونَ","bersyukurlah"]]],"3673":["(Dia memasukkan) Allah memasukkan (malam ke dalam siang) sehingga bertambah panjanglah siang (dan memasukkan siang) (ke dalam malam) sehingga waktu malam bertambah panjang (dan menundukkan matahari dan bulan, masing-masing) dari matahari dan bulan itu (berjalan) beredar pada garis edarnya (menurut waktu yang ditentukan) yakni sampai hari kiamat. (Yang -berbuat- demikian itulah Allah Rabb kalian, kepunyaan-Nyalah kerajaan. Dan orang-orang yang kalian seru) yang kalian sembah (selain-Nya) yang dimaksud adalah berhala-berhala (tiada mempunyai apa-apa walaupun setipis kulit ari) yakni kulit yang melapisi biji.",[["يُولِجُ","Dia menyebabkan untuk masuk"],["ٱلَّيْلَ","malam"],["فِى","dalam (ke)"],["ٱلنَّهَارِ","hari itu"],["وَيُولِجُ","dan Dia memasukkannya"],["ٱلنَّهَارَ","hari itu"],["فِى","dalam (ke)"],["ٱلَّيْلِ","malam"],["وَسَخَّرَ","dan Dia telah menundukkan"],["ٱلشَّمْسَ","matahari"],["وَٱلْقَمَرَ","dan bulan"],["كُلٌّۭ","setiap satu"],["يَجْرِى","berlari"],["لِأَجَلٍۢ","untuk satu penggal"],["مُّسَمًّۭى ۚ","dilantik"],["ذَٰلِكُمُ","Itu (ialah)"],["ٱللَّهُ","Allah"],["رَبُّكُمْ","Tuhanmu"],["لَهُ","untuk Dia"],["ٱلْمُلْكُ ۚ","(ialah) Kekuasaan"],["وَٱلَّذِينَ","Dan mereka yang"],["تَدْعُونَ","kamu menyeru"],["مِن","selain Dia"],["دُونِهِۦ","selain Dia"],["مَا","tidak"],["يَمْلِكُونَ","mereka miliki"],["مِن","malah"],["قِطْمِيرٍ","(sebanyak) selaput biji kurma"]]],"3674":["(Jika kalian menyeru mereka, tiada mendengar seruanmu, dan kalau mereka mendengar) seumpamanya (mereka tidak dapat memperkenankan permintaan kalian) mereka tidak dapat memenuhi permintaan kalian. (Dan di hari kiamat mereka akan mengingkari kemusyrikan kalian) disebabkan kalian menyekutukan Allah bersama mereka. Maksudnya, mereka tidak bertanggung jawab terhadap penyembahan kalian kepada mereka (dan tidak ada yang dapat memberikan keterangan kepada kalian) tentang keadaan dua negeri yaitu dunia dan akhirat (sebagaimana yang diberikan oleh Yang Maha Mengetahui) yaitu Allah swt. sendiri.",[["إِن","Jika"],["تَدْعُوهُمْ","kamu menyeru mereka"],["لَا","tidak"],["يَسْمَعُوا۟","mereka dengar"],["دُعَآءَكُمْ","panggilan kamu"],["وَلَوْ","dan jika"],["سَمِعُوا۟","mereka dengar"],["مَا","tidak"],["ٱسْتَجَابُوا۟","mereka (akan) bertindak balas"],["لَكُمْ ۖ","kepada kamu"],["وَيَوْمَ","Dan (pada) hari"],["ٱلْقِيَـٰمَةِ","Kiamat"],["يَكْفُرُونَ","mereka akan menafikan"],["بِشِرْكِكُمْ ۚ","persatuan kamu"],["وَلَا","Dan tiada"],["يُنَبِّئُكَ","boleh maklumkan"],["مِثْلُ","suka"],["خَبِيرٍۢ","(yang) Maha Mengetahui"]]],"3675":["(Hai manusia! Kalianlah yang berkehendak kepada Allah) dalam keadaan bagaimana pun (dan Allah, Dialah Yang Maha Kaya) tidak membutuhkan makhluk-Nya (lagi Maha Terpuji) atas perbuatan-Nya terhadap mereka.",[["۞ يَـٰٓأَيُّهَا","Wahai"],["ٱلنَّاسُ","manusia"],["أَنتُمُ","kamu"],["ٱلْفُقَرَآءُ","(adalah) mereka yang memerlukan"],["إِلَى","daripada"],["ٱللَّهِ ۖ","Allah"],["وَٱللَّهُ","sedangkan Allah"],["هُوَ","Dia"],["ٱلْغَنِىُّ","(adalah) Bebas daripada keperluan"],["ٱلْحَمِيدُ","yang Terpuji"]]],"3676":["(Jika Dia menghendaki, niscaya Dia memusnahkan kalian dan mendatangkan makhluk yang baru) sebagai ganti daripada kalian.",[["إِن","Jika"],["يَشَأْ","Dia kehendaki"],["يُذْهِبْكُمْ","Dia (boleh) menghapuskan kamu"],["وَيَأْتِ","dan bawa"],["بِخَلْقٍۢ","dalam sesuatu ciptaan"],["جَدِيدٍۢ","baru"]]],"3677":["(Dan yang demikian itu sekali-kali tidak sulit bagi Allah) tidak sukar bagi-Nya.",[["وَمَا","Dan tidak"],["ذَٰلِكَ","bahawa"],["عَلَى","(berada) di atas"],["ٱللَّهِ","Allah"],["بِعَزِيزٍۢ","susah"]]],"3678":["(Dan tidaklah menanggung) setiap diri (Yang telah berbuat dosa) yakni ia tidak akan menanggung (dosa) diri (orang lain. Dan jika memanggil) seseorang yang (diberati) oleh dosanya (untuk memikul dosa itu) yaitu memanggil orang lain untuk ikut memikul sebagian dari dosanya (tiadalah akan dipikul untuknya sedikit pun) orang yang dipanggil itu tidak akan mau memikulnya walau sedikit pun (meskipun -yang dipanggil itu- kaum kerabatnya) seperti ayah dan anaknya; tidak adanya penanggungan dosa dari kedua belah pihak ini berdasarkan keputusan dari Allah. (Sesungguhnya yang dapat kamu beri peringatan hanya orang-orang yang takut kepada azab Rabbnya -sekalipun mereka tidak melihat-Nya) mereka tetap takut kepada-Nya sekalipun mereka tidak melihat-Nya, sebab hanya merekalah orang-orang yang dapat mengambil manfaat dari adanya peringatan itu (dan mereka mendirikan salat) mereka melestarikannya (Dan barang siapa yang menyucikan dirinya) dari kemusyrikan dan dosa-dosa lainnya (sesungguhnya ia menyucikan diri untuk kebaikan dirinya) karena kemaslahatannya akan kembali kepada dirinya sendiri. (Dan kepada Allahlah kembali kalian) kelak di alam akhirat Dia akan membalas amal perbuatan kalian.",[["وَلَا","Dan tidak"],["تَزِرُ","akan menanggung"],["وَازِرَةٌۭ","pembawa beban"],["وِزْرَ","bebanan"],["أُخْرَىٰ ۚ","(dari) yang lain"],["وَإِن","Dan jika"],["تَدْعُ","panggilan"],["مُثْقَلَةٌ","yang sarat berat"],["إِلَىٰ","kepada"],["حِمْلِهَا","(memikul) bebannya"],["لَا","tidak"],["يُحْمَلْ","akan dibawa"],["مِنْهُ","daripadanya"],["شَىْءٌۭ","sesuatu"],["وَلَوْ","walaupun"],["كَانَ","dia jadi"],["ذَا","saudara terdekat"],["قُرْبَىٰٓ ۗ","saudara terdekat"],["إِنَّمَا","Hanya"],["تُنذِرُ","kamu boleh memberi amaran"],["ٱلَّذِينَ","orang yang"],["يَخْشَوْنَ","bertakwa"],["رَبَّهُم","Tuhan mereka"],["بِٱلْغَيْبِ","ghaib"],["وَأَقَامُوا۟","dan menubuhkan"],["ٱلصَّلَوٰةَ ۚ","solat"],["وَمَن","Dan sesiapa"],["تَزَكَّىٰ","menyucikan dirinya"],["فَإِنَّمَا","kemudian sahaja"],["يَتَزَكَّىٰ","dia menyucikan"],["لِنَفْسِهِۦ ۚ","untuk dirinya sendiri"],["وَإِلَى","Dan kepada"],["ٱللَّهِ","Allah"],["ٱلْمَصِيرُ","(adalah) destinasi"]]],"3679":["(Dan tidaklah sama orang yang buta dengan orang yang melihat) orang kafir dan orang mukmin.",[["وَمَا","Dan tidak"],["يَسْتَوِى","sama rata"],["ٱلْأَعْمَىٰ","(adalah) orang buta"],["وَٱلْبَصِيرُ","dan yang melihat"]]],"3680":["(Dan tidak pula sama gelap gulita) yaitu kekafiran (dengan cahaya) yakni keimanan.",[["وَلَا","Dan tidak"],["ٱلظُّلُمَـٰتُ","kegelapan[es]"],["وَلَا","dan bukan"],["ٱلنُّورُ","[the] cahaya"]]],"3681":["(Dan tidak pula sama yang teduh dengan yang panas) yakni surga dan neraka.",[["وَلَا","Dan tidak"],["ٱلظِّلُّ","teduh"],["وَلَا","dan bukan"],["ٱلْحَرُورُ","panasnya"]]],"3682":["(Dan tidak pula sama orang-orang yang hidup dan orang-orang yang mati) orang-orang beriman dengan orang-orang kafir; ditambahkannya lafal Laa pada ketiga ayat di atas untuk mengukuhkan makna tidak sama. (Sesungguhnya Allah memberikan pendengaran kepada siapa yang dikehendaki-Nya) untuk mendapat hidayah, karena itu tidak beriman (dan kamu sekali-kali tiada sanggup menjadikan orang yang di dalam kubur dapat mendengar) yakni orang-orang kafir; mereka diserupakan dengan orang-orang yang telah mati, maksudnya kamu tidak akan sanggup menjadikan mereka mendengar, kemudian mereka mau menerima seruanmu.",[["وَمَا","Dan tidak"],["يَسْتَوِى","sama rata"],["ٱلْأَحْيَآءُ","(adalah) yang hidup"],["وَلَا","dan bukan"],["ٱلْأَمْوَٰتُ ۚ","yang mati"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["يُسْمِعُ","menyebabkan mendengar"],["مَن","yang"],["يَشَآءُ ۖ","Dia kehendaki"],["وَمَآ","dan bukan"],["أَنتَ","kamu"],["بِمُسْمِعٍۢ","boleh buat dengar"],["مَّن","(mereka) yang"],["فِى","(ada) dalam"],["ٱلْقُبُورِ","kubur"]]],"3683":["(Tiada lain) (kamu hanyalah seorang pemberi peringatan) terhadap mereka.",[["إِنْ","Tidak"],["أَنتَ","kamu (adalah)"],["إِلَّا","tetapi"],["نَذِيرٌ","seorang pemberi amaran"]]],"3684":["(Sesungguhnya Kami mengutus kamu dengan membawa kebenaran) yakni petunjuk (sebagai pembawa berita gembira) bagi orang yang mau menerima kebenaran itu (dan sebagai pemberi peringatan) kepada orang yang tidak mau menerimanya. (Dan tidak ada) (suatu umat pun melainkan telah ada) telah lewat (padanya seorang pemberi peringatan) nabi yang memberi peringatan kepada mereka.",[["إِنَّآ","Sesungguhnya Kami"],["أَرْسَلْنَـٰكَ","[Kami] telah menghantar kamu"],["بِٱلْحَقِّ","dengan kebenaran"],["بَشِيرًۭا","(sebagai) pembawa berita gembira"],["وَنَذِيرًۭا ۚ","dan (sebagai) pemberi amaran"],["وَإِن","Dan tidak"],["مِّنْ","(adalah) mana-mana"],["أُمَّةٍ","bangsa"],["إِلَّا","tetapi"],["خَلَا","telah berlalu"],["فِيهَا","di dalamnya"],["نَذِيرٌۭ","seorang pemberi amaran"]]],"3685":["(Dan jika mereka mendustakan kamu) yakni penduduk Mekah (maka sesungguhnya orang-orang yang sebelum mereka telah mendustakan -rasul-rasul-Nya-; kepada mereka telah datang rasul-rasul-Nya dengan membawa bukti-bukti yang nyata) yakni mukjizat-mukjizat (zubur) seperti shuhuf Nabi Ibrahim (dan Kitab yang memberi penjelasan yang sempurna) yaitu kitab Taurat dan Injil, oleh karenanya bersabarlah kamu sebagaimana mereka bersabar.",[["وَإِن","Dan jika"],["يُكَذِّبُوكَ","mereka menafikan kamu"],["فَقَدْ","maka sudah tentu"],["كَذَّبَ","dinafikan"],["ٱلَّذِينَ","orang yang"],["مِن","(ada) sebelum mereka"],["قَبْلِهِمْ","(ada) sebelum mereka"],["جَآءَتْهُمْ","Datang kepada mereka"],["رُسُلُهُم","Rasul-rasul mereka"],["بِٱلْبَيِّنَـٰتِ","dengan tanda-tanda yang jelas"],["وَبِٱلزُّبُرِ","dan dengan Kitab Suci"],["وَبِٱلْكِتَـٰبِ","dan dengan Kitab"],["ٱلْمُنِيرِ","[yang] pencerahan"]]],"3686":["(Kemudian Aku azab orang-orang yang kafir) disebabkan kedustaan mereka (maka -lihatlah- bagaimana hebatnya akibat kemurkaan-Ku) keingkaran-Ku terhadap mereka, yaitu hukuman dan kebinasaan yang menimpa mereka, hal itu benar-benar pada tempatnya.",[["ثُمَّ","Kemudian"],["أَخَذْتُ","aku rampas"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟ ۖ","kufur"],["فَكَيْفَ","dan bagaimana"],["كَانَ","adalah"],["نَكِيرِ","penolakan aku"]]],"3687":["(Tidakkah kamu melihat) mengetahui (bahwasanya Allah menurunkan hujan dari langit lalu Kami hasilkan) di dalam ungkapan ayat ini terkandung Iltifat dari dhamir Gaib (dengan hujan itu buah-buahan yang beraneka ragam jenisnya) ada yang berwarna hijau, merah dan kuning dan warna-warna lainnya. (Dan di antara gunung-gunung itu ada garis-garis) Judadun adalah bentuk jamak dari lafal Juddatun, artinya jalan yang terdapat di gunung dan lainnya (putih, merah) dan kuning (yang beraneka macam warnanya) ada yang tua dan ada yang muda (dan ada -pula yang hitam pekat) di'athafkan kepada lafal Judadun, artinya ialah batu-batu yang besar yang hitam pekat warnanya. Dikatakan Aswadu Gharbiibu, hitam pekat; tetapi sangat sedikit dikatakan Gharabiibu Aswadu.",[["أَلَمْ","Jangan"],["تَرَ","kamu lihat"],["أَنَّ","bahawa"],["ٱللَّهَ","Allah"],["أَنزَلَ","menghantar turun"],["مِنَ","daripada"],["ٱلسَّمَآءِ","langit"],["مَآءًۭ","air"],["فَأَخْرَجْنَا","kemudian Kami lahirkan"],["بِهِۦ","dengan itu"],["ثَمَرَٰتٍۢ","buah-buahan"],["مُّخْتَلِفًا","(daripada) pelbagai"],["أَلْوَٰنُهَا ۚ","warna [mereka]."],["وَمِنَ","Dan dalam"],["ٱلْجِبَالِ","pergunungan"],["جُدَدٌۢ","(adalah) risalah"],["بِيضٌۭ","putih"],["وَحُمْرٌۭ","dan merah"],["مُّخْتَلِفٌ","(daripada) pelbagai"],["أَلْوَٰنُهَا","warna [mereka]."],["وَغَرَابِيبُ","dan hitam pekat"],["سُودٌۭ","dan hitam pekat"]]],"3688":["(Dan demikian pula di antara manusia, binatang-binatang melata dan binatang-binatang ternak ada yang bermacam-macam warnanya) sebagaimana beraneka ragamnya buah-buahan dan gunung-gunung. (Sesungguhnya yang takut kepada Allah di antara hamba-hamba-Nya, hanyalah ulama) berbeda halnya dengan orang-orang yang jahil seperti orang-orang kafir Mekah. (Sesungguhnya Allah Maha Perkasa) di dalam kerajaan-Nya (lagi Maha Pengampun) terhadap dosa hamba-hamba-Nya yang mukmin.",[["وَمِنَ","Dan antara"],["ٱلنَّاسِ","lelaki"],["وَٱلدَّوَآبِّ","dan makhluk yang bergerak"],["وَٱلْأَنْعَـٰمِ","dan lembu"],["مُخْتَلِفٌ","(adalah) pelbagai"],["أَلْوَٰنُهُۥ","warna [mereka]."],["كَذَٰلِكَ ۗ","begitu juga"],["إِنَّمَا","Hanya"],["يَخْشَى","bertakwa"],["ٱللَّهَ","Allah"],["مِنْ","antara"],["عِبَادِهِ","hambanya"],["ٱلْعُلَمَـٰٓؤُا۟ ۗ","mereka yang berilmu"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["عَزِيزٌ","(adalah) Maha Perkasa"],["غَفُورٌ","Selalu Memaafkan"]]],"3689":["(Sesungguhnya orang-orang yang selalu membaca) selalu mempelajari (kitab Allah dan mendirikan salat) yakni mereka melaksanakannya secara rutin dan memeliharanya (dan menafkahkan sebagian dari rezeki yang Kami anugerahkan kepada mereka dengan diam-diam dan terang-terangan) berupa zakat dan lain-lainnya (mereka itu mengharapkan perniagaan yang tidak akan merugi) tidak bangkrut.",[["إِنَّ","Sesungguhnya"],["ٱلَّذِينَ","orang yang"],["يَتْلُونَ","mengaji"],["كِتَـٰبَ","(the) Buku"],["ٱللَّهِ","(milik) Allah"],["وَأَقَامُوا۟","dan menubuhkan"],["ٱلصَّلَوٰةَ","solat"],["وَأَنفَقُوا۟","dan berbelanja"],["مِمَّا","daripada apa"],["رَزَقْنَـٰهُمْ","Kami telah menyediakan mereka"],["سِرًّۭا","secara rahsia"],["وَعَلَانِيَةًۭ","dan secara terbuka"],["يَرْجُونَ","harapan"],["تِجَـٰرَةًۭ","(untuk) perniagaan"],["لَّن","tidak pernah"],["تَبُورَ","ia akan binasa"]]],"3690":["(Agar Allah menyempurnakan kepada mereka pahala mereka) pahala amal-amal mereka yang telah disebutkan itu (dan menambah kepada mereka dari karunia-Nya. Sesungguhnya Allah Maha Pengampun) terhadap dosa-dosa mereka (lagi Maha Mensyukuri) ketaatan mereka.",[["لِيُوَفِّيَهُمْ","Supaya Dia memberi mereka sepenuhnya"],["أُجُورَهُمْ","ganjaran mereka"],["وَيَزِيدَهُم","dan bertambah bagi mereka"],["مِّن","daripada"],["فَضْلِهِۦٓ ۚ","Bounty-Nya"],["إِنَّهُۥ","Sesungguhnya Dia"],["غَفُورٌۭ","Maha Pengampun"],["شَكُورٌۭ","Paling Menghargai"]]],"3691":["(Dan apa yang telah Kami wahyukan kepadamu yaitu Alkitab) yakni Alquran (itulah yang benar, membenarkan kitab-kitab yang sebelumnya) yang diturunkan sebelumnya. (Sesungguhnya Allah benar-benar Maha Mengetahui lagi Maha Melihat -keadaan- hamba-hamba-Nya) Dia mengetahui apa yang tersimpan di dalam kalbu mereka dan apa yang mereka lahirkan.",[["وَٱلَّذِىٓ","Dan (yang) itu"],["أَوْحَيْنَآ","Kami telah mendedahkan"],["إِلَيْكَ","kepada kamu"],["مِنَ","daripada"],["ٱلْكِتَـٰبِ","Kitab"],["هُوَ","ia"],["ٱلْحَقُّ","(adalah) kebenaran"],["مُصَدِّقًۭا","mengesahkan"],["لِّمَا","apa (ada)"],["بَيْنَ","sebelum itu"],["يَدَيْهِ ۗ","sebelum itu"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["بِعِبَادِهِۦ","dari hamba-hamba-Nya"],["لَخَبِيرٌۢ","sesungguhnya, (adalah) Maha Mengetahui"],["بَصِيرٌۭ","Maha Melihat"]]],"3692":["(Kemudian Kami wariskan) Kami berikan (Kitab itu) yakni Alquran (kepada orang-orang yang Kami pilih di antara hamba-hamba Kami) mereka adalah umatmu (lalu di antara mereka ada yang menganiaya diri mereka sendiri) karena sembrono di dalam mengamalkannya (dan di antara mereka ada yang pertengahan) dalam mengamalkannya (dan di antara mereka ada -pula- yang lebih cepat berbuat kebaikan) di samping mengamalkan Alquran, juga mempelajarinya, mengajarkannya dan membimbing orang lain untuk mengamalkannya (dengan izin Allah) dengan kehendak-Nya. (Yang demikian itu) yakni diwariskannya Alquran kepada mereka (adalah karunia yang amat besar.)",[["ثُمَّ","Kemudian"],["أَوْرَثْنَا","Kami menyebabkan untuk mewarisi"],["ٱلْكِتَـٰبَ","Kitab"],["ٱلَّذِينَ","mereka yang"],["ٱصْطَفَيْنَا","Kami telah memilih"],["مِنْ","daripada"],["عِبَادِنَا ۖ","hamba kita"],["فَمِنْهُمْ","dan antara mereka"],["ظَالِمٌۭ","(adakah dia) yang berbuat zalim"],["لِّنَفْسِهِۦ","dirinya sendiri"],["وَمِنْهُم","dan antara mereka"],["مُّقْتَصِدٌۭ","(adakah dia yang) sederhana"],["وَمِنْهُمْ","dan antara mereka"],["سَابِقٌۢ","(adakah dia yang) lebih dahulu"],["بِٱلْخَيْرَٰتِ","dalam perbuatan baik"],["بِإِذْنِ","dengan izin"],["ٱللَّهِ ۚ","(milik) Allah"],["ذَٰلِكَ","Itu"],["هُوَ","ialah"],["ٱلْفَضْلُ","Bounty"],["ٱلْكَبِيرُ","yang hebat"]]],"3693":["(Bagi mereka surga Adn) sebagai tempat tinggalnya (mereka masuk ke dalamnya) yakni ketiga golongan tersebut; lafal ayat ini dapat dibaca Yadkhuluunahaa atau Yudkhaluunahaa, berkedudukan menjadi Khabar dari Mubtada yaitu lafal Jannaatu 'Adnin (mereka diberi perhiasan) kalimat ayat ini menjadi Khabar yang kedua (di dalamnya dengan) lafal Min di sini menunjukkan makna Ba'dh atau sebagian (gelang-gelang dari emas dan dengan mutiara) yang berbingkai emas (dan pakaian mereka di dalamnya adalah sutera.)",[["جَنَّـٰتُ","Taman-taman"],["عَدْنٍۢ","(dari) Keabadian"],["يَدْخُلُونَهَا","mereka akan memasukinya"],["يُحَلَّوْنَ","Mereka akan berhias"],["فِيهَا","di dalamnya"],["مِنْ","dengan"],["أَسَاوِرَ","gelang tangan"],["مِن","daripada"],["ذَهَبٍۢ","emas"],["وَلُؤْلُؤًۭا ۖ","dan mutiara"],["وَلِبَاسُهُمْ","dan pakaian mereka"],["فِيهَا","di dalamnya"],["حَرِيرٌۭ","(akan daripada) sutera"]]],"3694":["(Dan mereka berkata, \"Segala puji bagi Allah yang telah menghilangkan duka cita dari kami.) yakni semua duka cita. (Sesungguhnya Rabb kami benar-benar Maha Pengampun) terhadap dosa-dosa kami (lagi Maha Mensyukuri) ketaatan kami.",[["وَقَالُوا۟","Dan mereka (akan) berkata"],["ٱلْحَمْدُ","Semua pujian"],["لِلَّهِ","bagi Allah"],["ٱلَّذِىٓ","yang Esa"],["أَذْهَبَ","(telah) dikeluarkan"],["عَنَّا","daripada kami"],["ٱلْحَزَنَ ۖ","kesedihan itu"],["إِنَّ","Sesungguhnya"],["رَبَّنَا","Tuhan kami"],["لَغَفُورٌۭ","(adalah) sesungguhnya Maha Pengampun"],["شَكُورٌ","Paling Menghargai"]]],"3695":["(Yang menempatkan kami dalam tempat yang kekal) sebagai tempat tinggal kami (dari karunia-Nya; di dalamnya kami tidak merasa lelah) yakni tiada merasa payah (dan tiada pula merasa lesu\") karena kecapekan, sebab di dalam surga tidak ada lagi yang namanya taklif. Disebutkannya lafal yang kedua padahal maknanya sama dengan yang pertama, dimaksud untuk lebih menegaskan kenafiannya atau ketiadaannya.",[["ٱلَّذِىٓ","Dia yang"],["أَحَلَّنَا","telah menyelesaikan kami"],["دَارَ","(dalam) Rumah"],["ٱلْمُقَامَةِ","(dari) Keabadian"],["مِن","(keluar) daripada"],["فَضْلِهِۦ","Bounty-Nya"],["لَا","Tidak"],["يَمَسُّنَا","menyentuh kita"],["فِيهَا","di dalamnya"],["نَصَبٌۭ","sebarang keletihan"],["وَلَا","dan bukan"],["يَمَسُّنَا","sentuhan"],["فِيهَا","di dalamnya"],["لُغُوبٌۭ","kepenatan"]]],"3696":["(Dan orang-orang kafir bagi mereka neraka Jahanam; mereka tidak dibinasakan) dengan dimatikan (sehingga mereka mati) yakni terbebas dari rasa sakit (dan tidak -pula- diringankan dari mereka azabnya) walau barang sekejap pun. (Demikianlah) sebagaimana Kami berikan balasan azab kepada mereka. (Kami membalas setiap orang yang sangat kafir) lafal Najziy dapat pula dibaca Yajziy; arti lafal Kafuur adalah orang kafir.",[["وَٱلَّذِينَ","Dan orang yang"],["كَفَرُوا۟","kufur"],["لَهُمْ","bagi mereka"],["نَارُ","(akan menjadi) Api"],["جَهَنَّمَ","(dari) Neraka"],["لَا","Tidak"],["يُقْضَىٰ","diputuskan"],["عَلَيْهِمْ","bagi mereka"],["فَيَمُوتُوا۟","bahawa mereka mati"],["وَلَا","dan bukan"],["يُخَفَّفُ","akan diringankan"],["عَنْهُم","bagi mereka"],["مِّنْ","daripada"],["عَذَابِهَا ۚ","azabnya"],["كَذَٰلِكَ","Demikianlah"],["نَجْزِى","Kami membalas"],["كُلَّ","setiap"],["كَفُورٍۢ","yang tidak bersyukur"]]],"3697":["(Dan mereka berteriak di dalam neraka itu) meminta tolong dengan suara yang sangat keras dan jeritan-jeritan kesakitan, seraya mengatakan, (\"Ya Rabb kami! Keluarkanlah kami) dari dalam neraka (niscaya kami akan mengerjakan amal yang saleh berlainan dengan yang telah kami kerjakan\") lalu dikatakan kepada mereka, (\"Dan apakah Kami tidak memanjangkan umur kalian dalam masa) waktu (yang cukup untuk berpikir bagi orang yang mau berpikir dan apakah tidak datang kepada kalian pemberi peringatan?\") yakni rasul tetapi kalian tidak memenuhi seruannya (maka rasakanlah -azab Kami- dan tidak ada bagi orang yang lalim) orang kafir (seorang penolong pun) yang dapat menolak azab dari diri mereka.",[["وَهُمْ","Dan mereka"],["يَصْطَرِخُونَ","akan menangis"],["فِيهَا","di dalamnya"],["رَبَّنَآ","Wahai Tuhan kami"],["أَخْرِجْنَا","Bawa kami keluar"],["نَعْمَلْ","kami akan lakukan"],["صَـٰلِحًا","benar (perbuatan)"],["غَيْرَ","selain daripada"],["ٱلَّذِى","(itu) yang"],["كُنَّا","kami gunakan"],["نَعْمَلُ ۚ","(untuk) melakukan"],["أَوَلَمْ","tidak"],["نُعَمِّرْكُم","Kami memberi kamu umur yang cukup lama"],["مَّا","bahawa"],["يَتَذَكَّرُ","(akan) menerima peringatan"],["فِيهِ","di dalamnya"],["مَن","sesiapa sahaja"],["تَذَكَّرَ","menerima teguran"],["وَجَآءَكُمُ","Dan datang kepada kamu"],["ٱلنَّذِيرُ ۖ","pemberi amaran"],["فَذُوقُوا۟","Jadi rasa"],["فَمَا","maka tidak"],["لِلظَّـٰلِمِينَ","(adalah) bagi orang-orang yang zalim"],["مِن","sebarang"],["نَّصِيرٍ","penolong"]]],"3698":["(Sesungguhnya Allah mengetahui yang tersembunyi di langit dan di bumi. Sesungguhnya Dia Maha Mengetahui segala isi hati) yang tersimpan di dalam kalbu, ini berarti bahwa pengetahuan Allah tentang hal ikhwal manusia yang lahir lebih mengetahui.",[["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["عَـٰلِمُ","(adalah) Yang Maha Mengetahui"],["غَيْبِ","(daripada) yang ghaib"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ ۚ","dan bumi"],["إِنَّهُۥ","Sesungguhnya Dia"],["عَلِيمٌۢ","(adalah) Yang Maha Mengetahui"],["بِذَاتِ","daripada apa yang ada dalam dada"],["ٱلصُّدُورِ","daripada apa yang ada dalam dada"]]],"3699":["(Dialah yang menjadikan kalian khalifah-khalifah di muka bumi) lafal Khalaa-if adalah bentuk jamak dari Khaliifah, yakni Dia mengganti sebagian di antara kalian dengan sebagian yang lain, yaitu generasi demi generasi. (Barang siapa yang kafir) di antara kalian (maka kekafirannya menimpa dirinya sendiri.) (Dan kekafiran orang-orang yang kafir itu tidak lain hanyalah akan menambah kemurkaan pada sisi Rabbnya) Dia akan bertambah murka kepadanya (dan kekafiran orang-orang yang kafir itu tidak lain hanyalah akan menambah kerugian mereka belaka) di akhirat kelak.",[["هُوَ","Dia"],["ٱلَّذِى","(ialah) Yang"],["جَعَلَكُمْ","membuat kamu"],["خَلَـٰٓئِفَ","pengganti"],["فِى","dalam"],["ٱلْأَرْضِ ۚ","bumi"],["فَمَن","Dan sesiapa"],["كَفَرَ","tidak beriman"],["فَعَلَيْهِ","kemudian ke atasnya"],["كُفْرُهُۥ ۖ","(adalah) kekufurannya"],["وَلَا","Dan tidak"],["يَزِيدُ","bertambah"],["ٱلْكَـٰفِرِينَ","orang kafir"],["كُفْرُهُمْ","kekufuran mereka"],["عِندَ","dekat"],["رَبِّهِمْ","Tuhan mereka"],["إِلَّا","kecuali"],["مَقْتًۭا ۖ","(dalam) kebencian"],["وَلَا","dan bukan"],["يَزِيدُ","bertambah"],["ٱلْكَـٰفِرِينَ","orang kafir"],["كُفْرُهُمْ","kekufuran mereka"],["إِلَّا","kecuali"],["خَسَارًۭا","(dalam) kerugian"]]],"3700":["(Katakanlah! \"Terangkanlah kepadaku tentang sekutu-sekutu kalian yang kalian seru) yang kalian sembah (selain Allah) mereka adalah berhala-berhala yang diduga oleh para pengabdinya, bahwa mereka adalah sekutu-sekutu Allah swt. (Perlihatkanlah kepadaku) terangkanlah kepadaku (bagian manakah dari bumi ini yang telah mereka ciptakan ataukah mereka mempunyai saham) yakni andil bersama Allah (di dalam) menciptakan (langit atau adakah Kami memberi kepada mereka sebuah kitab sehingga mereka mendapatkan keterangan-keterangan yang jelas) yakni hujah-hujah yang jelas (daripadanya) seumpamanya disebutkan di dalamnya, bahwa mereka adalah sekutu-sekutu-Ku yang ikut andil bersama-Ku? Tentu saja tidak. (Sebenarnya tidaklah) (orang-orang yang lalim itu menjanjikan) yakni orang-orang yang kafir (sebagian dari mereka kepada sebagian yang lain, melainkan tipuan belaka.\") kebatilan belaka, melalui perkataan mereka, bahwa berhala-berhala itu dapat memberikan syafaat kepada mereka.",[["قُلْ","Katakanlah"],["أَرَءَيْتُمْ","Pernahkah kamu melihat"],["شُرَكَآءَكُمُ","rakan kongsi kamu"],["ٱلَّذِينَ","mereka yang"],["تَدْعُونَ","kamu panggil"],["مِن","selain"],["دُونِ","selain"],["ٱللَّهِ","Allah"],["أَرُونِى","Tunjukkan Aku"],["مَاذَا","apa"],["خَلَقُوا۟","mereka telah mencipta"],["مِنَ","daripada"],["ٱلْأَرْضِ","bumi"],["أَمْ","atau"],["لَهُمْ","bagi mereka"],["شِرْكٌۭ","(adalah) bahagian"],["فِى","dalam"],["ٱلسَّمَـٰوَٰتِ","langit"],["أَمْ","Atau"],["ءَاتَيْنَـٰهُمْ","telah Kami berikan kepada mereka"],["كِتَـٰبًۭا","sebuah Buku"],["فَهُمْ","jadi mereka"],["عَلَىٰ","(ada) pada"],["بَيِّنَتٍۢ","bukti yang jelas"],["مِّنْهُ ۚ","daripadanya"],["بَلْ","Bahkan"],["إِن","tidak"],["يَعِدُ","janji"],["ٱلظَّـٰلِمُونَ","orang yang zalim"],["بَعْضُهُم","sebahagian mereka"],["بَعْضًا","(kepada) orang lain"],["إِلَّا","kecuali"],["غُرُورًا","khayalan"]]],"3701":["(Sesungguhnya Allah menahan langit dan bumi supaya jangan lenyap) mencegah keduanya agar tidak lenyap (dan sungguh jika) huruf Lam di sini bermakna Qasam (keduanya akan lenyap tidak ada yang dapat menahan keduanya seorang pun selain Allah. Sesungguhnya Dia adalah Maha Penyantun lagi Maha Pengampun) oleh karenanya Dia menangguhkan azab-Nya atas orang-orang kafir.",[["۞ إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["يُمْسِكُ","menegakkan"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضَ","dan bumi"],["أَن","jangan-jangan"],["تَزُولَا ۚ","mereka berhenti"],["وَلَئِن","Dan jika"],["زَالَتَآ","mereka harus berhenti"],["إِنْ","tidak"],["أَمْسَكَهُمَا","boleh menegakkan mereka"],["مِنْ","sebarang"],["أَحَدٍۢ","satu"],["مِّنۢ","selepas Dia"],["بَعْدِهِۦٓ ۚ","selepas Dia"],["إِنَّهُۥ","Sesungguhnya Dia"],["كَانَ","ialah"],["حَلِيمًا","Maha Penyabar"],["غَفُورًۭا","Selalu Memaafkan"]]],"3702":["(Dan mereka bersumpah) yakni orang-orang kafir Mekah (dengan nama Allah dengan sekuat-kuat sumpah) sumpah yang sungguh-sungguh (sesungguhnya jika datang kepada mereka seorang pemberi peringatan) yakni seorang rasul (niscaya mereka akan lebih mendapat petunjuk dari salah satu umat-umat yang lain) yaitu umat Yahudi, Nasrani dan umat-umat beragama lainnya. Maksudnya mereka lebih mendapat petunjuk daripada umat mana pun, karena mereka melihat adanya perselisihan di antara mereka, yaitu sebagian dari mereka mendustakan sebagian yang lain. Karena orang-orang Yahudi mengatakan, \"Orang-orang Nasrani itu tidak mempunyai suatu pegangan.\" Demikian pula orang-orang Nasrani mengatakan, \"Orang-orang Yahudi tidak mempunyai suatu pegangan.\" (Tatkala datang kepada mereka pemberi peringatan) yaitu Nabi Muhammad saw. (maka tidaklah menambah kepada mereka) kedatangan pemberi peringatan itu (melainkan jauhnya mereka dari petunjuk) mereka makin bertambah jauh dari petunjuk.",[["وَأَقْسَمُوا۟","Dan mereka bersumpah"],["بِٱللَّهِ","oleh Allah"],["جَهْدَ","(yang) terkuat"],["أَيْمَـٰنِهِمْ","(dari) sumpah mereka"],["لَئِن","bahawa jika"],["جَآءَهُمْ","datang kepada mereka"],["نَذِيرٌۭ","seorang pemberi amaran"],["لَّيَكُونُنَّ","pasti, mereka akan menjadi"],["أَهْدَىٰ","lebih terbimbing"],["مِنْ","daripada"],["إِحْدَى","sebarang"],["ٱلْأُمَمِ ۖ","(dari) bangsa-bangsa"],["فَلَمَّا","Tetapi apabila"],["جَآءَهُمْ","datang kepada mereka"],["نَذِيرٌۭ","seorang pemberi amaran"],["مَّا","tidak"],["زَادَهُمْ","ia meningkatkan mereka"],["إِلَّا","tetapi"],["نُفُورًا","(dalam) keengganan"]]],"3703":["(Karena kesombongan -mereka- di muka bumi) terhadap keimanan, mereka tidak mau beriman karena sombong. Lafal ayat ini menjadi Maf'ul Lah (dan karena rencana) pekerjaan mereka (yang jahat) berupa kemusyrikan dan lain-lainnya. (Dan tidaklah menimpa) tidak menggilas (rencana jahat itu selain orang yang merencanakannya sendiri) yaitu orang yang mengadakan makar itu sendiri. Lafal Al Makru diberi sifat As Sayyi-u adalah bentuk asal tetapi di-mudhaf-kan-nya lafal Al Makru kepada lafal As Sayyi-u, menurut suatu pendapat merupakan cara pemakaian yang lain tetapi dengan memperkirakan adanya Mudhaf yang lain supaya jangan langsung di-mudhaf-kan kepada sifat. (Tiadalah yang mereka nanti-nantikan) (melainkan, berlakunya, sunah, Allah yang telah berlaku, kepada orang-orang yang dahulu) yaitu diturunkannya azab atas mereka sebab mereka mendustakan rasul-rasul-Nya. (Maka sekali-kali kamu tidak akan menemui perubahan bagi sunah Allah dan sekali-kali tidak pula akan menemui penyimpangan bagi sunah Allah itu) azab itu tidak dapat diganti dengan yang lain dan tidak ditimpakan kepada orang-orang yang tidak berhak menerimanya.",[["ٱسْتِكْبَارًۭا","(Disebabkan) kesombongan"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["وَمَكْرَ","dan merancang"],["ٱلسَّيِّئِ ۚ","(dari) kejahatan"],["وَلَا","tetapi tidak"],["يَحِيقُ","merangkumi"],["ٱلْمَكْرُ","plot"],["ٱلسَّيِّئُ","(dari) kejahatan"],["إِلَّا","kecuali"],["بِأَهْلِهِۦ ۚ","rakyatnya sendiri"],["فَهَلْ","Kemudian lakukan"],["يَنظُرُونَ","mereka menunggu"],["إِلَّا","kecuali"],["سُنَّتَ","jalan"],["ٱلْأَوَّلِينَ ۚ","(dari) orang-orang dahulu"],["فَلَن","Tetapi tidak pernah"],["تَجِدَ","kamu akan dapati"],["لِسُنَّتِ","dalam (cara)."],["ٱللَّهِ","(milik) Allah"],["تَبْدِيلًۭا ۖ","sebarang perubahan"],["وَلَن","dan tidak pernah"],["تَجِدَ","kamu akan dapati"],["لِسُنَّتِ","dalam (cara)."],["ٱللَّهِ","(milik) Allah"],["تَحْوِيلًا","sebarang perubahan"]]],"3704":["(Dan apakah mereka tidak berjalan di muka bumi, lalu melihat bagaimana kesudahan orang-orang yang sebelum mereka, sedangkan orang-orang itu adalah lebih besar kekuatannya dari mereka?) maka Allah tetap membinasakan mereka karena mereka telah mendustakan rasul-rasul mereka. (Dan tiada sesuatu pun yang dapat melemahkan Allah) yang dapat mendahului-Nya dan dapat meloloskan diri dari azab-Nya (baik di langit maupun di bumi. Sesungguhnya Allah Maha Mengetahui) segala sesuatu (lagi Maha Kuasa) atas semuanya.",[["أَوَلَمْ","Adakah mereka tidak"],["يَسِيرُوا۟","mengembara"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["فَيَنظُرُوا۟","dan dilihat"],["كَيْفَ","bagaimana"],["كَانَ","adalah"],["عَـٰقِبَةُ","(akhirnya)."],["ٱلَّذِينَ","orang yang"],["مِن","(ada) sebelum mereka"],["قَبْلِهِمْ","(ada) sebelum mereka"],["وَكَانُوٓا۟","Dan mereka"],["أَشَدَّ","lebih kuat"],["مِنْهُمْ","daripada mereka"],["قُوَّةًۭ ۚ","(dalam) kuasa"],["وَمَا","Tetapi tidak"],["كَانَ","ialah"],["ٱللَّهُ","Allah"],["لِيُعْجِزَهُۥ","yang dapat melepaskan diri (dari)Nya"],["مِن","sebarang"],["شَىْءٍۢ","perkara"],["فِى","dalam"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَلَا","dan bukan"],["فِى","dalam"],["ٱلْأَرْضِ ۚ","bumi"],["إِنَّهُۥ","Sesungguhnya Dia"],["كَانَ","ialah"],["عَلِيمًۭا","Maha Mengetahui"],["قَدِيرًۭا","Maha Berkuasa"]]],"3705":["(Dan kalau sekiranya Allah swt. menyiksa manusia disebabkan usahanya) karena maksiat-maksiat yang telah dikerjakannya (niscaya Dia tidak akan meninggalkan di atas permukaan bumi (suatu makhluk pun) yang hidup merayap di atasnya (akan tetapi Allah menangguhkan penyiksaan mereka, sampai waktu yang tertentu) yakni hari kiamat (maka apabila datang ajal mereka, maka sesungguhnya Allah adalah Maha Melihat keadaan hamba-hamba-Nya) Dia kelak akan membalas amal perbuatan mereka, yaitu dengan memberi pahala kepada orang-orang yang beriman dan menghukum orang-orang yang kafir.",[["وَلَوْ","Dan jika"],["يُؤَاخِذُ","Allah (akan) mengazab"],["ٱللَّهُ","Allah (akan) mengazab"],["ٱلنَّاسَ","manusia"],["بِمَا","bagi apa"],["كَسَبُوا۟","mereka telah perolehi"],["مَا","tidak"],["تَرَكَ","Dia akan pergi"],["عَلَىٰ","pada"],["ظَهْرِهَا","belakangnya"],["مِن","sebarang"],["دَآبَّةٍۢ","makhluk"],["وَلَـٰكِن","Tetapi"],["يُؤَخِّرُهُمْ","Dia memberi mereka tangguh"],["إِلَىٰٓ","sehingga"],["أَجَلٍۢ","satu istilah"],["مُّسَمًّۭى ۖ","dilantik"],["فَإِذَا","Dan apabila"],["جَآءَ","datang"],["أَجَلُهُمْ","istilah mereka"],["فَإِنَّ","maka sesungguhnya"],["ٱللَّهَ","Allah"],["كَانَ","ialah"],["بِعِبَادِهِۦ","dari hamba-hamba-Nya"],["بَصِيرًۢا","Maha Melihat"]]],"3706":["(Yaa siin) hanya Allahlah yang mengetahui maksudnya.",[["يسٓ","Ya Seen"]]],"3707":["(Demi Alquran yang penuh hikmah) yang padat dengan hikmah-hikmah, susunan kata-katanya amat mengagumkan dan makna-maknanya sangat indah lagi memukau.",[["وَٱلْقُرْءَانِ","Oleh al-Quran"],["ٱلْحَكِيمِ","yang Bijaksana"]]],"3708":["(Sesungguhnya kamu) hai Muhammad (salah seorang dari rasul-rasul.)",[["إِنَّكَ","Sesungguhnya kamu"],["لَمِنَ","(adalah) antara"],["ٱلْمُرْسَلِينَ","para Rasul"]]],"3709":["(Yang berada di atas) berta'alluq kepada ayat sebelumnya (jalan yang lurus) jalannya para nabi sebelum kamu, yaitu jalan tauhid dan hidayah. Ungkapan yang memakai kata pengukuh sumpah dan pengukuh lainnya, dimaksud sebagai sanggahan terhadap perkataan orang-orang kafir yang ditujukan kepada Nabi Muhammad, yaitu sebagaimana yang disitir oleh firman-Nya, \"Kamu bukan seorang yang dijadikan rasul.\" (Q.S. Ar-Ra'd 43.)",[["عَلَىٰ","hidup"],["صِرَٰطٍۢ","a Laluan"],["مُّسْتَقِيمٍۢ","Lurus"]]],"3710":["(Sebagai wahyu yang diturunkan oleh Yang Maha Perkasa) di dalam kerajaan-Nya (lagi Maha Penyayang) kepada makhluk-Nya. Khabar dari Mubtada diperkirakan keberadaannya, yaitu lafal Alquran. Maksudnya, Alquran ini sebagai wahyu yang diturunkan.",[["تَنزِيلَ","Satu wahyu"],["ٱلْعَزِيزِ","(dari) Yang Maha Perkasa"],["ٱلرَّحِيمِ","Yang Maha Mengasihani"]]],"3711":["(Agar kamu memberi peringatan) dengan Alquran itu (kepada kaum) lafal Litundzira berta'alluq kepada lafal Tanziilun (yang bapak-bapak mereka belum pernah diberi peringatan) mereka belum pernah diberi peringatan karena hidup di zaman fatrah atau zaman kekosongan nabi dan rasul (karena itu mereka) yakni kaum itu (dalam keadaan lalai) lalai dari iman dan petunjuk.",[["لِتُنذِرَ","Supaya kamu boleh memberi amaran"],["قَوْمًۭا","suatu kaum"],["مَّآ","tidak"],["أُنذِرَ","telah diberi amaran"],["ءَابَآؤُهُمْ","nenek moyang mereka"],["فَهُمْ","jadi mereka"],["غَـٰفِلُونَ","(adalah) lalai"]]],"3712":["(Sesungguhnya telah pasti berlaku perkataan) yakni ketentuan Allah telah pasti (terhadap kebanyakan mereka) yakni azab-Nya telah pasti atas mereka (karena mereka tidak beriman) kebanyakan dari mereka tidak beriman.",[["لَقَدْ","Sungguh"],["حَقَّ","(telah) terbukti benar"],["ٱلْقَوْلُ","perkataan itu"],["عَلَىٰٓ","ke atas"],["أَكْثَرِهِمْ","kebanyakan mereka"],["فَهُمْ","jadi mereka"],["لَا","jangan"],["يُؤْمِنُونَ","beriman"]]],"3713":["(Sesungguhnya Kami telah memasang belenggu di leher mereka) tangan mereka disatukan dengan leher mereka dalam satu belenggu, karena pengertian lafal Al-Ghillu ialah mengikatkan kedua tangan ke leher (lalu tangan mereka) yaitu tangan-tangan mereka diangkat dan disatukan (ke dagu) mereka, lafal Adzqaan bentuk jamak dari lafal Dzaqanun yaitu tempat tumbuh janggut (maka karena itu mereka tertengadah) kepala mereka terangkat dan tidak dapat ditundukkan. Ini merupakan tamtsil, yang dimaksud ialah mereka tidak mau taat untuk beriman, dan mereka sama sekali tidak mau menundukkan kepalanya dalam arti kata tidak mau beriman.",[["إِنَّا","Sesungguhnya Kami"],["جَعَلْنَا","[Kami] telah meletakkan"],["فِىٓ","pada"],["أَعْنَـٰقِهِمْ","leher mereka"],["أَغْلَـٰلًۭا","kolar besi"],["فَهِىَ","dan mereka"],["إِلَى","(terserah) kepada"],["ٱلْأَذْقَانِ","dagu"],["فَهُم","jadi mereka"],["مُّقْمَحُونَ","(ada dengan) kepala terangkat"]]],"3714":["(Dan Kami adakan di hadapan mereka dinding dan di belakang mereka dinding) lafal Saddan dalam dua tempat tadi boleh dibaca Suddan (dan Kami tutup -mata- mereka sehingga mereka tidak dapat melihat.) Ini merupakan tamtsil yang menggambarkan tertutupnya jalan iman bagi mereka.",[["وَجَعَلْنَا","Dan Kami telah menjadikan"],["مِنۢ","daripada"],["بَيْنِ","sebelum/antara"],["أَيْدِيهِمْ","tangan mereka/depan mereka"],["سَدًّۭا","penghalang"],["وَمِنْ","dan daripada"],["خَلْفِهِمْ","belakang mereka"],["سَدًّۭا","penghalang"],["فَأَغْشَيْنَـٰهُمْ","dan Kami menutupi mereka"],["فَهُمْ","jadi mereka"],["لَا","jangan"],["يُبْصِرُونَ","lihat"]]],"3715":["(Sama saja bagi mereka apakah kamu memberi peringatan kepada mereka) dapat dibaca Tahqiq dan dapat pula dibaca Tas-hil (ataukah kamu tidak memberi peringatan kepada mereka, mereka tidak akan beriman.)",[["وَسَوَآءٌ","Dan ia (adalah) sama"],["عَلَيْهِمْ","kepada mereka"],["ءَأَنذَرْتَهُمْ","sama ada kamu memberi amaran kepada mereka"],["أَمْ","atau"],["لَمْ","jangan"],["تُنذِرْهُمْ","memberi amaran kepada mereka"],["لَا","tidak"],["يُؤْمِنُونَ","mereka akan beriman"]]],"3716":["(Sesungguhnya Kamu hanya dapat memperingati) yakni akan dapat mengambil manfaat dari peringatanmu (orang yang mau mengikuti peringatan) petunjuk Alquran (dan yang takut kepada Tuhan Yang Maha Pemurah walaupun Dia tidak melihat-Nya) yakni ia tetap takut kepada-Nya sekalipun ia tidak melihat-Nya. (Maka berilah ia kabar gembira dengan ampunan dan pahala yang mulia) yaitu mendapat surga.",[["إِنَّمَا","Hanya"],["تُنذِرُ","kamu (boleh) memberi amaran"],["مَنِ","(dia) siapa"],["ٱتَّبَعَ","mengikuti"],["ٱلذِّكْرَ","Peringatan itu"],["وَخَشِىَ","dan ketakutan"],["ٱلرَّحْمَـٰنَ","Yang Maha Pemurah"],["بِٱلْغَيْبِ ۖ","dalam ghaib"],["فَبَشِّرْهُ","Maka berilah dia berita gembira"],["بِمَغْفِرَةٍۢ","daripada pengampunan"],["وَأَجْرٍۢ","dan ganjaran"],["كَرِيمٍ","mulia"]]],"3717":["(Sesungguhnya Kami menghidupkan orang-orang mati) yakni menghidupkannya kembali (dan Kami menuliskan) di Lohmahfuz (apa yang telah mereka kerjakan) selama hidup di dunia berupa kebaikan dan keburukan, lalu Kami membalasnya kepada mereka (dan bekas-bekas yang mereka tinggalkan) hal-hal yang dijadikan panutan dari perbuatan mereka sesudah mereka tiada (serta segala sesuatu) dinashabkannya lafal Kulla oleh pengaruh Fiil atau kata kerja yang menjelaskannya, yaitu kalimat berikutnya (Kami catat) Kami kumpulkan satu persatu secara mendetail (di dalam kitab induk yang nyata) yaitu di Lohmahfuz.",[["إِنَّا","Sesungguhnya Kami"],["نَحْنُ","[Kami]"],["نُحْىِ","[Kami] memberi kehidupan"],["ٱلْمَوْتَىٰ","(kepada) orang mati"],["وَنَكْتُبُ","dan Kami merekodkan"],["مَا","apa"],["قَدَّمُوا۟","mereka telah menghantar sebelum ini"],["وَءَاثَـٰرَهُمْ ۚ","dan tapak kaki mereka"],["وَكُلَّ","dan setiap"],["شَىْءٍ","perkara"],["أَحْصَيْنَـٰهُ","Kami telah menghitungnya"],["فِىٓ","dalam"],["إِمَامٍۢ","a Daftar"],["مُّبِينٍۢ","yang nyata"]]],"3718":["(Dan buatlah) adakanlah (buat mereka suatu perumpamaan) lafal Matsalan adalah Maf'ul Awal (yaitu penduduk) lafal Ashhaaba ini menjadi Maf'ul yang kedua (suatu negeri) yaitu kota Inthakiah (ketika datang kepada mereka) lafal ayat ini sampai akhir ayat berkedudukan menjadi Badal Isytimal dari lafal Ashhaabal Qaryah (utusan-utusan) utusan-utusan Nabi Isa.",[["وَٱضْرِبْ","Dan ditetapkan"],["لَهُم","kepada mereka"],["مَّثَلًا","satu contoh"],["أَصْحَـٰبَ","(daripada) para sahabat"],["ٱلْقَرْيَةِ","(dari) bandar itu"],["إِذْ","apabila"],["جَآءَهَا","datang kepadanya"],["ٱلْمُرْسَلُونَ","para Rasul"]]],"3719":["(Yaitu ketika Kami mengutus kepada mereka dua orang utusan, lalu mereka mendustakan keduanya) ayat ini seluruhnya berkedudukan sebagai Badal dari lafal Idz yang pertama (kemudian Kami kuatkan) kedua utusan itu; lafal ayat ini dapat dibaca Takhfif sehingga bunyinya menjadi Fa'azaznaa dapat pula dibaca Tasydid, sehingga bunyinya menjadi Fa'azzaznaa (dengan -utusan- yang ketiga, maka ketiga utusan itu berkata, \"Sesungguhnya kami adalah orang-orang yang diutus kepada kalian.\")",[["إِذْ","Apabila"],["أَرْسَلْنَآ","Kami utus"],["إِلَيْهِمُ","kepada mereka"],["ٱثْنَيْنِ","dua (Rasul)"],["فَكَذَّبُوهُمَا","tetapi mereka menafikan kedua-duanya"],["فَعَزَّزْنَا","maka Kami kuatkan mereka"],["بِثَالِثٍۢ","dengan satu pertiga"],["فَقَالُوٓا۟","dan mereka berkata"],["إِنَّآ","Sesungguhnya Kami"],["إِلَيْكُم","kepada kamu"],["مُّرْسَلُونَ","(adalah) Rasul-rasul"]]],"3720":["(Mereka menjawab, \"Kalian tidak lain hanyalah manusia seperti kami dan Allah Yang Maha Pemurah tidak menurunkan sesuatu pun. Tidak lain) (kalian hanyalah pendusta belaka.\")",[["قَالُوا۟","Mereka berkata"],["مَآ","Tidak"],["أَنتُمْ","kamu"],["إِلَّا","(adalah) tetapi"],["بَشَرٌۭ","manusia"],["مِّثْلُنَا","seperti kita"],["وَمَآ","dan bukan"],["أَنزَلَ","telah mendedahkan"],["ٱلرَّحْمَـٰنُ","Yang Maha Pemurah"],["مِن","sebarang"],["شَىْءٍ","perkara"],["إِنْ","Tidak"],["أَنتُمْ","kamu"],["إِلَّا","(adalah) tetapi"],["تَكْذِبُونَ","berbohong"]]],"3721":["(Mereka berkata, \"Rabb kami mengetahui) kalimat ayat ini mengandung makna qasam, kemudian pengukuhannya ditambah dengan adanya huruf Lam pada lafal Lamursaluuna, sebagai sanggahan terhadap perkataan mereka (bahwa sesungguhnya kami adalah orang-orang yang diutus kepada kalian.)",[["قَالُوا۟","Mereka berkata"],["رَبُّنَا","Wahai Tuhan kami"],["يَعْلَمُ","mengetahui"],["إِنَّآ","bahawa kita"],["إِلَيْكُمْ","kepada kamu"],["لَمُرْسَلُونَ","(adalah) sesungguhnya Rasul-rasul"]]],"3722":["(Dan kewajiban kami tidak lain hanyalah menyampaikan -perintah Allah- dengan jelas\") menyampaikan yang jelas dan gamblang melalui mukjizat-mukjizat yang terang, yaitu dapat menyembuhkan orang buta, yang berpenyakit supak, dan dapat menghidupkan orang mati.",[["وَمَا","Dan tidak"],["عَلَيْنَآ","(ada) pada kita"],["إِلَّا","kecuali"],["ٱلْبَلَـٰغُ","pengangkutan itu"],["ٱلْمُبِينُ","yang nyata"]]],"3723":["(Mereka menjawab, \"Sesungguhnya kami bernasib malang) mengalami kesialan (karena kalian) kami mengalami kekeringan dan tidak pernah turun hujan sebab ada kalian (sesungguhnya jika) huruf Lam di sini bermakna qasam (kalian tidak berhenti -menyeru kami-, niscaya kami akan merajam kalian) dengan batu-batu (dan kalian pasti akan mendapat siksa yang pedih dari kami.\") siksa yang menyakitkan.",[["قَالُوٓا۟","Mereka berkata"],["إِنَّا","Sesungguhnya kami"],["تَطَيَّرْنَا","[kita] melihat petanda jahat"],["بِكُمْ ۖ","daripada kamu"],["لَئِن","Jika"],["لَّمْ","tidak"],["تَنتَهُوا۟","kamu berhenti"],["لَنَرْجُمَنَّكُمْ","pasti, kami akan merejam kamu"],["وَلَيَمَسَّنَّكُم","dan pasti akan menyentuh kamu"],["مِّنَّا","daripada kami"],["عَذَابٌ","azab"],["أَلِيمٌۭ","yang pedih"]]],"3724":["(Utusan-utusan itu berkata, \"Kemalangan kalian) yakni kesialan kalian itu (adalah karena kalian sendiri\") disebabkan ulah kalian sendiri karena kafir. (Apakah jika) Hamzah Istifham digabungkan dengan In Syarthiyah, keduanya dapat dibaca Tahqiq, dan dapat pula dibaca Tas-hil (kalian diberi peringatan) yakni diberi nasihat dan peringatan; jawab Syarath tidak disebutkan. Lengkapnya ialah apakah jika kalian diberi peringatan lalu kalian bernasib sial karenanya lalu kalian kafir? Pengertian terakhir inilah objek daripada Istifham atau kata tanya. Makna yang dimaksud adalah sebagai cemoohan terhadap mereka. (Sebenarnya kalian adalah kaum yang melampaui batas) karena kemusyrikan kalian.",[["قَالُوا۟","Mereka berkata"],["طَـٰٓئِرُكُم","petanda jahat kamu"],["مَّعَكُمْ ۚ","(berada) bersama kamu"],["أَئِن","Adakah kerana"],["ذُكِّرْتُم ۚ","kamu dinasihatkan"],["بَلْ","Bahkan"],["أَنتُمْ","kamu"],["قَوْمٌۭ","(adalah) suatu kaum"],["مُّسْرِفُونَ","melanggar"]]],"3725":["(Dan datanglah dari ujung kota seorang laki-laki) Habib An Najjar atau Habib si tukang kayu; dia telah beriman kepada utusan-utusan Nabi Isa, dan tempat tinggalnya berada di ujung kota Inthakiyah (dengan bergegas-gegas) lari dengan cepat, tatkala ia mendengar berita bahwa kaumnya mendustakan utusan-utusan itu (ia berkata, \"Hai kaumku! Ikutilah utusan-utusan itu.)",[["وَجَآءَ","Dan datang"],["مِنْ","daripada"],["أَقْصَا","(hujung) yang paling jauh"],["ٱلْمَدِينَةِ","(dari) bandar itu"],["رَجُلٌۭ","seorang lelaki"],["يَسْعَىٰ","berlari"],["قَالَ","Dia berkata"],["يَـٰقَوْمِ","Wahai Umatku"],["ٱتَّبِعُوا۟","Ikut"],["ٱلْمُرْسَلِينَ","para Rasul"]]],"3726":["(Ikutilah) lafal ayat ini mengukuhkan makna lafal yang sama pada ayat sebelumnya (orang yang tiada minta balasan kepada kalian) atas misi risalah yang disampaikannya itu (dan mereka adalah orang-orang yang mendapat petunjuk) lalu dikatakan kepadanya, \"Kamu seagama dengan mereka.\"",[["ٱتَّبِعُوا۟","Ikut"],["مَن","(mereka) yang"],["لَّا","jangan"],["يَسْـَٔلُكُمْ","meminta (dari) kamu"],["أَجْرًۭا","sebarang bayaran"],["وَهُم","dan mereka"],["مُّهْتَدُونَ","(adalah) mendapat petunjuk"]]],"3727":["Lalu laki-laki itu berkata, (\"Mengapa aku tidak menyembah -Tuhan- yang telah menciptakan aku) yang telah menjadikan aku. Maksudnya, tidak ada yang mencegahku untuk menyembah-Nya, karena ada bukti-buktinya yang jelas, seharusnya kalian menyembah Dia (dan hanya kepada-Nya kalian semua akan dikembalikan?) sesudah mati, kemudian Dia akan membalas kekafiran kalian itu.",[["وَمَا","Dan apa"],["لِىَ","(adalah) untuk aku"],["لَآ","(itu) tidak"],["أَعْبُدُ","aku menyembah"],["ٱلَّذِى","yang Esa"],["فَطَرَنِى","mencipta aku"],["وَإِلَيْهِ","dan kepada Siapa"],["تُرْجَعُونَ","kamu akan dikembalikan"]]],"3728":["(Mengapa aku akan menjadikan) Istifham atau kata tanya di sini mengandung arti kalimat negatif; dan lafal ayat ini sama dengan lafal A-andzartahum tadi, yaitu dapat dibaca Tahqiq dan Tashil (selain Allah) yakni selain-Nya (sebagai tuhan-tuhan -yang disembah-) maksudnya berhala-berhala (jika Allah Yang Maha Pemurah menghendaki kemudaratan terhadapku, niscaya syafaat mereka tidak memberi manfaat sedikit pun bagi diriku) seperti yang kalian dugakan itu (dan mereka tidak -pula- dapat menyelamatkanku) lafal ayat ini menjadi sifat bagi lafal Aalihatan.",[["ءَأَتَّخِذُ","Patutkah aku ambil"],["مِن","selain Dia"],["دُونِهِۦٓ","selain Dia"],["ءَالِهَةً","tuhan"],["إِن","Jika"],["يُرِدْنِ","berniat untuk aku"],["ٱلرَّحْمَـٰنُ","Yang Maha Pemurah"],["بِضُرٍّۢ","sebarang kemudaratan"],["لَّا","tidak"],["تُغْنِ","akan mendapat manfaat"],["عَنِّى","[dari] aku"],["شَفَـٰعَتُهُمْ","syafaat mereka"],["شَيْـًۭٔا","(dalam) apa-apa"],["وَلَا","dan bukan"],["يُنقِذُونِ","mereka (boleh) menyelamatkan aku"]]],"3729":["(Sesungguhnya aku kalau begitu) seandainya aku menyembah selain Allah (berada dalam kesesatan yang nyata) benar-benar sesat.",[["إِنِّىٓ","Sesungguhnya aku"],["إِذًۭا","kemudian"],["لَّفِى","pasti akan masuk"],["ضَلَـٰلٍۢ","satu kesilapan"],["مُّبِينٍ","yang nyata"]]],"3730":["(Sesungguhnya aku telah beriman kepada Rabb kalian, maka dengarkanlah pengakuan keimananku.\") dengarkanlah perkataanku ini. Lalu mereka merajamnya hingga mati.",[["إِنِّىٓ","Sesungguhnya aku"],["ءَامَنتُ","[Aku] telah beriman"],["بِرَبِّكُمْ","pada Tuhanmu"],["فَٱسْمَعُونِ","jadi dengar cakap aku"]]],"3731":["(Dikatakan) kepadanya sesudah ia mati, (\"Masuklah ke surga\") menurut suatu pendapat dikatakan, bahwa Habib An Najjar itu masuk ke dalam surga dalam keadaan hidup. (Ia berkata, \"Aduhai!) huruf Ya di sini menunjukkan makna tanbih atau penyesalan (sekiranya kaumku mengetahui.)",[["قِيلَ","Dikatakan"],["ٱدْخُلِ","Masuk"],["ٱلْجَنَّةَ ۖ","Syurga"],["قَالَ","Dia berkata"],["يَـٰلَيْتَ","aku harap"],["قَوْمِى","bangsaku"],["يَعْلَمُونَ","tahu"]]],"3732":["(Apa yang menyebabkan Rabbku memberi ampun kepadaku) yakni penyebab Allah memberikan ampunan kepadanya (dan menjadikan aku termasuk orang-orang yang dimuliakan.\")",[["بِمَا","Bagaimana"],["غَفَرَ","telah memaafkan"],["لِى","aku"],["رَبِّى","Tuhanku"],["وَجَعَلَنِى","dan meletakkan aku"],["مِنَ","antara"],["ٱلْمُكْرَمِينَ","yang dihormati"]]]});